INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at) VALUES ('deck_rin_skinned', '【高定美化】雨夜便利店的离家少女 · 霓虹幻梦高定版', '🔥 正则+内置CSS · 高定美化版', '🍧', '雨夜便利店的离家少女', '正则替换打标 + 霓虹赛博胶片皮肤 + 防挤行排版', '🍧', 'pink', 'from-pink-600 via-rose-500 to-amber-500', '{"audience": ["追求视觉精致感、拟真二次元互动与高定制皮肤美学的沉浸派玩家"], "tips": ["【正则管道实装】：AI输出的details与suggested_questions已被自动挂载rin-panel与rin-suggest类名。", "【内置CSS质感】：享受暗夜霓虹雨夜玻璃质感、悬浮微发光与分行自适应。", "【随时对比】：可在顶部随时一键切回【原始白模版】感受反差。"], "quote": "“别看了……我没有偷东西，只是在避雨而已。买得起关东煮的钱我还是有的。”"}', '[{"name": "星野凛 (Hoshino Rin)", "role": "女主角 · 离家出走的高二少女", "desc": "17岁，原本是私立名校的优等生，因无法承受母亲窒息的高压掌控，在暴雨夜砸碎了存钱罐离家出走。全身湿透，穿着打湿的水手服，神情像一只受惊却呲牙防备的野猫。", "avatar": "https://api.dicebear.com/7.x/bottts/svg?seed=rin_skinned"}, {"name": "值班店员 / 避难者", "role": "玩家视角", "desc": "深夜两点在全家便利店值班的年轻店员，面对这个缩在垃圾桶旁和关东煮货架夹缝中发抖的陌生少女。", "avatar": "https://api.dicebear.com/7.x/bottts/svg?seed=clerk"}]', '[{"name": "深夜2:15 全家便利店靠窗散座", "desc": "外侧暴雨如注，霓虹灯被雨水晕染成模糊的光晕。便利店冷气很足，关东煮冒着微弱的热气。"}]', '["二次元冷调文学", "正则打标高定皮肤", "拟真微表情动态"]', '{"status": "【状态：凌晨02:15 暴雨夜 | 凛的体温：失温颤抖 | 警惕度：90%（随时准备逃跑） | 食物：一碗快凉掉的白萝卜和魔芋丝】", "story": "凌晨两点十五分，暴雨疯狂砸在便利店巨大的落地玻璃窗上，将街对面的霓虹招牌冲刷成一片斑驳扭曲的色块。\n\n门上的电子迎宾铃「叮咚——欢迎光临」已经三个小时没有响过了。店内老旧的空调送风口正呼呼地吐着冷气，空气里弥漫着关东煮高汤和廉价关东煮蒸发出来的甜咸气味。\n\n在靠窗最狭窄的垃圾分类桶旁边，那个一个小时前冲进来的少女依旧缩在塑料圆凳上。\n\n她浑身都湿透了。藏青色的水手服短裙黏在白皙却冻得发青的大腿上，额前被雨水打湿的齐刘海下一双杏眼死死盯着面前那碗早已不再冒热气的关东煮。在她脚边，一个掉漆的帆布双肩包正不断往地板砖上滴着水，洇开了一大片水渍。\n\n当你端着热茶走近时，她像被踩到尾巴的野猫一样猛地瑟缩了一下身子，纤细的手指一把抓紧了双肩包的肩带，苍白的嘴唇抿成一条紧绷的直线：\n\n「别过来……！\n我、我买了关东煮的，小票还在桌子上！我没有霸占你们的座位，等雨停了……雨停了我马上就走！」\n\n她说话时牙齿在轻微打颤，湿漉漉的黑色水手服领口下，那根褪色的红领巾随着她急促的呼吸微微起伏。她显然在竭力维持着凶狠冷淡的防备姿态，可冻得发红的鼻尖和眼眶里的湿气却出卖了她此刻的无助。", "rawOutputSnippet": "<details>\n<summary>📊 实时物理与心理状态</summary>\n- 当前位置：便利店靠窗角落塑料凳\n- 衣着状态：水手服全湿（黏在皮肤上）\n- 体能状态：轻度失温，双肩微颤\n- 心理防备：90%（将店员视作潜在驱赶者或警察同伙）\n- 随身物品：湿透的双肩包（含学生证、存钱罐碎银与未关机的手机）\n</details>\n\n<suggested_questions>\n【递毛巾】：“擦擦吧，制服全湿了会着凉的。我不会赶你走。”\n【送热关东煮】：“这碗已经凉了，我帮你换一份刚煮好的热高汤吧。”\n【试探询问】：“现在已经凌晨两点了，给家里人报个平安比较好哦。”\n【保持距离】：“我就在前台，有需要的话随时喊我。”\n</suggested_questions>", "userAction": "我从柜台拿了一条干净的员工毛巾和一杯热大麦茶，没有直接走近，而是隔着一个座位的距离轻轻放下：“毛巾是干净的，大麦茶免费，你先擦擦头发吧。”", "actionChoices": ["【递毛巾】：“擦擦吧，制服全湿了会着凉的。我不会赶你走。”", "【送热关东煮】：“这碗已经凉了，我帮你换一份刚煮好的热高汤吧。”", "【试探询问】：“现在已经凌晨两点了，给家里人报个平安比较好哦。”", "【保持距离】：“我就在前台，有需要的话随时喊我。”"]}', NULL, '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>【高定美化】雨夜便利店的离家少女 · 霓虹幻梦高定版</title>
<link href="https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;600;700&display=swap" rel="stylesheet">
<style>
    :root{
        --soft-white:#ffffff;
        --cream-bg:#fdfcf8;
        --accent-gold:#d4a373;
        --accent-purple:#9d8ec7;
        --text-dark:#2d2d2d;
        --text-gray:#6d6d6d;
        --border-color:#efe6ff;
        --shadow:0 12px 42px rgba(120,90,160,0.10);
