        border:1px solid var(--border-color);
        box-shadow:var(--shadow);
        margin-bottom:24px;
        overflow:hidden;
    }
    .hero-tag{
        position:relative;
        display:inline-block;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:#7c6bb0;
        padding:7px 20px;
        border-radius:999px;
        font-size:12.5px;
        letter-spacing:3px;
        font-weight:600;
        border:1px solid #ead9ff;
    }
    .hero h1{
