    }
    .hero .hero-sub{
        position:relative;
        color:var(--accent-purple);
        font-size:14px;
        letter-spacing:3px;
        margin:0;
    }
    .hero .hero-line{
        position:relative;
        width:60px;height:2px;
        background:linear-gradient(90deg,transparent,var(--accent-gold),transparent);
        margin:18px auto 0;
    }
    .card{
        background:var(--soft-white);
        border-radius:24px;
        padding:28px 26px;
        margin-bottom:22px;
        box-shadow:var(--shadow-soft);
        border:1px solid #f2edfb;
    }
    .section-title{
        display:flex;
        align-items:center;
        gap:12px;
        font-size:18.5px;
        font-weight:700;
        color:#3a3350;
        margin:0 0 18px;
        letter-spacing:1px;
    }
    .section-title::before{
        content:"";
