/* 现实修改器专属 6 级折叠面板样式 (1:1 对齐用户截图) */
.reality-panels-container {
  border: 1px solid #383b46 !important;
  border-radius: 8px !important;
  background: #1e2026 !important;
  overflow: hidden !important;
  margin-top: 14px !important;
}
.reality-panel {
  border-bottom: 1px solid #2d303a !important;
}
.reality-panel:last-child {
  border-bottom: none !important;
}
.reality-summary {
  padding: 8px 14px !important;
  font-size: 13px !important;
  font-weight: 500 !important;
  color: #e2e8f0 !important;
  cursor: pointer !important;
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  user-select: none !important;
  background: #202228 !important;
  transition: background 0.15s ease, color 0.15s ease !important;
}
.reality-summary:hover {
  background: #282a32 !important;
  color: #fff !important;
}
.reality-panel[open] > .reality-summary {
  background: #22252e !important;
  color: #38bdf8 !important;
}
.reality-panel[open] > .reality-summary .arrow-indicator {
  color: #38bdf8 !important;
}
.reality-body {
  padding: 12px 16px !important;
  font-size: 12px !important;
  color: #cbd5e1 !important;
  line-height: 1.85 !important;
  background: #181a20 !important;
  border-top: 1px solid #282a32 !important;
}
', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>📱 现实修改器 v6.9——无所不能的都市生活</title>
<link href="https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;600;700&display=swap" rel="stylesheet">
<style>
    :root{
        --soft-white:#ffffff;
        --cream-bg:#fdfcf8;
        --accent-gold:#06b6d4;
        --accent-purple:#8b5cf6;
        --text-dark:#2d2d2d;
        --text-gray:#6d6d6d;
        --border-color:#efe6ff;
        --shadow:0 12px 42px rgba(120,90,160,0.10);
        --shadow-soft:0 6px 20px rgba(120,90,160,0.07);
    }
    *{box-sizing:border-box;}
    html,body{margin:0;padding:0;}
    body{
        font-family:''Noto Serif SC'',"PingFang SC","Microsoft YaHei",serif;
        background:linear-gradient(180deg,#fcfaff 0%,#f0f9ff 45%,#fcfaff 100%);
        color:var(--text-dark);
        line-height:1.85;
        padding:18px 14px 60px;
        -webkit-font-smoothing:antialiased;
    }
    .page{max-width:880px;margin:0 auto;}
    .hero{
        position:relative;
        text-align:center;
        padding:46px 24px 40px;
        background:linear-gradient(135deg,#f5f3ff 0%,#e0f2fe 55%,#fdfcf8 100%);
        border-radius:30px;
        border:1px solid var(--border-color);
        box-shadow:var(--shadow);
        margin-bottom:24px;
        overflow:hidden;
    }
    .hero-tag{
        position:relative;
        display:inline-block;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:#6366f1;
        padding:7px 20px;
        border-radius:999px;
        font-size:12.5px;
        letter-spacing:3px;
        font-weight:600;
        border:1px solid #ead9ff;
    }
    .hero h1{
        position:relative;
        font-size:28px;
        letter-spacing:1.5px;
        margin:20px 0 10px;
        color:#332b4d;
    }
    .hero .hero-sub{
        position:relative;
        color:var(--accent-purple);
        font-size:14px;
        letter-spacing:3px;
        margin:0;
    }
    .hero .hero-line{
        position:relative;
        width:60px;height:2px;
        background:linear-gradient(90deg,transparent,var(--accent-gold),transparent);
        margin:18px auto 0;
    }
    .card{
        background:var(--soft-white);
        border-radius:24px;
        padding:28px 26px;
        margin-bottom:22px;
        box-shadow:var(--shadow-soft);
        border:1px solid #f2edfb;
    }
    .section-title{
        display:flex;
        align-items:center;
        gap:12px;
        font-size:18.5px;
        font-weight:700;
        color:#3a3350;
        margin:0 0 18px;
        letter-spacing:1px;
    }
    .section-title::before{
        content:"";
        width:6px;height:22px;
        border-radius:4px;
        background:linear-gradient(180deg,var(--accent-purple),var(--accent-gold));
        display:inline-block;
    }
    .section-sub{
        color:var(--text-gray);
        font-size:13px;
        margin:-10px 0 16px;
    }
    p{margin:0 0 14px;}
    .story-text{color:#4a4458;font-size:15px;line-height:1.9;white-space:pre-line;}
    .profile-grid{
        display:grid;
        grid-template-columns:repeat(auto-fit,minmax(240px,1fr));
        gap:16px;
    }
    .p-item{
        background:linear-gradient(160deg,#fdfbff,#fff9f2);
        border:1px solid #f0eafc;
        border-radius:18px;
        padding:18px 20px;
        transition:.25s;
    }
    .p-item:hover{transform:translateY(-3px);box-shadow:var(--shadow-soft);}
    .p-item h4{
        margin:0 0 10px;
        font-size:15px;
