INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at) VALUES ('deck_friend_sister', '早泄好哥们每晚都在肏亲生姐姐？', '豪宅寄宿 · 禁忌偷窥', '🍷', '好哥们的秘密', '欲求不满的火辣姐姐与贵妇熟母', '🍷', '#8b5cf6', 'linear-gradient(135deg, #8b5cf6 0%, #6d28d9 100%)', '{"desc": "受好兄弟邀请借住独栋别墅。深夜撞见短发火辣姐姐林若曦与弟弟的畸形关系与欲求不满，同时隔壁还有压抑的42岁端庄贵妇母亲苏青岚。", "author": "八颗牙齿"}', '[{"name": "林若曦", "role": "22岁画室老师（姐姐）", "desc": "短发冷艳、身材火辣、E罩杯紧身背心白丝热裤，对弟弟有病态占有欲但弟弟能力不行导致其长期欲求不满"}, {"name": "苏青岚", "role": "42岁贵妇母亲", "desc": "连锁美容院老板，古典鹅蛋脸盘发，优雅高贵，有着超越年轻人的H罩杯丰腴熟躯"}, {"name": "林铭宇", "role": "铁哥们（弟弟）", "desc": "富二代，英俊多金但严重秒射，对家人过度依赖"}]', '[{"title": "独栋别墅昏暗走廊", "desc": "虚掩的房门，微弱暖色壁灯下的偷窥视角"}, {"title": "林若曦的私人画室", "desc": "满室油画颜料香气，画布前交缠的诱惑"}, {"title": "苏青岚的主卧套房", "desc": "华贵大床与真丝吊带睡袍，压抑喘息的禁地"}]', '{}', '{"story": "独栋别墅的夏夜静谧得令人心慌，唯有走廊中央的落地大钟在发出规律的滴答声。\n你口渴想下楼倒水，赤着脚走过铺着厚厚地毯的长廊。尽头客房虚掩的门缝里，泄出一缕暧昧昏黄的暖光，随之而来的，是一阵压抑不住的急促撞击声与娇喘。\n你鬼使神差地放轻呼吸凑上前去——门缝内，好兄弟林铭宇赤身伏在床上，而跨坐在他腰间的，正是平日对所有人冷若冰霜的姐姐林若曦。她短发被香汗打湿，丰满白腻的E罩杯巨乳在空气中剧烈颠颤，白丝长腿紧绷扣在床沿。然而不过几秒，林铭宇便发出一声挫败的闷哼瘫软下来。\n“又这样……铭宇，姐姐还没到啊……”林若曦美眸泛着未平息的潮红与深深的欲求不满。\n而在走廊另一侧的门内，42岁的贵妇母亲苏青岚房中，也传来了一声极度压抑的痛苦低咽……", "branches": [{"tag": "A", "title": "屏住呼吸在门缝前近距离窥视若曦的娇躯", "desc": "贴在门缝边注视这位平日不可一世的冷艳御姐在床第间欲壑难平的失落神态"}, {"tag": "B", "title": "故意踩响地板制造声响打破屋内的尴尬", "desc": "重重咳嗽一声在走廊踱步，看房内的林铭宇和林若曦如何慌乱分开收拾残局"}, {"tag": "C", "title": "转身悄步走向发出压抑低咽的母亲苏青岚房门", "desc": "循着另一侧更幽微的喘息声，悄悄来到那位雍容华贵的美容院女总裁门前"}, {"tag": "D", "title": "在走廊耐心等候欲求不满的姐姐开门撞见", "desc": "斜靠在走廊吧台边倒了一杯冰水，静静等待若曦带着满腔幽怨走出门来"}], "location": "市郊独栋别墅 · 深夜二楼走廊"}', NULL, '<!DOCTYPE html>
<html lang="zh-CN">
<head>
