/* ---------- 总结区 ---------- */
.summary{
  background:linear-gradient(135deg,rgba(255,255,255,.96),rgba(255,240,246,.9));
  border-radius:1.2em;
  padding:1.5em 1.4em;
  margin-bottom:1.5em;
  border:1.5px solid rgba(230,164,180,.7);
  box-shadow:0 .5em 1.6em rgba(209,96,129,.16);
}
.summary-title{
  font-size:1.2em;color:#d16081;font-weight:700;
  margin-bottom:1em;text-align:center;letter-spacing:.08em;
}
.summary-title span{
  display:inline-block;
  padding-bottom:.3em;
  border-bottom:2px solid rgba(230,164,180,.6);
}
.summary-content{
  font-size:.92em;
  color:#6b4a52;
  white-space:pre-wrap;
  word-break:break-word;
  line-height:1.9;
  background:rgba(255,252,253,.85);
  border-radius:.8em;
  padding:1.1em 1.1em;
  border:1px solid rgba(242,198,212,.5);
  max-height:26em;
  overflow-y:auto;
}
.summary-content::-webkit-scrollbar{width:.5em;}
.summary-content::-webkit-scrollbar-thumb{background:rgba(230,164,180,.6);border-radius:1em;}
.summary-content::-webkit-scrollbar-track{background:transparent;}

/* ---------- 复制按钮 ---------- */
.copy-btn{
  display:block;
  width:100%;
  padding:1em;
  margin-top:1em;
  border:none;
  border-radius:.9em;
  background:linear-gradient(135deg,#f7b7c9,#e07d9c,#d16081);
  background-size:200% 200%;
  color:#fff;
  font-family:inherit;
  font-size:1.08em;
  font-weight:700;
  letter-spacing:.18em;
  cursor:pointer;
  box-shadow:0 .4em 1.3em rgba(224,125,156,.5);
  transition:transform .2s ease,box-shadow .2s ease;
  animation:flow 3.5s ease infinite;
}
@keyframes flow{
  0%{background-position:0% 50%;}
  50%{background-position:100% 50%;}
  100%{background-position:0% 50%;}
}
.copy-btn:hover{
  transform:translateY(-.15em);
  box-shadow:0 .6em 1.7em rgba(224,125,156,.65);
}
.copy-btn:active{transform:translateY(0);}
.copy-btn.done{
  background:linear-gradient(135deg,#b6e0c4,#8fcf9e);
  animation:none;
  box-shadow:0 .4em 1.3em rgba(143,207,158,.5);
}

/* ---------- 页脚 ---------- */
.footer{
  text-align:center;
  font-size:.78em;
  color:#c9a3b1;
  padding:1.2em 0 .6em;
  letter-spacing:.1em;
}

/* ---------- 响应式 ---------- */
@media (max-width:600px){
