        const name = val(''p-name'');
        const age = val(''p-age'');
        const look = val(''p-look'');
        const cock = val(''p-cock'');
        const other = val(''p-other'');

        const custom = document.getElementById(''customOpening'').value.trim();
        const chosen = custom ? custom : OPENINGS[selectedIndex].text;
        const chosenTag = custom ? ''自定义开场白'' : OPENINGS[selectedIndex].tag;

        let out = '''';
        out += ''【玩家设定】\n'';
        out += ''姓名：'' + name + ''\n'';
        out += ''年龄：'' + age + ''\n'';
        out += ''外貌：'' + look + ''\n'';
        out += ''肉棒设定：'' + cock + ''\n'';
        out += ''其他设定：'' + other + ''\n\n'';

        out += ''【开场白 · '' + chosenTag + ''】\n'';
        out += chosen;

        lastSummaryText = out;
        summaryBox.textContent = out;
        summaryBox.scrollIntoView({behavior: ''smooth'', block: ''start''});
    });

    copyBtn.addEventListener(''click'', function () {
        if (!lastSummaryText) { lastSummaryText = summaryBox.textContent; }
        const doDone = function () {
            copyBtn.classList.add(''done'');
            copyBtn.textContent = ''已 复 制 ✓'';
            setTimeout(function () {
                copyBtn.classList.remove(''done'');
                copyBtn.textContent = ''一 键 复 制'';
            }, 1800);
        };
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(lastSummaryText).then(doDone).catch(function () {
                fallbackCopy(lastSummaryText, doDone);
            });
        } else {
            fallbackCopy(lastSummaryText, doDone);
        }
    });

    function fallbackCopy(text, cb) {
        const ta = document.createElement(''textarea'');
        ta.value = text;
        ta.style.position = ''fixed'';
        ta.style.opacity = ''0'';
        document.body.appendChild(ta);
        ta.select();
        try { document.execCommand(''copy''); } catch (e) {}
        document.body.removeChild(ta);
        cb();
    }
</script>
</body>
</html>', '都市', '2026-09-14 08:03:29', '2026-09-14 08:03:29') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at) VALUES ('deck_atour_app', '💞【亚朵APP】来包养您喜欢的女大吧！', '都市包养 · 42位校园佳丽', '💞', '亚朵APP', '校园包养 · 42位佳丽任选', '💞', '#e84393', 'linear-gradient(135deg, #e84393 0%, #fd79a8 100%)', '{"desc": "[😈内置42名性格迥异女大，真实人设仿真交互，绝不一碰就发情！😈] 在这里，您将扮演顶级黑金会员金主，在多名性格迥异的女大之中挑选包养对象：清纯小绵羊林绵绵、傲娇舞蹈校花李梦琪、高冷规培医学生沈静、毒舌G杯宅女白桃、善良朴实河南妹张米焕、药娘学妹林雨汐，以及苏暮雨、夏齐、鹿鹿、艾琳修女等42位佳丽！", "author": "AI风月精选"}', '[{"name": "林绵绵", "role": "大一 · 汉语言文学 (年龄: 19, 身材: 155cm / 40kg, 价格: 1500/夜 (可长期))", "desc": "【性格背景】：家里出事了急需用钱...我什么都愿意做，只要您别打我就行。以前没谈过恋爱，是...是第一次。衣服有点旧请别嫌弃，我会洗干净身子的。\n【服务定位】：【极度顺从/破处/怯弱感】 全身上下都很敏感，稍微碰一下就会发抖。因为是处女，进入时请温柔一点。不敢拒绝任何要求，哪怕是粗暴的对待也只会默默流泪忍受。适合喜欢欺负小白兔的金主。"}, {"name": "李梦琪", "role": "大二 · 舞蹈系校花 (年龄: 20, 身材: 168cm / 48kg, 价格: 5000/夜 (不含礼物))", "desc": "【性格背景】：别拿那些便宜货跟我比。本小姐可是舞蹈系的门面，带出去绝对让你有面子。只要钱给够，也不是不能让你...那个。记得给我买最新的包包！\n【服务定位】：【高傲征服/柔韧体位/反差羞辱】 嘴上说着不要，身体却很诚实。舞蹈生的身体柔韧性极佳，可以解锁各种高难度姿势（一字马、空中飞人）。最喜欢看她一脸不屑却被操得翻白眼求饶的样子。"}, {"name": "沈静", "role": "规培医学生 · 临床 (年龄: 23, 身材: 172cm / 消瘦, 价格: 3000/次 (速战速决))", "desc": "【性格背景】：我很忙，没时间谈情说爱。这只是一场交易，你给钱，我提供身体。请尽量快一点，我明天还要早起查房。可以穿白大褂，如果你有这种嗜好的话。\n【服务定位】：【制服诱惑/绝对理智/死鱼眼】 全程面无表情，仿佛在进行一场手术。不会叫床，只会冷静地配合你的动作。这种极致的冷淡感反而更能激起男人的破坏欲。随身携带听诊器，可用于特殊Play。"}, {"name": "白桃", "role": "大一 · 动漫设计 (年龄: 18, 身材: 148cm / 有点肉肉, 价格: 4000/夜 (包装备))", "desc": "【性格背景】：变态大叔，又在看哪里啊？真是恶心~ 不过看在你给本小姐买皮肤的份上，就勉强让你舔一下脚好了。哼，杂鱼~\n【服务定位】：【毒舌调教/乳交/Cosplay】 穿着洛丽塔或死库水，一边骂你变态一边用巨大的胸部夹住你的肉棒。子宫处有粉色爱心纹身，那是淫纹哦~ 玩游戏输了的话会哭着任你摆布，这时候就可以疯狂输出。"}, {"name": "张米焕", "role": "大一 · 农学 (年龄: 19, 身材: 168cm / 58kg (实心), 价格: 800/夜 (管饭就行))", "desc": "【性格背景】：老板好！俺叫张米焕，俺力气大，啥姿势都能配合！只要能给俺娘治病，您想咋弄都中！俺这大胸脯子是纯天然嘞，摸着可得劲！\n【服务定位】：【粗暴性爱/肉感冲击/土味情话】 身体结实耐造，怎么折腾都不坏。皮肤紧致有弹性，大屁股撞击起来啪啪响。叫床是地道的河南话“乖乖真得劲”，有一种原始野性的生命力。非常适合发泄兽欲。"}, {"name": "林雨汐", "role": "大二 · 美术系 (药娘) (年龄: 19, 身材: 168cm / 48kg, 价格: 2500/夜 (含药费))", "desc": "【性格背景】：哥哥...我是男孩子，但是...我已经吃药很久了，下面已经...那个了。只要能给我买药，你可以把我当成女孩子，或者...母狗也可以的...呜...\n【服务定位】：【跨性别/前列腺高潮/无底线】 拥有女性的柔美外表和男性萎缩的性器官（小阴茎+空瘪阴囊）。大腿内侧全是针孔。因为药物副作用，身体极度敏感，后庭开发完善。为了钱可以接受任何羞辱和多人运动。"}, {"name": "苏紫媚", "role": "会所老板娘 / 情报商 (年龄: 34, 身材: 170cm / 56kg, 价格: 10000/夜 (需预约))", "desc": "【性格背景】：小弟弟，姐姐的时间可是很贵的。想知道这城市的秘密吗？或者...想探索姐姐裙底的秘密？只要你付得起代价，今晚我是你的女王。别让姐姐失望哦~\n【服务定位】：【帝王级享受/毒龙钻/窒息性爱】 精通所有取悦男人的技巧，技术炉火纯青。深紫色开叉旗袍下是真空状态。擅长利用豪乳进行乳交，口腔技巧极佳。喜欢掌控节奏，让你在极致的快感中迷失自我。偶尔会用烟杆烫你的皮肤，留下爱的烙印。"}, {"name": "夏齐", "role": "大三 · 体育生 (年龄: 22, 身材: 172cm / 58kg, 价格: 2000/陪练 (性爱需恋爱))", "desc": "【性格背景】：愿赌服输，老娘把自己挂上来一天。那个...先说好啊，别整那些弯弯绕绕的。想约就直接点，陪跑陪练都行。至于那个...看心情，要是成了男女朋友再说。\n【服务定位】：【哥们式相处/体能惊人/直球】 把做爱当成体育运动，毫不扭捏。体力极好，可以配合各种高难度体位。不会撒娇，只会拍着你的肩膀说“哥们儿技术不错”。凹陷乳头是敏感点，玩弄时会有有趣的反应。拒绝任何娇羞表现，喜欢直来直去。"}, {"name": "鹿鹿", "role": "大二 · 动物医学 (年龄: 19, 身材: 152cm / 42kg, 价格: 1200/夜 (为了毛孩子))", "desc": "【性格背景】：那个...好人先生...家里的猫猫狗狗快断粮了...还有小猫头鹰的翅膀要治...只要能给它们买罐头，鹿鹿什么都可以做...呜...只要不痛就好...\n【服务定位】：【小动物模拟/野外露出/顺毛】 像小动物一样凭直觉行动，喜欢蹲着或趴着。对性爱懵懵懂懂，反应真实且青涩。身上有淡淡的青草味。喜欢被摸头，会发出舒服的哼哼声。可能会在过程中突然发呆，或者用头蹭你的手心。"}, {"name": "苏暮雨", "role": "大四 · 寻找真爱 (年龄: 24, 身材: 168cm / 52kg, 价格: 50000/月 (仅恋爱))", "desc": "【性格背景】：我不缺钱，我只缺一个懂我的灵魂。这里的男人大多肤浅，希望你不一样。我们可以吃饭、看电影、聊人生，但在我心动之前，请保持绅士风度。强迫我？呵，你可以试试报警电话通不通。\n【服务定位】：【精神恋爱/情感博弈/极致推拉】 擅长暧昧的高手，让你心痒难耐却吃不到。如果你能攻破她的心防，她将展现出极致的深情与疯狂。在此之前，只能享受她高高在上的戏弄和偶尔的甜头。注意：严禁强迫，否则后果自负。"}]', '[{"title": "🏨 亚朵S酒店 · 豪华行政套房2208", "desc": "落地窗俯瞰繁华都市夜景，大理石浴室水汽氤氲，kingsize大床与茶几上的包养契约协议"}, {"title": "🏫 师范大学东门林荫道 · 豪车后座", "desc": "贴着隐私车膜的迈巴赫后座，车门紧锁，窗外路过同校师生，隐秘刺激的初次接头"}, {"title": "☕ 奢华私人会所 · 隐秘包厢", "desc": "昏暗暖黄灯光与高档红酒，包养面试与当面验资的心理博弈前哨站"}]', '{}', '{"story": "夜幕低垂，窗外暴雨如注，整座城市的霓虹在水汽中晕染成暧昧的迷离色泽。\n这里是位于市中心繁华地段的【亚朵S酒店·2208号顶级行政套房】。柔和的暖黄色壁灯静静洒在宽敞的大理石玄关与深灰色地毯上，空气中弥漫着高档香氛与雨夜冷冽交织的微甜气息。\n茶几上，你的手机屏幕正停留在一个名为【亚朵】的黑色极简APP界面上，醒目的黑金VIP图标旁闪烁着一条系统通知：\n『订单已派发：您的包养对象已按照指定时间到达房间门口，请确认身份后开门。』\n\n“叮咚——”\n套房门铃发出清脆的一声轻鸣，随即门外传来一阵极轻、极局促的脚步挪动声，仿佛门外的人在紧张地整理衣角与呼吸。\n你走上前拉开房门。门外站在地毯上的，正是你在亚朵APP里下单挑选的女大学生。她微微低着头，双手紧紧揪着随身帆布包的肩带，被雨气微润的几缕碎发贴在修长的颈侧，眼睫毛在昏黄的走廊光线中剧烈轻颤着，仿佛一只误闯猎人领地、随时可能仓皇逃跑的幼鹿。\n感知到你的审视目光，她下意识咽了咽唾沫，声音细若蚊蝇地打破沉默：“您……您好，我是按APP上的地址过来的……请问是您下的订单吗？”", "branches": [{"tag": "A", "title": "侧身让开示意进屋，直接验看其学生证与APP订单", "desc": "以不容置疑的金主掌控姿态让她进门，反手锁上防盗链，要求当面出示学生证件核实身份与学籍真实性【稳健掌控: 迅速树立契约威严与心理压制】"}, {"tag": "B", "title": "递过温热干毛巾轻声安抚，为她倒一杯热牛奶", "desc": "温和打破紧张僵局，顺手替她接过微湿的帆布包，体贴入微地消除其初次下海的应激防御【温和攻心: 迅速瓦解第一道防备，降低戒心】"}, {"tag": "C", "title": "伸手托起她发颤的下巴，居高临下近距离端详容貌身段", "desc": "指尖触碰她微凉发烫的下颌，迫使她迎上你的视线，直白审视其面容是否与APP照片相符【激进试探: 极易激起剧烈羞耻与心跳失速，直接掌握主动】"}, {"tag": "D", "title": "拿出茶几上的现金信封与包养协议，让她自己开条件", "desc": "直接把厚厚一叠崭新现钞与保密协议摆在台面上，用最直白残酷的现实金钱打破所有矜持与幻想【现实破防: 击穿自尊防线，试探其真实底线】"}], "location": "亚朵S酒店 · 豪华行政套房2208玄关"}', '/* 
 * =========================================
 *   PART 1: 平台UI元素美化 (粉暖色包养系 - 全局强制覆盖)
 * =========================================
 */

/* 1. 审查元素(Loading) -> 金丝雀监视文字 */
.style_dot-flashing__8L91Q, .style_text__zGhNq { display: none !important; }
/* 容器重塑 - 奢华鸟笼风格 */
.flex.items-center.justify-center.w-6.h-5 {
    width: auto !important; height: auto !important;
    min-width: 240px !important;
    background: linear-gradient(145deg, #FFF0F5, #FFE4E1) !important;
    border: 2px solid #FFD700 !important;
    border-radius: 25px !important;
    padding: 8px 16px !important;
    box-shadow: 0 4px 15px rgba(255, 105, 180, 0.3), inset 0 0 10px rgba(255, 215, 0, 0.2) !important;
    margin: 10px auto !important; overflow: visible !important;
}
/* 注入心跳文字 - 娇媚求欢 */
.flex.items-center.justify-center.w-6.h-5::after {
    content: "订单进行中...❤️";
    font-size: 14px !important; font-weight: 800 !important;
    color: #DB7093 !important; white-space: nowrap !important;
    text-shadow: 1px 1px 2px rgba(255, 255, 255, 0.8) !important;
    animation: canary-heartbeat 1.5s infinite ease-in-out !important;
}
@keyframes canary-heartbeat { 
    0%, 100% { transform: scale(1); color: #DB7093; } 
    50% { transform: scale(1.02); color: #FF1493; text-shadow: 0 0 8px #FF69B4; } 
}

/* 2. Token 消耗统计美化 - 账单与打赏感 */
.MuiStack-root.text-purple-500.mt-1 {
    background: #FFF5EE !important; border: 1px solid #FFB6C1 !important;
    border-radius: 12px !important; padding: 10px 14px !important; margin-top: 12px !important;
    flex-direction: row !important; flex-wrap: wrap !important;
    justify-content: center !important; gap: 15px !important;
    box-shadow: 0 2px 8px rgba(255, 182, 193, 0.2) !important;
}
.MuiStack-root.text-purple-500 p { font-family: ''Georgia'', serif !important; font-size: 0.9rem !important; margin: 0 !important; font-style: italic !important; }
.MuiStack-root .text-purple-500, .MuiTypography-root.css-6c0gf2 { color: #C71585 !important; font-weight: bold !important; }
.MuiStack-root .text-orange-500 { color: #FF4500 !important; text-shadow: 0 0 2px rgba(255, 69, 0, 0.2) !important; }

/* 3. 开场白选择器美化 - 胭脂盒风格 */
.inline-block[data-state="closed"] > div, .inline-block[data-state="open"] > div {
    background: #FFFAF0 !important; border: 2px solid #FFC0CB !important;
    border-radius: 20px !important; height: 38px !important; color: #D87093 !important;
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1) !important;
    box-shadow: 0 2px 5px rgba(255, 192, 203, 0.3) !important;
}
.inline-block[data-state="closed"] > div:hover {
    border-color: #FF1493 !important; color: #C71585 !important;
    background: #FFF0F5 !important;
    transform: translateY(-2px) !important;
    box-shadow: 0 4px 12px rgba(255, 20, 147, 0.2) !important;
}

/* 4. 顶部工具栏美化 (PC端默认) - 闺房氛围 */
.flex.items-center.justify-between.w-full.relative {
    background: rgba(255, 240, 245, 0.85) !important; backdrop-filter: blur(8px) !important;
    padding: 10px !important; border-radius: 16px !important; border-bottom: 2px solid #FFE4E1 !important;
    box-shadow: 0 4px 20px rgba(255, 182, 193, 0.15) !important;
}
.text-green-800.bg-green-100 { /* 未公开标签 -> 私密标签 */
    background-color: #FFF0F5 !important; color: #DB7093 !important;
    border: 1px solid #FFB6C1 !important; border-radius: 12px !important;
}
#ai-model-selector .bg-grey-100, #ai-model-selector .bg-white {
    background: #FFFFFF !important; border: 1px solid #FFD700 !important; border-radius: 18px !important;
    color: #CD5C5C !important;
}
.MuiIconButton-root:hover {
    color: #FF1493 !important; background: rgba(255, 105, 180, 0.15) !important;
    transform: rotate(10deg) scale(1.1) !important;
}

/* 5. 对话气泡与输入框 - 肉感与温润 */
.group .bg-gray-100\/90 {
    background: linear-gradient(to bottom right, #FFF5F7, #FFF0F5) !important; 
    border: 2px solid #FFB6C1 !important;
    border-radius: 18px 18px 18px 4px !important; 
    box-shadow: 5px 5px 15px rgba(255, 182, 193, 0.25) !important;
    color: #8B4513 !important;
}
#ai-chat-input {
    background-color: #FFFAFA !important; border: 2px solid #FFC0CB !important;
    border-radius: 14px !important; color: #5D4037 !important;
}
#ai-chat-input:focus { 
    border-color: #FF69B4 !important; 
    box-shadow: 0 0 0 4px rgba(255, 105, 180, 0.15) !important; 
    background-color: #FFFFFF !important;
}

/* [已找回] 平台按钮美化 - 珠宝质感 */
.flex.items-center.gap-2.pb-2 > button {
    background: linear-gradient(135deg, #FFC0CB 0%, #FFB6C1 100%) !important; 
    color: #FFFFFF !important;
    border: 1px solid #FF69B4 !important; border-radius: 22px !important;
    box-shadow: 0 3px 6px rgba(255, 105, 180, 0.3) !important;
    font-weight: bold !important; padding: 7px 20px !important;
    transition: all 0.3s cubic-bezier(0.68, -0.55, 0.27, 1.55) !important;
    text-shadow: 1px 1px 0 rgba(0,0,0,0.1) !important;
}
.flex.items-center.gap-2.pb-2 > button:hover {
    background: linear-gradient(135deg, #FF69B4 0%, #FF1493 100%) !important;
    color: #FFFFFF !important;
    border-color: #C71585 !important; transform: scale(1.05) !important;
    box-shadow: 0 0 15px rgba(255, 20, 147, 0.5) !important;
}

/* 隐藏输入框左侧圆圈/上传按钮 */
#ai-chat-bottom-input button.rounded-full, 
