setTimeout(() => { showPanel(''👾 来自 零 的消息'', ''虽然弹窗关了，但你的系统已经被本小姐接管了哦~大叔乖乖去大厅第一个找我吧，噗库库~♡''); }, 500);
}
}
function handleHeaderClick() {
headerClickCount++;
if(headerClickCount >= 4) {
if(isHacked) {
restoreSystem();
} else {
if(!hasBeenHackedOnce) {
document.getElementById(''afOverlay'').style.display = ''flex'';
hasBeenHackedOnce = true;
headerClickCount = 0;
