{n:''粉樱花和服'', u:''https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAEMVTJpNp2UmfcfL8-DjpaEawesF8CeCwACqCYAAjH4sFUWKnxXo1wpXTYE.png'', b:false},
{n:''工作制服'', u:''https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAEMVTFpNp2UPD2k3_nYnXbUrCUE0oh4FAACpyYAAjH4sFWnrJA8QzR4kjYE.png'', b:false},
{n:''蓝浴衣'', u:''https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAEMTD9pNYvNpOkop8Sd0kyJ0CNTldW2-QACFCAAAtFAsVXlW0qfECN3YzYE.png'', b:false},
{n:''睡衣'', u:''https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAEMS7VpNYOqL-tGBwv08Kv_ePlAJv7w1QACXR8AAtFAsVWOh1H3clE8JTYE.png'', b:true},
