function rC(){var cg=document.getElementById(''cGr'');cg.innerHTML='''';ws.forEach(function(w){var d=document.createElement(''div'');d.className=''wd-item'';var bCl=w.b?'' blur-secret'':'''';d.innerHTML=''<div class="wd-im''+bCl+''" style="background-image:url(\''''+w.u+''\'')"></div><div class="wd-nm">''+w.n+''</div>'';d.onclick=function(){ps();document.getElementById(''cPl'').classList.remove(''sw'');var ts=document.getElementById(''ts'');ts.textContent=''👗 已检视 ''+w.n;ts.classList.add(''sw'');setTimeout(function(){ ts.classList.remove(''sw''); }, 1500);};cg.appendChild(d);});}
document.querySelectorAll(''input,textarea'').forEach(i=>{i.addEventListener(''focus'',ps);});
document.getElementById(''fSt'').value="周六的清晨，女儿在沙发睡觉，我叫醒她。";
rC();
document.getElementById(''gTt'').onclick=function(){ps();this.classList.remove(''sk'');void this.offsetWidth;this.classList.add(''sk'');};
var cPl=document.getElementById(''cPl'');
document.getElementById(''sOp'').onclick=function(){ps();cPl.classList.add(''sw'');};
document.getElementById(''cCl'').onclick=function(){ps();cPl.classList.remove(''sw'');};
document.getElementById(''fMd'').onchange=function(){ps();};
document.getElementById(''bGo'').onclick=function(){
ps();
var pE=document.getElementById(''fGn'');
var pn=pE.value.trim();
if(!pn){
    pE.classList.remove(''er'');void pE.offsetWidth;pE.classList.add(''er'');
    var ts=document.getElementById(''ts'');ts.textContent=''⚠️ 请输入姓名哦！'';ts.classList.add(''sw'');setTimeout(function(){ts.classList.remove(''sw'');},2500);return;
}
var rl=document.getElementById(''fRl'').value.trim()||''我是陈佳慧的父亲'';
var st=document.getElementById(''fSt'').value.trim()||''周六的清晨，女儿在沙发睡觉，我叫醒她。'';
