if(document.getElementById(''fMd'').checked){txt+=''\n【平然世界】：开启'';}
txt+=''\n\n''+st;
var ta=document.createElement(''textarea'');ta.value=txt;ta.style.position=''fixed'';ta.style.left=''-9999px'';document.body.appendChild(ta);ta.select();document.execCommand(''copy'');document.body.removeChild(ta);
document.getElementById(''mBg'').style.backgroundImage="url(''https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAEMVXNpNqJ4yB3be_-NBPSnX-mP2MWHhwAC_SYAAjH4sFVOyjMAAV9pwUw2BA.png'')";
