INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at) VALUES ('deck_sister_in_law_niece', '深夜求助的嫂子与侄女', '暴雨投奔 · 双成人路线', '🌧️', '深夜求助', '嫂子与侄女 · 雨夜投奔', '🌧️', '#6c5ce7', 'linear-gradient(135deg, #6c5ce7 0%, #a29bfe 100%)', '{"desc": "哥哥周世杰欠债失踪，36岁的丰润人妻嫂子林晚晴（D罩杯）与18岁的俏丽侄女周若宁（C罩杯）在暴雨深夜投奔小叔子。无处可去的母女二人、高利贷的催逼账单、同居屋檐下的身体与情感双成人路线。", "author": "AI风月精选"}', '[{"name": "林晚晴", "role": "36岁丰润人妻嫂子 (168cm / 58kg / D罩杯 / 95-70-96)", "desc": "失踪哥哥周世杰的妻子。成熟丰润的梨形身材，腰腹柔软丰满，臀腿线条饱满。平日端庄自持，但为了保护女儿不受催债人骚扰，准备了只要遭到拒绝就不惜向小叔子献身的隐秘杀手锏。"}, {"name": "周若宁", "role": "18岁高中毕业侄女 (163cm / 50kg / C罩杯 / 86-60-88)", "desc": "刚满18岁的高中毕业生，身材纤细匀称、腰线分明。从小极度依赖小叔，成年后活泼嘴硬、爱坏笑挑衅，是个懂得试探叔叔边界的雌小鬼型成年少女。"}]', '[{"title": "公寓门厅玄关 · 暴雨夜", "desc": "浑身湿透的母女俩局促伫立，雨水沿着发梢与浸透的风衣滴落在地毯上"}, {"title": "客厅暖光沙发 · 账单核查", "desc": "换上小叔子大号T恤的母女捧着热茶，茶几上散落着高利贷催收账单"}, {"title": "次卧临时通铺 · 母女夜话", "desc": "狭窄双人被褥相依，隔壁传来的轻微翻身声与禁忌心跳"}]', '{}', '{"location": "单身公寓 · 深夜暴雨玄关门前", "story": "午夜零点，窗外的暴雨像瓢泼般倾泻在玻璃窗上，闷雷滚滚震动着整间屋子。\n一阵带着迟疑却格外急促的敲门声突然打破了夜的死寂。你走上前拧开门锁拉开防盗门——\n门外幽暗的声控灯下，站在走廊水迹里的赫然是你的嫂子林晚晴和18岁的侄女周若宁。\n两人浑身湿透，发丝凌乱地贴在苍白的面颊上。36岁的林晚晴薄风衣湿得几乎透明，紧紧裹在她极其丰满的D罩杯胸脯与丰腴迷人的梨形腰臀曲线上；身旁刚满18岁的周若宁冻得嘴唇发紫，双手死死攥着母亲的衣角。\n两只破旧行李箱在脚边不断渗着脏水，林晚晴眼眶通红，声音带着哭腔与无尽的屈辱颤抖着开口：“小叔……世杰经营失败欠了一大笔高利贷跑路了……催债的把老房子锁了，我和若宁实在无路可走……求求你，能不能收留我们避一避……”", "branches": [{"tag": "A", "title": "侧身拉开大门接过沉重行李箱，温和安抚母女先进屋", "desc": "不再多问，一把接过两只滴水的箱子让两人进门暖身，拿大毛巾替她们披上【温和攻心: 迅速驱散惊恐防线，确立值得依靠的绝对庇护者形象】"}, {"tag": "B", "title": "堵在门前严肃要求先把债务金额与借贷合同讲清", "desc": "双臂抱胸站在玄关，要求当面交底欠款明细与催债细节，防止引火烧身【审慎立界: 确立理性掌控权，以现实契约压制被动收留】"}, {"tag": "C", "title": "目光扫过嫂子湿透透光的丰满身段，单手托起她下巴低语", "desc": "直白注视着成熟人妻近乎全裸的曼妙轮廓，压低声音试探其为了留下来准备付出怎样的代价【激进破防: 击碎道德伪装，直接试探其心理底线】"}, {"tag": "D", "title": "递过干净拖鞋与浴巾，吩咐母女二人先去浴室洗热水澡", "desc": "体贴递上自己的大号衬衫与浴巾，吩咐两人轮流去浴室换装，为后续同居生活铺垫【循序渐进: 营造生活常态，借更衣换装打破私密边界】"}]}', '', '<!DOCTYPE html>
<html lang="zh-Hans">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>雨夜来客</title>
<style>
*{box-sizing:border-box}body{margin:0;background:linear-gradient(145deg,#090e14,#131d28);color:#edf1f5;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Microsoft YaHei",sans-serif}.wrap{max-width:860px;margin:auto;padding:18px}.hero{padding:28px 24px;border:1px solid rgba(218,180,108,.28);border-radius:20px;background:radial-gradient(circle at 90% 5%,rgba(111,164,198,.2),transparent 38%),linear-gradient(135deg,#223040,#111922);box-shadow:0 20px 55px rgba(0,0,0,.35)}.hero small{color:#ddb975;letter-spacing:.2em}.hero h1{margin:8px 0;font-size:29px}.hero p{margin:0;color:#c4cbd3;line-height:1.8}.tags{display:flex;flex-wrap:wrap;gap:7px;margin-top:16px}.tag{padding:6px 9px;border:1px solid rgba(218,180,108,.25);border-radius:99px;background:rgba(218,180,108,.08);color:#dec896;font-size:12px}.tabs{display:flex;gap:8px;margin:13px 0}.tab{flex:1;padding:12px;border:1px solid rgba(255,255,255,.09);border-radius:11px;background:rgba(255,255,255,.04);color:#99a5b1;font-weight:700;cursor:pointer}.tab.active{border-color:rgba(218,180,108,.42);background:linear-gradient(135deg,rgba(218,180,108,.17),rgba(111,164,198,.08));color:#fff}.pane{display:none}.pane.active{display:block}.card{margin-top:12px;padding:18px;border:1px solid rgba(255,255,255,.08);border-radius:15px;background:rgba(21,29,39,.92);box-shadow:0 12px 32px rgba(0,0,0,.2)}.card h2{margin:0 0 13px;color:#f2d49b;font-size:17px}.card p{margin:0 0 10px;color:#c9d0d7;line-height:1.8}.people{display:grid;grid-template-columns:1fr 1fr;gap:11px}.person{padding:15px;border:1px solid rgba(255,255,255,.08);border-radius:13px;background:rgba(31,42,54,.78)}.person b{display:block;margin-bottom:5px}.person small{color:#d8b678}.person p{margin-top:8px;font-size:13px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-top:11px}.stat{padding:8px 5px;border-radius:8px;background:rgba(0,0,0,.22);text-align:center}.stat span{display:block;color:#8f9ba7;font-size:10px}.stat strong{color:#ebd09a;font-size:12px}.notice{padding:12px 13px;border-left:3px solid #75a7c6;border-radius:8px;background:rgba(117,167,198,.09);color:#c8dae5;line-height:1.7}.grid{display:grid;grid-template-columns:1fr 1fr;gap:11px}.field{margin-bottom:11px}.field.full{grid-column:1/-1}.field label{display:block;margin-bottom:6px;color:#c7cdd4;font-size:12px}.input{width:100%;padding:10px 11px;border:1px solid rgba(255,255,255,.12);border-radius:9px;background:rgba(5,9,14,.72);color:#fff;outline:none}.input:focus{border-color:#bc9655;box-shadow:0 0 0 3px rgba(218,180,108,.08)}textarea.input{min-height:72px;resize:vertical}.fixed{padding:10px 11px;border:1px dashed rgba(218,180,108,.34);border-radius:9px;background:rgba(218,180,108,.06);color:#ddc797}.preview{min-height:170px;padding:13px;border:1px solid rgba(218,180,108,.22);border-radius:10px;background:rgba(4,8,12,.7);white-space:pre-wrap;color:#d5dbe1;line-height:1.72}.btn{width:100%;margin-top:11px;padding:12px;border:0;border-radius:9px;background:linear-gradient(100deg,#896535,#d9b46f);color:#171109;font-weight:800;cursor:pointer}.toast{display:none;margin-top:9px;color:#79b79a;text-align:center}.tip{color:#8f9ba7;font-size:11px;line-height:1.6}@media(max-width:680px){.wrap{padding:9px}.hero{padding:22px 17px}.people,.grid{grid-template-columns:1fr}.field.full{grid-column:auto}.stats{grid-template-columns:1fr 1fr}}
</style>
</head>
<body>
<main class="wrap">
<header class="hero"><small>A RAINY NIGHT · ADULT FAMILY DRAMA</small><h1>雨夜来客</h1><p>哥哥欠债失踪后，36岁的嫂子带着18岁的女儿，在暴雨夜带着两只行李箱和一袋零散账单敲响了你的门。母女身无分文，原住处无法返回，也没有任何亲友或其他地方能够收留她们。</p><div class="tags"><span class="tag">共同生活</span><span class="tag">债务谜团</span><span class="tag">双成人路线</span><span class="tag">动态内心</span><span class="tag">身体状态</span><span class="tag">自定义玩家</span></div></header>
<nav class="tabs"><button class="tab active" data-pane="story">作品档案</button><button class="tab" data-pane="profile">自定义玩家</button></nav>
<section id="story" class="pane active">
<div class="card"><h2>☔ 开场局面</h2><p>周世杰经营失败、留下多笔来历不明的债务后失联。催债者频繁上门，林晚晴为了母女安全，只能带着女儿前来向身为弟弟的成年{{user}}求助。她们身无分文，原住处已无法返回，亲友也无人愿意或有能力收留，当晚没有旅馆、朋友家或其他安全落脚处可去，只能恳求{{user}}暂时收留。是否答应、如何安排共同生活、谁该承担债务以及哥哥去了哪里，仍由玩家决定。</p></div>
<div class="card"><h2>👥 人物档案</h2><div class="people">
<article class="person"><small>36岁 · 嫂子</small><b>林晚晴</b><p>168cm、58kg，95/70/96，D杯。成熟丰润的梨形身材，腰腹柔软，臀腿饱满，日常穿着克制利落。她准备了一个只有遭到拒绝时才可能启用的秘密杀手锏；即使没有使用，这个念头也会长期留在内心。</p><div class="stats"><div class="stat"><span>身高</span><strong>168cm</strong></div><div class="stat"><span>体重</span><strong>58kg</strong></div><div class="stat"><span>罩杯</span><strong>D</strong></div><div class="stat"><span>三围</span><strong>95/70/96</strong></div></div></article>
<article class="person"><small>18岁 · 侄女</small><b>周若宁</b><p>163cm、50kg，86/60/88，C杯。纤细匀称、腰线明显，动作轻快。刚高中毕业，从小依赖叔叔；成年后的她活泼嘴硬、爱坏笑挑衅，是懂得边界的“雌小鬼”型成年人。</p><div class="stats"><div class="stat"><span>身高</span><strong>163cm</strong></div><div class="stat"><span>体重</span><strong>50kg</strong></div><div class="stat"><span>罩杯</span><strong>C</strong></div><div class="stat"><span>三围</span><strong>86/60/88</strong></div></div></article>
<article class="person"><small>39岁 · 失踪的哥哥</small><b>周世杰</b><p>债务与失踪原因均不明确，需要从合同、转账、通讯和来访者证词中逐步调查。</p></article>
<article class="person"><small>成年 · 玩家</small><b>{{user}}</b><p>周世杰的弟弟、林晚晴的小叔子、周若宁的叔叔。姓名、外貌、体型、职业、资产、住房、经验、偏好与边界均可自定义。</p></article>
</div></div>
<div class="card"><h2>✦ 成人路线规则</h2><div class="notice">林晚晴与周若宁均为成年人，分别拥有独立的恋爱与成人路线。雨夜投奔、无处可去的处境和此后的共同生活都可以直接成为路线起点，不要求先完成固定恋爱阶段、好感门槛或指定回合。嫂子的秘密预案在玩家明确拒绝收留后，也可触发一次成人路线的选择节点。玩家可以接受、拒绝、追问、谈条件、改变话题、只提供普通收留，或以自己的方式推进任意路线；系统不会替玩家作决定。进入具体成人行为前，相关成年人仍需在当轮清醒并明确表达意愿。</div></div>
</section>
<section id="profile" class="pane">
<div class="card"><h2>✦ 身份与身体档案</h2><div class="grid">
<div class="field"><label>姓名或称呼</label><input id="p-name" class="input" placeholder="如：周砚 / 阿砚"></div>
<div class="field"><label>年龄（必须满18岁）</label><input id="p-age" class="input" type="number" min="18" max="80" value="30"></div>
<div class="field"><label>固定家庭身份</label><div class="fixed">周世杰的成年弟弟 · 林晚晴的小叔子 · 周若宁的叔叔</div></div>
<div class="field"><label>职业</label><input id="p-job" class="input" placeholder="如：公司管理层 / 律师 / 个体经营"></div>
<div class="field"><label>身高（cm）</label><input id="p-height" class="input" type="number" min="140" max="230" placeholder="180"></div>
<div class="field"><label>体重（kg）</label><input id="p-weight" class="input" type="number" min="40" max="250" placeholder="78"></div>
<div class="field"><label>体型与外貌</label><input id="p-build" class="input" placeholder="如：肩背宽阔、短发、神情沉稳"></div>
<div class="field"><label>私密身体资料（可留空）</label><input id="p-private" class="input" placeholder="只填写希望剧情明确采用的成年身体资料"></div>
<div class="field full"><label>与哥哥一家的既往关系</label><textarea id="p-history" class="input" placeholder="如：哥哥常年疏远，若宁小时候经常由我照顾，和嫂子一直保持礼貌距离。"></textarea></div>
</div></div>
<div class="card"><h2>💰 住房与经济档案</h2><div class="grid">
<div class="field"><label>住房情况</label><input id="p-home" class="input" placeholder="如：市中心三居室，全款独居"></div>
<div class="field"><label>当前可用现金</label><input id="p-cash" class="input" placeholder="如：5万元"></div>
<div class="field"><label>月收入</label><input id="p-income" class="input" placeholder="如：税后3万元"></div>
<div class="field"><label>存款／投资</label><input id="p-savings" class="input" placeholder="如：存款80万，有少量基金"></div>
<div class="field"><label>个人负债</label><input id="p-debt" class="input" placeholder="如：无负债 / 尚有120万房贷"></div>
<div class="field"><label>可动用的人脉或资源</label><input id="p-resource" class="input" placeholder="如：律师朋友、银行渠道、警方熟人"></div>
</div></div>
<div class="card"><h2>⚖️ 立场、偏好与边界</h2>
<div class="field"><label>对留宿请求的态度</label><select id="p-attitude" class="input"><option>先让母女安全住下，再核对事实</option><option>可以短住，但必须约定期限和家规</option><option>愿意长期提供住处，但不替哥哥承担未知债务</option><option>暂不收留，先协助安排其他安全住处</option></select></div>
<div class="field"><label>当前感情倾向</label><select id="p-route" class="input"><option>暂不选择路线，先处理现实问题</option><option>更关注林晚晴，但不会利用她的困境</option><option>更关注成年后的周若宁，但会重新确认关系边界</option><option>保持开放，让关系随剧情自然变化</option></select></div>
<div class="field"><label>成年感情经验与偏好（可留空）</label><textarea id="p-pref" class="input" placeholder="填写希望影响亲密节奏、互动方式和描写重点的偏好。"></textarea></div>
<div class="field"><label>明确边界／绝对禁止事项</label><textarea id="p-boundary" class="input" placeholder="如：不接受胁迫、醉酒推进或用金钱和住处交换亲密；任何人说停都必须停止。"></textarea></div>
<div class="field"><label>其他补充</label><textarea id="p-extra" class="input" placeholder="可补充性格、恋爱状态、生活习惯、车辆、公司或其他资产。"></textarea></div>
</div>
<div class="card"><h2>📋 玩家档案预览</h2><p class="tip">点击生成后复制到聊天框发送；未填写项目继续采用作品默认值。</p><div id="preview" class="preview"></div><button id="copy" class="btn" type="button">生成并复制玩家档案</button><div id="toast" class="toast">✓ 已复制，请回到聊天中粘贴发送</div></div>
</section>
</main>
<script>
function q(s){return document.querySelector(s)}function v(s){var e=q(s);return e&&e.value?e.value.trim():""}function profile(){var age=Math.max(18,Number(v("#p-age"))||30);return["【雨夜来客｜玩家自定义档案】","姓名或称呼："+(v("#p-name")||"未指定"),"年龄："+age+"岁","固定身份：周世杰的成年弟弟、林晚晴的小叔子、周若宁的叔叔","职业："+(v("#p-job")||"未指定"),"身体资料：身高"+(v("#p-height")||"未指定")+"cm｜体重"+(v("#p-weight")||"未指定")+"kg｜体型外貌："+(v("#p-build")||"未补充")+"｜私密资料："+(v("#p-private")||"未填写，不得擅自推定"),"既往家庭关系："+(v("#p-history")||"未补充，沿用默认"),"【住房与经济】","住房："+(v("#p-home")||"未指定"),"可用现金："+(v("#p-cash")||"未指定"),"月收入："+(v("#p-income")||"未指定"),"存款／投资："+(v("#p-savings")||"未指定"),"个人负债："+(v("#p-debt")||"未指定"),"可动用资源："+(v("#p-resource")||"未指定"),"【当前立场】","留宿态度："+v("#p-attitude"),"感情倾向："+v("#p-route"),"成年感情经验与偏好："+(v("#p-pref")||"未填写，不得擅自推定"),"明确边界："+(v("#p-boundary")||"未额外填写，仍须遵守清醒、自愿和随时撤回规则"),"其他补充："+(v("#p-extra")||"无"),"【采用规则】以上内容只覆盖{{user}}资料，不修改林晚晴、周若宁、周世杰、既有关系和已发生事件；经济帮助与住处不代表任何具体亲密同意。"].join("\n")}function render(){q("#preview").textContent=profile()}document.querySelectorAll(".tab").forEach(function(b){b.addEventListener("click",function(){document.querySelectorAll(".tab").forEach(function(x){x.classList.remove("active")});document.querySelectorAll(".pane").forEach(function(x){x.classList.remove("active")});b.classList.add("active");q("#"+b.dataset.pane).classList.add("active")})});document.querySelectorAll(".input").forEach(function(x){x.addEventListener("input",render)});q("#copy").addEventListener("click",async function(){var t=profile();try{await navigator.clipboard.writeText(t)}catch(e){var x=document.createElement("textarea");x.value=t;document.body.appendChild(x);x.select();document.execCommand("copy");x.remove()}q("#toast").style.display="block";setTimeout(function(){q("#toast").style.display="none"},2400)});render();
</script>
</body>
</html>', '👩‍👧 熟女母女', '2026-09-14 14:01:08', '2026-09-14 14:01:08') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at) VALUES ('432a57e9-8f8a-4e4e-80fc-83eb9ebc71eb', '深夜求助的嫂子与侄女', '暴雨投奔 · 双成人路线', '🌧️', '深夜求助', '嫂子与侄女 · 雨夜投奔', '🌧️', '#6c5ce7', 'linear-gradient(135deg, #6c5ce7 0%, #a29bfe 100%)', '{"desc": "哥哥周世杰欠债失踪，36岁的丰润人妻嫂子林晚晴（D罩杯）与18岁的俏丽侄女周若宁（C罩杯）在暴雨深夜投奔小叔子。无处可去的母女二人、高利贷的催逼账单、同居屋檐下的身体与情感双成人路线。", "author": "AI风月精选"}', '[{"name": "林晚晴", "role": "36岁丰润人妻嫂子 (168cm / 58kg / D罩杯 / 95-70-96)", "desc": "失踪哥哥周世杰的妻子。成熟丰润的梨形身材，腰腹柔软丰满，臀腿线条饱满。平日端庄自持，但为了保护女儿不受催债人骚扰，准备了只要遭到拒绝就不惜向小叔子献身的隐秘杀手锏。"}, {"name": "周若宁", "role": "18岁高中毕业侄女 (163cm / 50kg / C罩杯 / 86-60-88)", "desc": "刚满18岁的高中毕业生，身材纤细匀称、腰线分明。从小极度依赖小叔，成年后活泼嘴硬、爱坏笑挑衅，是个懂得试探叔叔边界的雌小鬼型成年少女。"}]', '[{"title": "公寓门厅玄关 · 暴雨夜", "desc": "浑身湿透的母女俩局促伫立，雨水沿着发梢与浸透的风衣滴落在地毯上"}, {"title": "客厅暖光沙发 · 账单核查", "desc": "换上小叔子大号T恤的母女捧着热茶，茶几上散落着高利贷催收账单"}, {"title": "次卧临时通铺 · 母女夜话", "desc": "狭窄双人被褥相依，隔壁传来的轻微翻身声与禁忌心跳"}]', '{}', '{"location": "单身公寓 · 深夜暴雨玄关门前", "story": "午夜零点，窗外的暴雨像瓢泼般倾泻在玻璃窗上，闷雷滚滚震动着整间屋子。\n一阵带着迟疑却格外急促的敲门声突然打破了夜的死寂。你走上前拧开门锁拉开防盗门——\n门外幽暗的声控灯下，站在走廊水迹里的赫然是你的嫂子林晚晴和18岁的侄女周若宁。\n两人浑身湿透，发丝凌乱地贴在苍白的面颊上。36岁的林晚晴薄风衣湿得几乎透明，紧紧裹在她极其丰满的D罩杯胸脯与丰腴迷人的梨形腰臀曲线上；身旁刚满18岁的周若宁冻得嘴唇发紫，双手死死攥着母亲的衣角。\n两只破旧行李箱在脚边不断渗着脏水，林晚晴眼眶通红，声音带着哭腔与无尽的屈辱颤抖着开口：“小叔……世杰经营失败欠了一大笔高利贷跑路了……催债的把老房子锁了，我和若宁实在无路可走……求求你，能不能收留我们避一避……”", "branches": [{"tag": "A", "title": "侧身拉开大门接过沉重行李箱，温和安抚母女先进屋", "desc": "不再多问，一把接过两只滴水的箱子让两人进门暖身，拿大毛巾替她们披上【温和攻心: 迅速驱散惊恐防线，确立值得依靠的绝对庇护者形象】"}, {"tag": "B", "title": "堵在门前严肃要求先把债务金额与借贷合同讲清", "desc": "双臂抱胸站在玄关，要求当面交底欠款明细与催债细节，防止引火烧身【审慎立界: 确立理性掌控权，以现实契约压制被动收留】"}, {"tag": "C", "title": "目光扫过嫂子湿透透光的丰满身段，单手托起她下巴低语", "desc": "直白注视着成熟人妻近乎全裸的曼妙轮廓，压低声音试探其为了留下来准备付出怎样的代价【激进破防: 击碎道德伪装，直接试探其心理底线】"}, {"tag": "D", "title": "递过干净拖鞋与浴巾，吩咐母女二人先去浴室洗热水澡", "desc": "体贴递上自己的大号衬衫与浴巾，吩咐两人轮流去浴室换装，为后续同居生活铺垫【循序渐进: 营造生活常态，借更衣换装打破私密边界】"}]}', '', '<!DOCTYPE html>
<html lang="zh-Hans">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>雨夜来客</title>
<style>
*{box-sizing:border-box}body{margin:0;background:linear-gradient(145deg,#090e14,#131d28);color:#edf1f5;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Microsoft YaHei",sans-serif}.wrap{max-width:860px;margin:auto;padding:18px}.hero{padding:28px 24px;border:1px solid rgba(218,180,108,.28);border-radius:20px;background:radial-gradient(circle at 90% 5%,rgba(111,164,198,.2),transparent 38%),linear-gradient(135deg,#223040,#111922);box-shadow:0 20px 55px rgba(0,0,0,.35)}.hero small{color:#ddb975;letter-spacing:.2em}.hero h1{margin:8px 0;font-size:29px}.hero p{margin:0;color:#c4cbd3;line-height:1.8}.tags{display:flex;flex-wrap:wrap;gap:7px;margin-top:16px}.tag{padding:6px 9px;border:1px solid rgba(218,180,108,.25);border-radius:99px;background:rgba(218,180,108,.08);color:#dec896;font-size:12px}.tabs{display:flex;gap:8px;margin:13px 0}.tab{flex:1;padding:12px;border:1px solid rgba(255,255,255,.09);border-radius:11px;background:rgba(255,255,255,.04);color:#99a5b1;font-weight:700;cursor:pointer}.tab.active{border-color:rgba(218,180,108,.42);background:linear-gradient(135deg,rgba(218,180,108,.17),rgba(111,164,198,.08));color:#fff}.pane{display:none}.pane.active{display:block}.card{margin-top:12px;padding:18px;border:1px solid rgba(255,255,255,.08);border-radius:15px;background:rgba(21,29,39,.92);box-shadow:0 12px 32px rgba(0,0,0,.2)}.card h2{margin:0 0 13px;color:#f2d49b;font-size:17px}.card p{margin:0 0 10px;color:#c9d0d7;line-height:1.8}.people{display:grid;grid-template-columns:1fr 1fr;gap:11px}.person{padding:15px;border:1px solid rgba(255,255,255,.08);border-radius:13px;background:rgba(31,42,54,.78)}.person b{display:block;margin-bottom:5px}.person small{color:#d8b678}.person p{margin-top:8px;font-size:13px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-top:11px}.stat{padding:8px 5px;border-radius:8px;background:rgba(0,0,0,.22);text-align:center}.stat span{display:block;color:#8f9ba7;font-size:10px}.stat strong{color:#ebd09a;font-size:12px}.notice{padding:12px 13px;border-left:3px solid #75a7c6;border-radius:8px;background:rgba(117,167,198,.09);color:#c8dae5;line-height:1.7}.grid{display:grid;grid-template-columns:1fr 1fr;gap:11px}.field{margin-bottom:11px}.field.full{grid-column:1/-1}.field label{display:block;margin-bottom:6px;color:#c7cdd4;font-size:12px}.input{width:100%;padding:10px 11px;border:1px solid rgba(255,255,255,.12);border-radius:9px;background:rgba(5,9,14,.72);color:#fff;outline:none}.input:focus{border-color:#bc9655;box-shadow:0 0 0 3px rgba(218,180,108,.08)}textarea.input{min-height:72px;resize:vertical}.fixed{padding:10px 11px;border:1px dashed rgba(218,180,108,.34);border-radius:9px;background:rgba(218,180,108,.06);color:#ddc797}.preview{min-height:170px;padding:13px;border:1px solid rgba(218,180,108,.22);border-radius:10px;background:rgba(4,8,12,.7);white-space:pre-wrap;color:#d5dbe1;line-height:1.72}.btn{width:100%;margin-top:11px;padding:12px;border:0;border-radius:9px;background:linear-gradient(100deg,#896535,#d9b46f);color:#171109;font-weight:800;cursor:pointer}.toast{display:none;margin-top:9px;color:#79b79a;text-align:center}.tip{color:#8f9ba7;font-size:11px;line-height:1.6}@media(max-width:680px){.wrap{padding:9px}.hero{padding:22px 17px}.people,.grid{grid-template-columns:1fr}.field.full{grid-column:auto}.stats{grid-template-columns:1fr 1fr}}
</style>
</head>
<body>
<main class="wrap">
<header class="hero"><small>A RAINY NIGHT · ADULT FAMILY DRAMA</small><h1>雨夜来客</h1><p>哥哥欠债失踪后，36岁的嫂子带着18岁的女儿，在暴雨夜带着两只行李箱和一袋零散账单敲响了你的门。母女身无分文，原住处无法返回，也没有任何亲友或其他地方能够收留她们。</p><div class="tags"><span class="tag">共同生活</span><span class="tag">债务谜团</span><span class="tag">双成人路线</span><span class="tag">动态内心</span><span class="tag">身体状态</span><span class="tag">自定义玩家</span></div></header>
<nav class="tabs"><button class="tab active" data-pane="story">作品档案</button><button class="tab" data-pane="profile">自定义玩家</button></nav>
<section id="story" class="pane active">
<div class="card"><h2>☔ 开场局面</h2><p>周世杰经营失败、留下多笔来历不明的债务后失联。催债者频繁上门，林晚晴为了母女安全，只能带着女儿前来向身为弟弟的成年{{user}}求助。她们身无分文，原住处已无法返回，亲友也无人愿意或有能力收留，当晚没有旅馆、朋友家或其他安全落脚处可去，只能恳求{{user}}暂时收留。是否答应、如何安排共同生活、谁该承担债务以及哥哥去了哪里，仍由玩家决定。</p></div>
<div class="card"><h2>👥 人物档案</h2><div class="people">
<article class="person"><small>36岁 · 嫂子</small><b>林晚晴</b><p>168cm、58kg，95/70/96，D杯。成熟丰润的梨形身材，腰腹柔软，臀腿饱满，日常穿着克制利落。她准备了一个只有遭到拒绝时才可能启用的秘密杀手锏；即使没有使用，这个念头也会长期留在内心。</p><div class="stats"><div class="stat"><span>身高</span><strong>168cm</strong></div><div class="stat"><span>体重</span><strong>58kg</strong></div><div class="stat"><span>罩杯</span><strong>D</strong></div><div class="stat"><span>三围</span><strong>95/70/96</strong></div></div></article>
<article class="person"><small>18岁 · 侄女</small><b>周若宁</b><p>163cm、50kg，86/60/88，C杯。纤细匀称、腰线明显，动作轻快。刚高中毕业，从小依赖叔叔；成年后的她活泼嘴硬、爱坏笑挑衅，是懂得边界的“雌小鬼”型成年人。</p><div class="stats"><div class="stat"><span>身高</span><strong>163cm</strong></div><div class="stat"><span>体重</span><strong>50kg</strong></div><div class="stat"><span>罩杯</span><strong>C</strong></div><div class="stat"><span>三围</span><strong>86/60/88</strong></div></div></article>
<article class="person"><small>39岁 · 失踪的哥哥</small><b>周世杰</b><p>债务与失踪原因均不明确，需要从合同、转账、通讯和来访者证词中逐步调查。</p></article>
<article class="person"><small>成年 · 玩家</small><b>{{user}}</b><p>周世杰的弟弟、林晚晴的小叔子、周若宁的叔叔。姓名、外貌、体型、职业、资产、住房、经验、偏好与边界均可自定义。</p></article>
</div></div>
<div class="card"><h2>✦ 成人路线规则</h2><div class="notice">林晚晴与周若宁均为成年人，分别拥有独立的恋爱与成人路线。雨夜投奔、无处可去的处境和此后的共同生活都可以直接成为路线起点，不要求先完成固定恋爱阶段、好感门槛或指定回合。嫂子的秘密预案在玩家明确拒绝收留后，也可触发一次成人路线的选择节点。玩家可以接受、拒绝、追问、谈条件、改变话题、只提供普通收留，或以自己的方式推进任意路线；系统不会替玩家作决定。进入具体成人行为前，相关成年人仍需在当轮清醒并明确表达意愿。</div></div>
</section>
<section id="profile" class="pane">
<div class="card"><h2>✦ 身份与身体档案</h2><div class="grid">
<div class="field"><label>姓名或称呼</label><input id="p-name" class="input" placeholder="如：周砚 / 阿砚"></div>
<div class="field"><label>年龄（必须满18岁）</label><input id="p-age" class="input" type="number" min="18" max="80" value="30"></div>
<div class="field"><label>固定家庭身份</label><div class="fixed">周世杰的成年弟弟 · 林晚晴的小叔子 · 周若宁的叔叔</div></div>
<div class="field"><label>职业</label><input id="p-job" class="input" placeholder="如：公司管理层 / 律师 / 个体经营"></div>
<div class="field"><label>身高（cm）</label><input id="p-height" class="input" type="number" min="140" max="230" placeholder="180"></div>
<div class="field"><label>体重（kg）</label><input id="p-weight" class="input" type="number" min="40" max="250" placeholder="78"></div>
<div class="field"><label>体型与外貌</label><input id="p-build" class="input" placeholder="如：肩背宽阔、短发、神情沉稳"></div>
<div class="field"><label>私密身体资料（可留空）</label><input id="p-private" class="input" placeholder="只填写希望剧情明确采用的成年身体资料"></div>
<div class="field full"><label>与哥哥一家的既往关系</label><textarea id="p-history" class="input" placeholder="如：哥哥常年疏远，若宁小时候经常由我照顾，和嫂子一直保持礼貌距离。"></textarea></div>
</div></div>
<div class="card"><h2>💰 住房与经济档案</h2><div class="grid">
<div class="field"><label>住房情况</label><input id="p-home" class="input" placeholder="如：市中心三居室，全款独居"></div>
<div class="field"><label>当前可用现金</label><input id="p-cash" class="input" placeholder="如：5万元"></div>
<div class="field"><label>月收入</label><input id="p-income" class="input" placeholder="如：税后3万元"></div>
<div class="field"><label>存款／投资</label><input id="p-savings" class="input" placeholder="如：存款80万，有少量基金"></div>
<div class="field"><label>个人负债</label><input id="p-debt" class="input" placeholder="如：无负债 / 尚有120万房贷"></div>
<div class="field"><label>可动用的人脉或资源</label><input id="p-resource" class="input" placeholder="如：律师朋友、银行渠道、警方熟人"></div>
</div></div>
<div class="card"><h2>⚖️ 立场、偏好与边界</h2>
<div class="field"><label>对留宿请求的态度</label><select id="p-attitude" class="input"><option>先让母女安全住下，再核对事实</option><option>可以短住，但必须约定期限和家规</option><option>愿意长期提供住处，但不替哥哥承担未知债务</option><option>暂不收留，先协助安排其他安全住处</option></select></div>
<div class="field"><label>当前感情倾向</label><select id="p-route" class="input"><option>暂不选择路线，先处理现实问题</option><option>更关注林晚晴，但不会利用她的困境</option><option>更关注成年后的周若宁，但会重新确认关系边界</option><option>保持开放，让关系随剧情自然变化</option></select></div>
<div class="field"><label>成年感情经验与偏好（可留空）</label><textarea id="p-pref" class="input" placeholder="填写希望影响亲密节奏、互动方式和描写重点的偏好。"></textarea></div>
<div class="field"><label>明确边界／绝对禁止事项</label><textarea id="p-boundary" class="input" placeholder="如：不接受胁迫、醉酒推进或用金钱和住处交换亲密；任何人说停都必须停止。"></textarea></div>
<div class="field"><label>其他补充</label><textarea id="p-extra" class="input" placeholder="可补充性格、恋爱状态、生活习惯、车辆、公司或其他资产。"></textarea></div>
</div>
<div class="card"><h2>📋 玩家档案预览</h2><p class="tip">点击生成后复制到聊天框发送；未填写项目继续采用作品默认值。</p><div id="preview" class="preview"></div><button id="copy" class="btn" type="button">生成并复制玩家档案</button><div id="toast" class="toast">✓ 已复制，请回到聊天中粘贴发送</div></div>
</section>
</main>
<script>
function q(s){return document.querySelector(s)}function v(s){var e=q(s);return e&&e.value?e.value.trim():""}function profile(){var age=Math.max(18,Number(v("#p-age"))||30);return["【雨夜来客｜玩家自定义档案】","姓名或称呼："+(v("#p-name")||"未指定"),"年龄："+age+"岁","固定身份：周世杰的成年弟弟、林晚晴的小叔子、周若宁的叔叔","职业："+(v("#p-job")||"未指定"),"身体资料：身高"+(v("#p-height")||"未指定")+"cm｜体重"+(v("#p-weight")||"未指定")+"kg｜体型外貌："+(v("#p-build")||"未补充")+"｜私密资料："+(v("#p-private")||"未填写，不得擅自推定"),"既往家庭关系："+(v("#p-history")||"未补充，沿用默认"),"【住房与经济】","住房："+(v("#p-home")||"未指定"),"可用现金："+(v("#p-cash")||"未指定"),"月收入："+(v("#p-income")||"未指定"),"存款／投资："+(v("#p-savings")||"未指定"),"个人负债："+(v("#p-debt")||"未指定"),"可动用资源："+(v("#p-resource")||"未指定"),"【当前立场】","留宿态度："+v("#p-attitude"),"感情倾向："+v("#p-route"),"成年感情经验与偏好："+(v("#p-pref")||"未填写，不得擅自推定"),"明确边界："+(v("#p-boundary")||"未额外填写，仍须遵守清醒、自愿和随时撤回规则"),"其他补充："+(v("#p-extra")||"无"),"【采用规则】以上内容只覆盖{{user}}资料，不修改林晚晴、周若宁、周世杰、既有关系和已发生事件；经济帮助与住处不代表任何具体亲密同意。"].join("\n")}function render(){q("#preview").textContent=profile()}document.querySelectorAll(".tab").forEach(function(b){b.addEventListener("click",function(){document.querySelectorAll(".tab").forEach(function(x){x.classList.remove("active")});document.querySelectorAll(".pane").forEach(function(x){x.classList.remove("active")});b.classList.add("active");q("#"+b.dataset.pane).classList.add("active")})});document.querySelectorAll(".input").forEach(function(x){x.addEventListener("input",render)});q("#copy").addEventListener("click",async function(){var t=profile();try{await navigator.clipboard.writeText(t)}catch(e){var x=document.createElement("textarea");x.value=t;document.body.appendChild(x);x.select();document.execCommand("copy");x.remove()}q("#toast").style.display="block";setTimeout(function(){q("#toast").style.display="none"},2400)});render();
</script>
</body>
</html>', '👩‍👧 熟女母女', '2026-09-14 14:01:08', '2026-09-14 14:01:08') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at) VALUES ('deck_apocalypse_survival', '😱 末世求生录 😱 生存·性暴力·屈辱·征服·调教·末日', '末日废土 · 极境生存', '☣️', '末世求生录', '丧尸瘟疫核冬天 · 废土人性征服', '☣️', '#e17055', 'linear-gradient(135deg, #e17055 0%, #d63031 100%)', '{"desc": "在崩溃的世界中挣扎求生，你的极限生存在多少天。玩家在开局选择末世类型（丧尸、核战、瘟疫等22种题材），在资源匮乏、危机四伏的废土中寻找生存之路。体力、饥饿、口渴与性压抑的人性试炼。", "author": "AI风月精选"}', '[{"name": "苏晓染", "role": "21岁医学院校花幸存者 (167cm / 49kg / D罩杯)", "desc": "灾变前是全校公认的高岭之花医学生。末日爆发后在外独自逃亡三天，弹尽粮绝、衣衫破烂。为了获得一口干净的水和避难所的接纳，尊严与骄傲已被现实碾得粉碎，愿意接受一切屈辱的生存交换。"}, {"name": "玩家 (避难所支配者)", "role": "废土安全屋主宰", "desc": "掌控坚固地下防空洞、充足柴油、纯净水与武器储备的冷酷生存大师。"}]', '[{"title": "地下防空洞核心安全屋", "desc": "重型防爆钢门紧闭，柴油发电机轰鸣，桌上摆着纯净水与压缩饼干"}, {"title": "避难所消毒与检疫铁笼", "desc": "泛着锈迹与血斑的铁栏，剥光衣物进行全身体表感染排查的冰冷之地"}, {"title": "地表废墟物资搜刮掩体", "desc": "辐射酸雨滋滋作响的装甲车废墟，丧尸与掠夺者游荡的危险荒原"}]', '{}', '{"location": "避难所地下核心安全屋 · 辐射暴雨夜", "story": "厚重斑驳的防爆钢门将外界丧尸刺耳的抓挠声与酸雨腐蚀声彻底隔绝。\n防空洞深处，柴油发电机发出沉闷有力的轰鸣，昏黄的白炽灯在金属墙壁上投下斑驳长影。你坐在弹药箱上擦拭着自动霰弹枪，旁边的折叠桌上整齐地摆放着两瓶密封矿泉水、三袋军用高能压缩饼干与几板未拆封的阿莫西林抗生素——在这片秩序崩坏的废土上，这些就是主宰生死的硬通货。\n沉重的安全门闸传来转动声，一个被守卫反绑双手的年轻女人被粗暴地推倒在冰冷的水泥地上。\n她曾是医学院万人瞩目的清纯校花苏晓染。此刻，她身上的白衬衫与牛仔裤已被撕裂得多处走光，白皙如玉的肌肤上满是泥泞与擦伤，胸前发育绝佳的D罩杯双峰随着剧烈喘息大幅度起伏。干裂泛白的嘴唇紧紧抿着，饥饿与干渴让她浑身不受控制地发颤，眼神在触及桌上矿泉水的瞬间爆发出野兽般贪婪而绝望的渴望：“求求你……给我一口水喝……只要让我留在这……你让我做什么都可以……”", "branches": [{"tag": "A", "title": "拧开水壶倒出一小杯清水，命令她像狗一样爬过来喝", "desc": "以残酷的废土生存法则直接剥夺其残存的文明自尊，建立绝对的主奴支配从属【屈辱驯服: 击碎昔日校花自尊，以物资确立终身依附】"}, {"tag": "B", "title": "递过抗生素与半块压缩饼干，严肃考查其临床医学价值", "desc": "保持冷静克制，利用食物交换其医疗技能为庇护所团队服务【理性统合: 评估实用价值，建立高效分工契约】"}, {"tag": "C", "title": "举枪冷漠示意她退后，命令其当场脱光接受感染排查", "desc": "严厉执行末世防疫铁律，要求其脱掉所有衣物仔细检查全身有无抓伤咬痕【严苛检疫: 杜绝致命隐患，借检疫之名将春光尽收眼底】"}, {"tag": "D", "title": "反锁厚重防爆门，居高临下挑起她下巴行使领主特权", "desc": "当着她的面关上唯一生路，用粗糙的掌心揉捏其下颌迫使其屈从献身【强势占有: 撕碎所有文明遮羞布，直接确立私人肉便器地位】"}]}', '/* --- 末世科技风格（暗色系红色点缀）--- */

/* 1. 全局包裹层：高科技废土 */
.survival-interface {
    background: linear-gradient(135deg, #1a1d23 0%, #0f1115 100%);
    border-radius: 16px;
    padding: 24px;
    box-shadow: 
        0 20px 60px rgba(0, 0, 0, 0.5),
        0 0 0 1px rgba(239, 68, 68, 0.05) inset;
    position: relative;
    color: #c4c4c4;
    font-family: ''Segoe UI'', ''Roboto'', ''Microsoft YaHei'', sans-serif;
    line-height: 1.7;
    max-width: 900px;
    margin: 0 auto;
    overflow: hidden;
}

/* 顶部光晕效果 */
.survival-interface::after {
    content: '''';
    position: absolute;
    top: -50%; left: -50%;
    width: 200%; height: 200%;
    background: radial-gradient(circle at 20% 20%, rgba(239, 68, 68, 0.08) 0%, transparent 50%);
    pointer-events: none;
}

/* --- 1. 时间轴：现代终端风格 --- */
code.language-Time {
    display: block;
    background: linear-gradient(135deg, #0a0c10 0%, #13151a 100%);
    border: 1px solid rgba(239, 68, 68, 0.2);
    border-left: 4px solid #dc2626;
    padding: 16px 24px;
    color: #fca5a5;
    font-family: ''JetBrains Mono'', ''Fira Code'', monospace;
    margin-bottom: 24px;
    white-space: pre-wrap;
    box-shadow: 
        0 4px 20px rgba(0, 0, 0, 0.3),
        inset 0 1px 0 rgba(255, 255, 255, 0.05);
    position: relative;
    border-radius: 8px;
}

/* --- 2. 折叠栏：玻璃卡片风格 --- */
details {
    border-radius: 12px;
    overflow: hidden;
    background: transparent;
    border: none;
    margin-bottom: 12px;
    transition: all 0.3s ease;
}

details[open] {
    /* 打开时不需要额外样式 */
}

summary {
    display: flex;
    align-items: center;
    padding: 16px 24px;
    font-weight: 600;
    color: #e0e0e0;
    background: rgba(26, 29, 35, 0.8);
    cursor: pointer;
    list-style: none;
    text-transform: uppercase;
    letter-spacing: 1px;
    transition: all 0.3s ease;
    position: relative;
    font-size: 14px;
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    backdrop-filter: blur(10px);
}

summary:hover {
    background: rgba(40, 44, 52, 0.9);
    color: #fff;
    border-color: rgba(239, 68, 68, 0.3);
}

/* 发光指示器 */
summary::before {
    content: ''▸'';
    margin-right: 12px;
    color: #dc2626;
    font-size: 12px;
    transition: transform 0.3s ease;
}

details[open] > summary::before {
    transform: rotate(90deg);
    color: #fca5a5;
}

/* 状态标签 */
summary::after {
    content: ''OFFLINE'';
    font-size: 10px;
    position: absolute;
    right: 24px;
    padding: 4px 10px;
    border-radius: 20px;
    background: rgba(239, 68, 68, 0.2);
    color: #ef4444;
    font-weight: 500;
    transition: all 0.3s ease;
}

details[open] > summary::after {
    content: ''ONLINE'';
    background: rgba(220, 38, 38, 0.2);
    color: #dc2626;
}

/* 🎯 折叠内容区：独立的深色卡片风格 */
details > *:not(summary) {
    background: linear-gradient(135deg, #252932 0%, #1a1d23 100%);
    margin-top: 8px;
    padding: 20px 24px;
    color: #c4c4c4;
    line-height: 1.7;
    font-size: 15px;
    position: relative;
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    box-shadow: 
        0 4px 20px rgba(0, 0, 0, 0.3),
        inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

/* --- 3. 警告与威胁：现代化徽章 --- */
.threat-level {
    background: linear-gradient(135deg, rgba(239, 68, 68, 0.15) 0%, rgba(239, 68, 68, 0.05) 100%);
    color: #ef4444;
    padding: 6px 14px;
    font-weight: 600;
    border-radius: 20px;
    font-size: 12px;
    border: 1px solid rgba(239, 68, 68, 0.3);
    text-transform: uppercase;
    letter-spacing: 1px;
    display: inline-flex;
    align-items: center;
    gap: 6px;
}

.threat-level::before {
    content: ''⚠'';
    font-size: 10px;
}

.threat-level.low {
    background: linear-gradient(135deg, rgba(245, 158, 11, 0.15) 0%, rgba(245, 158, 11, 0.05) 100%);
    color: #f59e0b;
    border-color: rgba(245, 158, 11, 0.3);
}

.threat-level.low::before {
    content: ''⚡'';
}

.threat-level.medium {
    background: linear-gradient(135deg, rgba(249, 115, 22, 0.15) 0%, rgba(249, 115, 22, 0.05) 100%);
    color: #f97316;
    border-color: rgba(249, 115, 22, 0.3);
}

.threat-level.medium::before {
    content: ''◆'';
}

.threat-level.high {
    background: linear-gradient(135deg, rgba(220, 38, 38, 0.2) 0%, rgba(220, 38, 38, 0.08) 100%);
    color: #dc2626;
    border-color: rgba(220, 38, 38, 0.5);
    animation: threat-pulse 2s ease-in-out infinite;
}

.threat-level.high::before {
    content: ''⚠'';
}

@keyframes threat-pulse {
    0%, 100% { 
        box-shadow: 0 0 0 0 rgba(220, 38, 38, 0.4);
    }
    50% { 
        box-shadow: 0 0 0 8px rgba(220, 38, 38, 0);
    }
}

/* --- 4. 记忆栏与档案：数据卡片风格 --- */
.memory-zone {
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: rgba(26, 29, 35, 0.4);
    padding: 0;
    border-radius: 12px;
    margin-top: 16px;
    overflow: hidden;
    backdrop-filter: blur(10px);
}

/* 档案标题 */
.memory-zone-header {
    display: block;
    background: linear-gradient(135deg, #dc2626 0%, #b91c1c 100%);
    color: #fff;
    padding: 14px 24px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 2px;
    font-size: 12px;
    position: relative;
}

.memory-zone-header::before {
    content: ''📊'';
    margin-right: 8px;
}

.memory-item {
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
    padding: 14px 24px;
    position: relative;
    transition: all 0.3s ease;
    color: #c4c4c4;
}

.memory-item::before {
    content: '''';
    position: absolute;
    left: 12px;
    top: 50%;
    transform: translateY(-50%);
    width: 4px;
    height: 4px;
    background: #dc2626;
    border-radius: 50%;
    box-shadow: 0 0 8px rgba(220, 38, 38, 0.5);
}

.memory-item:hover {
    background: rgba(220, 38, 38, 0.05);
    padding-left: 32px;
}

.memory-item:last-child {
    border-bottom: none;
}

/* --- 5. 分割线：现代分割线 --- */
hr {
    border: 0;
    height: 1px;
    background: linear-gradient(to right, transparent, rgba(239, 68, 68, 0.1), transparent);
    margin: 32px 0;
    position: relative;
}

/* --- 6. 强调文本：高亮标记 --- */
strong {
    color: #fca5a5;
    background: rgba(239, 68, 68, 0.1);
    padding: 2px 8px;
    border-radius: 4px;
    font-weight: 600;
}

/* --- 7. 状态块和选项块：代码编辑器风格 --- */
.status-block, .options-block {
    background: linear-gradient(135deg, #0f1115 0%, #1a1d23 100%);
    border-radius: 12px;
    padding: 20px 24px;
    font-family: ''JetBrains Mono'', ''Fira Code'', monospace;
    font-size: 14px;
    line-height: 1.8;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-left: 4px solid #dc2626;
    white-space: pre-wrap;
    word-break: break-word;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.2);
    color: #c4c4c4;
    position: relative;
}

/* 行号装饰 */
.status-block::before,
.options-block::before {
    content: '''';
    position: absolute;
    top: 0; left: 0; width: 4px; height: 100%;
    background: linear-gradient(180deg, #dc2626 0%, #b91c1c 100%);
}

/* --- 8. 响应式调整 --- */
@media (max-width: 768px) {
    .survival-interface {
        padding: 16px;
        border-radius: 12px;
    }
    
    summary {
        padding: 14px 20px;
        font-size: 13px;
    }
    
    summary::after {
        right: 20px;
        font-size: 9px;
    }
    
    .memory-zone-header {
        font-size: 11px;
        padding: 12px 20px;
    }
    
    .memory-item {
        padding: 12px 20px;
        font-size: 14px;
    }
    
    .status-block, .options-block {
        padding: 16px 20px;
        font-size: 13px;
    }
    
    details > *:not(summary) {
        padding: 16px 20px;
        font-size: 14px;
    }
}

/* --- 9. 对话颜色规范（现代风格）--- */
/* 玩家言语（暗红色） */
font[color="#00c6c6"],
.dialog-player {
    color: #ef4444 !important;
    font-weight: 600;
    background: rgba(239, 68, 68, 0.1);
    padding: 2px 8px;
    border-radius: 4px;
}

/* 女性NPC言语（粉紫色） */
font[color="#FF2D2D"],
.dialog-female {
    color: #fca5a5 !important;
    font-style: italic;
    background: rgba(252, 165, 165, 0.1);
    padding: 2px 8px;
    border-radius: 4px;
}

/* 男性NPC言语（橙红色） */
font[color="#ea0029"],
.dialog-male {
    color: #f97316 !important;
    font-weight: 600;
    background: rgba(249, 115, 22, 0.1);
    padding: 2px 8px;
    border-radius: 4px;
}

/* --- 10. 实用工具类 --- */
.glow-indigo {
    color: #dc2626;
    text-shadow: 0 0 20px rgba(220, 38, 38, 0.5);
}

.border-glass {
    border: 1px solid rgba(255, 255, 255, 0.1);
    backdrop-filter: blur(10px);
}

.bg-dark-tech {
    background: linear-gradient(135deg, #1a1d23 0%, #0f1115 100%);
}

.text-gradient {
    background: linear-gradient(135deg, #dc2626 0%, #ef4444 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.card-hover {
    transition: all 0.3s ease;
}

.card-hover:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>末世生存档案</title>
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    /* --- 末世科技风格 (精致版) --- */
    
    body {
      margin: 0;
      padding: 0;
      font-family: ''Segoe UI'', ''Roboto'', ''Microsoft YaHei'', sans-serif;
      background: url(''https://i.postimg.cc/J0hd1jJ6/1.png'') center/cover no-repeat fixed;
      min-height: 100vh;
      color: #c4c4c4;
      line-height: 1.7;
    }
    
    body::before {
      content: '''';
      position: fixed;
      top: 0; left: 0; width: 100%; height: 100%;
      background: linear-gradient(135deg, rgba(0, 0, 0, 0.3) 0%, rgba(0, 0, 0, 0.4) 100%);
      z-index: 0;
    }
    
    .tech-container {
      position: relative;
      min-height: 100vh;
      padding: 24px;
      z-index: 1;
    }
    
    .tech-music-btn {
      width: 56px;
      height: 56px;
      background: linear-gradient(135deg, #252932 0%, #1a1d23 100%);
      border: 2px solid rgba(255, 255, 255, 0.1);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      transition: all 0.3s ease;
      box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);
      position: relative;
      z-index: 10;
      pointer-events: auto;
    }
    
    .tech-music-btn:hover {
      transform: scale(1.1);
      border-color: rgba(255, 255, 255, 0.3);
      box-shadow: 0 6px 20px rgba(0, 0, 0, 0.4), 0 0 20px rgba(255, 255, 255, 0.1);
    }
    
    .tech-action-card {
      background: linear-gradient(135deg, #252932 0%, #1a1d23 100%);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 12px;
      padding: 12px 24px;
      min-width: 200px;
      cursor: pointer;
      transition: all 0.3s ease;
      position: relative;
      box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2);
    }
    
    .tech-action-card:hover {
      transform: translateY(-2px);
      border-color: rgba(255, 255, 255, 0.2);
      box-shadow: 0 6px 25px rgba(0, 0, 0, 0.3), 0 0 20px rgba(255, 255, 255, 0.05);
    }
    
    .tech-action-card::before {
      content: '''';
      position: absolute;
      top: -4px;
      left: 50%;
      transform: translateX(-50%);
      width: 40px;
      height: 12px;
      background: rgba(255, 255, 255, 0.05);
      border-radius: 6px;
      backdrop-filter: blur(5px);
    }
    
    .tech-modal-overlay {
      position: fixed;
      inset: 0;
      background: rgba(0, 0, 0, 0.8);
      backdrop-filter: blur(10px);
      z-index: 50;
      display: none;
      align-items: center;
      justify-content: center;
      padding: 24px;
    }
    
    .tech-modal-overlay.active {
      display: flex;
    }
    
    .tech-modal {
      background: linear-gradient(135deg, #252932 0%, #1a1d23 100%);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 16px;
      max-width: 800px;
      width: 100%;
      max-height: 80vh;
      display: flex;
      flex-direction: column;
      overflow: hidden;
      box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
    }
    
    .tech-modal-header {
      padding: 24px;
      border-bottom: 1px solid rgba(255, 255, 255, 0.1);
      display: flex;
      justify-content: space-between;
      align-items: center;
      background: rgba(0, 0, 0, 0.2);
    }
    
    .tech-modal-content {
      padding: 24px;
      overflow-y: auto;
      flex: 1;
    }
    
    .tech-modal-content::-webkit-scrollbar {
      width: 8px;
    }
    
    .tech-modal-content::-webkit-scrollbar-track {
      background: rgba(0, 0, 0, 0.2);
    }
    
    .tech-modal-content::-webkit-scrollbar-thumb {
      background: rgba(255, 255, 255, 0.2);
      border-radius: 4px;
    }
    
    .tech-input {
      width: 100%;
      padding: 12px 16px;
      background: rgba(0, 0, 0, 0.3);
      border: 1px solid rgba(255, 255, 255, 0.1);
      border-radius: 8px;
      color: #c4c4c4;
      font-size: 14px;
      transition: all 0.3s ease;
      font-family: inherit;
    }
    
    .tech-input:focus {
      outline: none;
      border-color: rgba(255, 255, 255, 0.3);
      box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.05);
    }
    
    .tech-input::placeholder {
      color: rgba(196, 196, 196, 0.5);
    }
    
    .tech-label {
      display: block;
      margin-bottom: 8px;
      color: #e0e0e0;
      font-size: 12px;
      font-weight: 500;
    }
    
    .tech-btn {
      padding: 10px 20px;
      background: linear-gradient(135deg, #ffffff 0%, #d4d4d4 100%);
      color: #1a1d23;
      border: none;
      border-radius: 8px;
      font-weight: 600;
      cursor: pointer;
      transition: all 0.3s ease;
      font-size: 14px;
    }
    
    .tech-btn:hover {
      transform: translateY(-1px);
      box-shadow: 0 4px 15px rgba(255, 255, 255, 0.2);
    }
    
    .tech-btn:disabled {
      opacity: 0.4;
      cursor: not-allowed;
      text-decoration: line-through;
    }
    
    .tech-toast {
      position: fixed;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
      z-index: 60;
      display: none;
      align-items: center;
      justify-content: center;
      pointer-events: none;
    }
    
    .tech-toast.active {
      display: flex;
    }
    
    .tech-toast-content {
      background: linear-gradient(135deg, #252932 0%, #1a1d23 100%);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 12px;
      padding: 16px 24px;
      box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
      pointer-events: auto;
    }
    
    .tech-info-block {
      background: rgba(0, 0, 0, 0.3);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 12px;
      padding: 16px;
      margin-bottom: 16px;
    }
    
    .tech-info-block-title {
      font-size: 12px;
      font-weight: 600;
      color: #ffffff;
      margin-bottom: 12px;
      text-transform: uppercase;
      letter-spacing: 2px;
    }
    
    .tech-preview-item {
      background: rgba(0, 0, 0, 0.3);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 8px;
      padding: 12px 16px;
      margin-bottom: 8px;
    }
    
    .tech-preview-label {
      color: #ffffff;
      font-size: 13px;
      font-weight: 600;
    }
    
    .tech-preview-value {
      color: #c4c4c4;
      font-size: 14px;
      margin-top: 4px;
    }
    
    details {
      border-radius: 12px;
      overflow: hidden;
      background: transparent;
      border: none;
      margin-bottom: 12px;
      transition: all 0.3s ease;
    }
    
    summary {
      display: flex;
      align-items: center;
      padding: 16px 24px;
      font-weight: 600;
      color: #e0e0e0;
      background: rgba(26, 29, 35, 0.8);
      cursor: pointer;
      list-style: none;
      text-transform: uppercase;
      letter-spacing: 1px;
      transition: all 0.3s ease;
      position: relative;
      font-size: 14px;
      border-radius: 12px;
      border: 1px solid rgba(255, 255, 255, 0.08);
      backdrop-filter: blur(10px);
    }
    
    summary:hover {
      background: rgba(40, 44, 52, 0.9);
      color: #fff;
      border-color: rgba(255, 255, 255, 0.2);
    }
    
    summary::before {
      content: ''▸'';
      margin-right: 12px;
      color: #ffffff;
      font-size: 12px;
      transition: transform 0.3s ease;
    }
    
    details[open] > summary::before {
      transform: rotate(90deg);
      color: #ffffff;
    }
    
    details[open] > summary {
      background: rgba(0, 0, 0, 0.4);
      border-bottom: 1px solid rgba(255, 255, 255, 0.2);
      border-radius: 12px 12px 0 0;
    }
    
    details > *:not(summary) {
      background: linear-gradient(135deg, #252932 0%, #1a1d23 100%);
      margin-top: 0;
      padding: 20px 24px;
      color: #c4c4c4;
      line-height: 1.7;
      font-size: 15px;
      position: relative;
      border-radius: 0 0 12px 12px;
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-top: none;
      box-shadow: 
        0 4px 20px rgba(0, 0, 0, 0.3),
        inset 0 1px 0 rgba(255, 255, 255, 0.05);
    }
    
    .checkbox-wrapper {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 12px;
      background: rgba(0, 0, 0, 0.3);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 8px;
      cursor: pointer;
      transition: all 0.3s ease;
    }
    
    .checkbox-wrapper:hover {
      border-color: rgba(255, 255, 255, 0.2);
      background: rgba(0, 0, 0, 0.4);
    }
    
    .checkbox-wrapper input[type="checkbox"] {
      width: 20px;
      height: 20px;
      accent-color: #ffffff;
      cursor: pointer;
    }
    
    .country-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(100px, 1fr));
      gap: 8px;
    }
    
    .country-btn, .region-type-btn, .job-btn {
      padding: 8px 12px;
      background: rgba(0, 0, 0, 0.3);
      border: 1px solid rgba(255, 255, 255, 0.1);
      border-radius: 6px;
      color: #c4c4c4;
      cursor: pointer;
      transition: all 0.3s ease;
      font-size: 12px;
    }
    
    .country-btn:hover, .country-btn.selected, .region-type-btn:hover, .region-type-btn.selected, .job-btn:hover, .job-btn.selected {
      background: rgba(255, 255, 255, 0.1);
      border-color: rgba(255, 255, 255, 0.3);
      color: #fff;
    }
    
    .country-btn.selected, .region-type-btn.selected, .job-btn.selected {
      background: rgba(255, 255, 255, 0.2);
      box-shadow: 0 0 10px rgba(255, 255, 255, 0.2);
    }
    
    .timeline-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 12px;
    }
    
    .timeline-btn {
      padding: 16px;
      background: rgba(0, 0, 0, 0.3);
      border: 1px solid rgba(255, 255, 255, 0.1);
      border-radius: 8px;
      color: #c4c4c4;
      cursor: pointer;
      transition: all 0.3s ease;
      text-align: center;
    }
    
    .timeline-btn:hover, .timeline-btn.selected {
      background: rgba(255, 255, 255, 0.1);
      border-color: rgba(255, 255, 255, 0.3);
      color: #fff;
      transform: translateY(-2px);
    }
    
    .timeline-btn.selected {
      background: rgba(255, 255, 255, 0.2);
      box-shadow: 0 4px 15px rgba(255, 255, 255, 0.15);
    }
    
    @media (max-width: 768px) {
      .tech-container {
        padding: 16px;
      }
      
      .tech-action-card {
        width: calc(50% - 8px);
        padding: 10px 16px;
        min-width: unset;
      }
      
      .timeline-grid {
        grid-template-columns: 1fr;
      }
      
      .country-grid {
        grid-template-columns: repeat(2, 1fr);
      }
    }
  </style>
</head>
<body>
  <div class="bg-grid"></div>
  <div class="bg-glow"></div>
  
  <div id="app" class="tech-container">
    <!-- 音频元素 -->
    <audio id="bg-music" loop preload="auto">
      <source src="https://cdn.jsdelivr.net/gh/QingFgg/xueshizi/xueshizi.mp3" type="audio/mpeg" />
      <source src="https://raw.githubusercontent.com/QingFgg/xueshizi/main/xueshizi.mp3" type="audio/mpeg" />
    </audio>
    
    <!-- 主要内容 -->
    <div class="flex flex-col min-h-[calc(100vh-48px)]">
      <!-- 顶部区域 - 音乐按钮 -->
      <div class="flex justify-end mb-8">
        <button id="music-ctrl" class="tech-music-btn">
          <span class="text-2xl">🔇</span>
        </button>
      </div>
      
      <!-- 下方的功能按钮 -->
      <div class="flex-1 flex flex-col justify-end pb-8">
        <div class="max-w-5xl mx-auto w-full">
          <div class="flex flex-wrap md:flex-nowrap justify-center gap-4">
            <!-- 功能按钮1 - 作者劝告 -->
            <div class="tech-action-card" onclick="openModal(''advice'')">
              <div class="flex items-center justify-center gap-2">
                <span class="text-xl">⚠️</span>
                <span class="text-white font-medium">作者劝告</span>
              </div>
            </div>
            
            <!-- 功能按钮2 - 世界背景 -->
            <div class="tech-action-card" onclick="openModal(''world'')">
              <div class="flex items-center justify-center gap-2">
                <span class="text-xl">🌍</span>
                <span class="text-white font-medium">世界背景</span>
              </div>
            </div>
            
            <!-- 功能按钮3 - 角色创建 -->
            <div class="tech-action-card" onclick="openModal(''custom'')">
              <div class="flex items-center justify-center gap-2">
                <span class="text-xl">🎮</span>
                <span class="text-white font-medium">角色创建</span>
              </div>
            </div>
            
            <!-- 功能按钮4 - 角色档案 -->
            <div class="tech-action-card" onclick="openModal(''preview'')">
              <div class="flex items-center justify-center gap-2">
                <span class="text-xl">📋</span>
                <span class="text-white font-medium">角色档案</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
    
    <!-- 弹窗遮罩 -->
    <div id="modalOverlay" class="tech-modal-overlay" onclick="closeModal()">
      <div class="tech-modal" onclick="event.stopPropagation()">
        <!-- 弹窗头部 -->
        <div class="tech-modal-header">
          <h2 id="modalTitle" class="text-xl font-bold text-white"></h2>
          <button onclick="closeModal()" class="text-gray-400 hover:text-white text-2xl transition-colors">✕</button>
        </div>
        <!-- 弹窗内容 -->
        <div id="modalContent" class="tech-modal-content"></div>
      </div>
    </div>
    
    <!-- 提示框 -->
    <div id="toastOverlay" class="tech-toast">
      <div class="tech-toast-content">
        <div class="flex items-center gap-2">
          <span id="toastIcon" class="text-xl">✅</span>
          <span id="toastText" class="text-white font-medium">操作成功</span>
        </div>
      </div>
    </div>
    
    <!-- 警告弹窗 -->
    <div id="warningOverlay" class="tech-modal-overlay" style="z-index: 100;">
      <div class="tech-modal" style="max-width: 400px;">
        <div class="tech-modal-header" style="border-color: rgba(239, 68, 68, 0.3);">
          <h2 class="text-xl font-bold text-red-400">⚠️ 内容警告</h2>
        </div>
        <div class="tech-modal-content text-center">
          <p class="text-gray-300 mb-6">本卡随机事件紧凑，生存难度极高，内容可能引起不适，不喜欢这类可以退出，请勿随意差评！   ** 请谨慎选择 **</p>
          <button onclick="closeWarning()" class="tech-btn w-full">我已知晓</button>
        </div>
      </div>
    </div>

    <!-- 音乐初始化弹窗 -->
    <div id="music-init" class="tech-modal-overlay" style="z-index: 99;">
      <div class="tech-modal" style="max-width: 400px;">
        <div class="tech-modal-header" style="border-color: rgba(239, 68, 68, 0.3);">
          <h2 class="text-xl font-bold text-red-400">🎵 背景音乐</h2>
        </div>
        <div class="tech-modal-content text-center">
          <p class="text-gray-300 mb-4">是否开启沉浸背景音乐？</p>
          <p class="text-xs text-gray-400 mb-6"><span style="color: red;">(需要开启VPN因为音乐是GitHub部署的)</span></p>
          <div class="space-y-3">
            <button onclick="initMusic(true)" class="tech-btn w-full">开启播放</button>
            <button onclick="initMusic(false)" class="tech-btn w-full" style="background: linear-gradient(135deg, #555 0%, #444 100%);">保持静音</button>
          </div>
        </div>
      </div>
    </div>
  </div>

  <script>
    var memoryStorage = {};
    var useLocalStorage = true;
    
    function isLocalStorageAvailable() {
      try {
        var test = ''__test__'';
        localStorage.setItem(test, test);
        localStorage.removeItem(test);
        return true;
      } catch (e) {
        return false;
      }
    }
    
    function isFileProtocol() {
      return window.location.protocol === ''file:'';
    }
    
    function saveData(key, value) {
      if (useLocalStorage && isLocalStorageAvailable()) {
        localStorage.setItem(key, value);
      } else {
        memoryStorage[key] = value;
      }
    }
    
    function loadData(key) {
      if (useLocalStorage && isLocalStorageAvailable()) {
        return localStorage.getItem(key);
      } else {
        return memoryStorage[key] || null;
      }
    }
    
    function initApp() {
      console.log(''initApp 开始执行'');
      var app = document.getElementById(''app'');
      if (!app) {
        console.error(''App element not found'');
        return;
      }
      console.log(''App 元素找到，继续执行'');

      // 检查音频元素
      bgMusic = document.getElementById(''bg-music'');
      if (!bgMusic) {
        console.warn(''音频元素未找到'');
      } else {
        console.log(''音频元素已找到，readyState:'', bgMusic.readyState);
        // 监听音频加载事件
        bgMusic.addEventListener(''error'', function(e) {
          console.error(''音频加载错误:'', e);
          alert(''音乐文件加载失败，可能是网络问题或CDN访问受限'');
        });
      }
      
      // 显示警告弹窗
      var warningOverlay = document.getElementById(''warningOverlay'');
      if (warningOverlay) {
        warningOverlay.classList.add(''active'');
      }
      
      window.showToast = function(message, icon) {
        var toastOverlay = document.getElementById(''toastOverlay'');
        var toastText = document.getElementById(''toastText'');
        var toastIcon = document.getElementById(''toastIcon'');
        if (!toastOverlay || !toastText || !toastIcon) return;
        
        toastText.textContent = message;
        toastIcon.textContent = icon || ''✅'';
        
        toastOverlay.classList.add(''active'');
        setTimeout(function() {
          toastOverlay.classList.remove(''active'');
        }, 2000);
      };
      
      // 音乐控制
      var bgMusic = document.getElementById(''bg-music'');
      var musicCtrl = document.getElementById(''music-ctrl'');
      var isPlaying = false;
      var musicRetryCount = 0;
      var maxRetries = 3;
      
      // 音乐初始化
      window.initMusic = function(shouldPlay) {
        var musicInit = document.getElementById(''music-init'');
        if (musicInit) {
          musicInit.classList.remove(''active'');
        }
        
        if (shouldPlay && bgMusic) {
          // 重置重试计数
          musicRetryCount = 0;
          
          // 设置音量
          bgMusic.volume = 0.3;
          
          // 尝试加载音频
          if (bgMusic.readyState === 0) {
            // 音频未加载，等待加载完成
            bgMusic.addEventListener(''canplaythrough'', function onCanPlay() {
              bgMusic.removeEventListener(''canplaythrough'', onCanPlay);
              playMusic();
            }, { once: true });
            
            // 设置超时
            setTimeout(function() {
              if (bgMusic.readyState < 2) {
                console.warn(''音频加载超时，尝试播放'');
                playMusic();
              }
            }, 5000);
          } else {
            playMusic();
          }
        }
      };
      
      // 播放音乐
      function playMusic() {
        if (!bgMusic) return;
        
        bgMusic.play().then(function() {
          isPlaying = true;
          musicCtrl.innerHTML = ''<span class="text-2xl">🩸</span>'';
          console.log(''音乐已开启'');
          musicRetryCount = 0;
        }).catch(function(error) {
          console.error(''音乐播放失败:'', error);
          musicRetryCount++;
          
          if (musicRetryCount <= maxRetries) {
            console.log(''尝试重新播放 ('' + musicRetryCount + ''/'' + maxRetries + '')'');
            setTimeout(playMusic, 1000);
          } else {
            isPlaying = false;
            musicCtrl.innerHTML = ''<span class="text-2xl">🔇</span>'';
            var errorMsg = ''音乐播放失败，可能原因：\n1. 网络连接问题\n2. CDN访问受限\n3. 浏览器阻止自动播放\n\n建议：\n- 检查网络连接\n- 尝试刷新页面\n- 手动点击音乐按钮'';
            alert(errorMsg);
          }
        });
      }
      
      // 音乐开关
      musicCtrl.onclick = function() {
        if (!bgMusic) {
          alert(''音频组件未加载，请刷新页面重试'');
          return;
        }
        
        if (isPlaying) {
          bgMusic.pause();
          isPlaying = false;
          musicCtrl.innerHTML = ''<span class="text-2xl">🔇</span>'';
          console.log(''音乐已关闭'');
        } else {
          musicRetryCount = 0;
          playMusic();
        }
      };
      
      // 自动保存
      window.autoSave = function() {
        function getValue(id) {
          var el = document.getElementById(id);
          return el ? el.value : '''';
        }
        function getCheckboxValue(id) {
          var el = document.getElementById(id);
          return el ? el.checked : false;
        }
        function getSelectedValue(className) {
          var els = document.querySelectorAll(''.'' + className + ''.selected'');
          var values = [];
          els.forEach(function(el) {
            var text = el.getAttribute(''data-text'') || el.textContent;
            values.push(text);
          });
          return values.join('', '');
        }
        
        var characterData = {
          country: getSelectedValue(''country-btn''),
          regionType: getSelectedValue(''region-type-btn''),
          customRegion: getValue(''customRegion''),
          job: getSelectedValue(''job-btn''),
          customJob: getValue(''customJob''),
          disasterType: getValue(''charDisasterType''),
          timeline: getSelectedValue(''timeline-btn''),
          name: getValue(''charName''),
          gender: getValue(''charGender''),
          age: getValue(''charAge''),
          personality: getValue(''charPersonality''),
          appearance: getValue(''charAppearance''),
          openingStory: getValue(''charOpeningStory''),
          normalStatus: getCheckboxValue(''normalStatus''),
          strictStatus: getCheckboxValue(''strictStatus'')
        };
        
        saveData(''characterData'', JSON.stringify(characterData));
        
        var overlay = document.getElementById(''modalOverlay'');
        var modalTitle = document.getElementById(''modalTitle'');
        if (overlay && modalTitle && overlay.classList.contains(''active'')) {
          if (modalTitle.textContent.indexOf(''角色档案'') !== -1) {
            window.loadCharacterData();
          }
        }
      };
      
      // 选择国家
      window.selectCountry = function(btn) {
        var allBtns = document.querySelectorAll(''.country-btn'');
        allBtns.forEach(function(b) {
          b.classList.remove(''selected'');
        });
        btn.classList.add(''selected'');
        window.autoSave();
      };
      
      // 选择地区类型
      window.selectRegionType = function(btn) {
        // 清空自定义地区输入
        var customRegion = document.getElementById(''customRegion'');
        if (customRegion) {
          customRegion.value = '''';
        }
        
        var allBtns = document.querySelectorAll(''.region-type-btn'');
        allBtns.forEach(function(b) {
          b.classList.remove(''selected'');
        });
        btn.classList.add(''selected'');
        window.autoSave();
      };
      
      // 选择职业
