      // 清除地区类型选择（当输入自定义地区时）
      window.clearRegionType = function() {
        var customRegion = document.getElementById(''customRegion'');
        if (customRegion && customRegion.value.trim() !== '''') {
          var regionTypeBtns = document.querySelectorAll(''.region-type-btn'');
          regionTypeBtns.forEach(function(btn) {
            btn.classList.remove(''selected'');
          });
        }
      };
      
      // 清除职业选择（当输入自定义职业时）
      window.clearJobSelection = function() {
        var customJob = document.getElementById(''customJob'');
        if (customJob && customJob.value.trim() !== '''') {
          var jobBtns = document.querySelectorAll(''.job-btn'');
          jobBtns.forEach(function(btn) {
            btn.classList.remove(''selected'');
          });
        }
      };
      
      window.loadCustomData = function() {
        try {
          var savedData = loadData(''characterData'');
          if (savedData) {
            var data = JSON.parse(savedData);
            
            // 加载输入框
            var inputs = [''customRegion'', ''customJob'', 
                          ''charDisasterType'', ''charName'', ''charGender'', ''charAge'', ''charPersonality'',
                          ''charAppearance'', ''charOpeningStory''];
            inputs.forEach(function(id) {
              var el = document.getElementById(id);
              if (el && data[id]) {
                el.value = data[id];
              }
            });
            
            // 加载复选框
            [''normalStatus'', ''strictStatus''].forEach(function(id) {
              var el = document.getElementById(id);
              if (el && data[id] !== undefined) {
                el.checked = data[id];
              }
            });
            
            // 加载国家选择
            if (data.country) {
              var countries = data.country.split('', '');
              var countryBtns = document.querySelectorAll(''.country-btn'');
              countryBtns.forEach(function(btn) {
                if (countries.includes(btn.textContent)) {
                  btn.classList.add(''selected'');
                } else {
                  btn.classList.remove(''selected'');
                }
              });
            }
            
            // 加载地区类型选择
            if (data.regionType) {
              var regionTypes = data.regionType.split('', '');
              var regionTypeBtns = document.querySelectorAll(''.region-type-btn'');
              regionTypeBtns.forEach(function(btn) {
                if (regionTypes.includes(btn.textContent)) {
                  btn.classList.add(''selected'');
                } else {
                  btn.classList.remove(''selected'');
                }
              });
            }
            
            // 加载职业选择
            if (data.job) {
              var jobs = data.job.split('', '');
              var jobBtns = document.querySelectorAll(''.job-btn'');
              jobBtns.forEach(function(btn) {
                if (jobs.includes(btn.textContent)) {
                  btn.classList.add(''selected'');
                } else {
                  btn.classList.remove(''selected'');
                }
              });
            }
            
            // 加载时间线选择
            if (data.timeline) {
              var timelineValue = data.timeline.trim();
              var timelineBtns = document.querySelectorAll(''.timeline-btn'');
              timelineBtns.forEach(function(btn) {
                var btnText = btn.getAttribute(''data-text'') || btn.textContent;
                if (btnText === timelineValue) {
                  btn.classList.add(''selected'');
                } else {
                  btn.classList.remove(''selected'');
                }
              });
            }
          }
        } catch (e) {
          console.error(''loadCustomData error:'', e);
        }
      };
      
      window.loadCharacterData = function() {
        try {
          var savedData = loadData(''characterData'');
          var previewContent = document.getElementById(''previewContent'');
          if (!previewContent) return;
          
          if (savedData) {
            var data = JSON.parse(savedData);
            var html = ''<div class="space-y-4">'';
            
            // 末世设定
            html += ''<div class="tech-info-block">'';
            html += ''<div class="tech-info-block-title">🌪️ 末世设定</div>'';
            html += ''<div class="tech-preview-item"><div class="tech-preview-label">末世类型</div><div class="tech-preview-value">'' + (data.disasterType || ''未选择'') + ''</div></div>'';
            html += ''<div class="tech-preview-item"><div class="tech-preview-label">时间线</div><div class="tech-preview-value">'' + (data.timeline || ''未选择'') + ''</div></div>'';
            html += ''</div>'';
            
            // 所在地区
            html += ''<div class="tech-info-block">'';
            html += ''<div class="tech-info-block-title">🌍 所在地区</div>'';
            html += ''<div class="tech-preview-item"><div class="tech-preview-label">国家</div><div class="tech-preview-value">'' + (data.country || ''未选择'') + ''</div></div>'';
            // 地区类型：优先显示自定义地区，否则显示选择的地区类型
            var regionValue = data.customRegion || data.regionType || ''未选择'';
            html += ''<div class="tech-preview-item"><div class="tech-preview-label">地区类型</div><div class="tech-preview-value">'' + regionValue + ''</div></div>'';
            html += ''</div>'';
            
            // 基本信息
            html += ''<div class="tech-info-block">'';
            html += ''<div class="tech-info-block-title">📋 基本信息</div>'';
            html += ''<div class="grid grid-cols-1 md:grid-cols-2 gap-3">'';
            html += ''<div class="tech-preview-item"><div class="tech-preview-label">姓名</div><div class="tech-preview-value">'' + (data.name || ''未填写'') + ''</div></div>'';
            html += ''<div class="tech-preview-item"><div class="tech-preview-label">性别</div><div class="tech-preview-value">'' + (data.gender || ''未填写'') + ''</div></div>'';
            html += ''<div class="tech-preview-item"><div class="tech-preview-label">年龄</div><div class="tech-preview-value">'' + (data.age || ''未填写'') + ''</div></div>'';
            html += ''<div class="tech-preview-item"><div class="tech-preview-label">性格</div><div class="tech-preview-value">'' + (data.personality || ''未填写'') + ''</div></div>'';
            html += ''<div class="tech-preview-item"><div class="tech-preview-label">职业</div><div class="tech-preview-value">'' + (data.job || data.customJob || ''未填写'') + ''</div></div>'';
            html += ''</div>'';
            html += ''<div class="tech-preview-item"><div class="tech-preview-label">外貌</div><div class="tech-preview-value whitespace-pre-wrap">'' + (data.appearance || ''未填写'') + ''</div></div>'';
            html += ''<div class="tech-preview-item"><div class="tech-preview-label">开局剧情</div><div class="tech-preview-value whitespace-pre-wrap">'' + (data.openingStory || ''未填写'') + ''</div></div>'';
            html += ''</div>'';
            
            // 状态栏（仅在勾选时显示）
            if (data.normalStatus || data.strictStatus) {
              html += ''<div class="tech-info-block">'';
              html += ''<div class="tech-info-block-title">📊 状态栏</div>'';
              html += ''<div class="space-y-2">'';
              if (data.normalStatus) {
                html += ''<div class="tech-preview-item"><div class="tech-preview-label">普通状态栏</div><div class="tech-preview-value">已启用</div></div>'';
              }
              if (data.strictStatus) {
                html += ''<div class="tech-preview-item"><div class="tech-preview-label">严格状态栏</div><div class="tech-preview-value">已启用</div></div>'';
              }
              html += ''</div></div>'';
            }
            
            html += ''</div>'';
            
            previewContent.innerHTML = html;
          } else {
            previewContent.innerHTML = ''<p class="text-gray-500 text-center">暂无角色数据，请先在角色创建中创建角色</p>'';
          }
        } catch (e) {
          console.error(''loadCharacterData error:'', e);
        }
      };
      
      window.copyCharacterData = function() {
        try {
          var savedData = loadData(''characterData'');
          if (savedData) {
            var data = JSON.parse(savedData);

            var text = ''【末世设定】\n'';
            text += ''末世类型：'' + (data.disasterType || ''未选择'') + ''\n'';
            text += ''时间线：'' + (data.timeline || ''未选择'') + ''\n'';
            text += ''\n'';
            text += ''【所在地区】\n'';
            text += ''国家：'' + (data.country || ''未选择'') + ''\n'';
            // 地区类型：优先显示自定义地区，否则显示选择的地区类型
            var regionValue = data.customRegion || data.regionType || ''未选择'';
            text += ''地区类型：'' + regionValue + ''\n'';
            text += ''\n'';
            text += ''【基本信息】\n'';
            text += ''姓名：'' + (data.name || ''未填写'') + ''\n'';
            text += ''性别：'' + (data.gender || ''未填写'') + ''\n'';
            text += ''年龄：'' + (data.age || ''未填写'') + ''\n'';
            text += ''性格：'' + (data.personality || ''未填写'') + ''\n'';
            text += ''职业：'' + (data.job || data.customJob || ''未填写'') + ''\n'';
            text += ''外貌：'' + (data.appearance || ''未填写'') + ''\n'';
            text += ''开局剧情：'' + (data.openingStory || ''未填写'') + ''\n'';
            if (data.normalStatus || data.strictStatus) {
              text += ''\n'';
              text += ''【状态栏】\n'';
              if (data.normalStatus) text += ''普通状态栏：已启用\n'';
              if (data.strictStatus) text += ''严格状态栏：已启用\n'';
            }

            // 定义复制成功的回调
            var handleSuccess = function() {
              window.showToast(''复制成功！'', ''📋'');
            };

            // 定义复制失败的回调
            var handleFailure = function() {
              // 使用传统方法作为备用
              var textarea = document.createElement(''textarea'');
              textarea.value = text;
              textarea.style.position = ''fixed'';
              textarea.style.opacity = ''0'';
              textarea.style.left = ''-9999px'';
              textarea.style.top = ''-9999px'';
              document.body.appendChild(textarea);
              textarea.select();
              textarea.setSelectionRange(0, 99999);

              try {
                if (document.execCommand(''copy'')) {
                  document.body.removeChild(textarea);
                  window.showToast(''复制成功！'', ''📋'');
                  return;
                }
              } catch (err) {
                console.warn(''execCommand 复制失败:'', err);
              }

              document.body.removeChild(textarea);

              // 如果所有方法都失败
              alert(''自动复制失败，请手动复制以下内容：\n\n'' + text);
              window.showToast(''复制失败，请手动复制'', ''⚠️'');
            };

            // 优先使用现代 Clipboard API
            if (navigator.clipboard && navigator.clipboard.writeText) {
              navigator.clipboard.writeText(text).then(handleSuccess).catch(handleFailure);
            } else {
              // 不支持 Clipboard API，直接使用传统方法
              handleFailure();
            }
          } else {
            window.showToast(''暂无角色数据'', ''⚠️'');
          }
        } catch (e) {
          console.error(''copyCharacterData error:'', e);
          window.showToast(''复制失败'', ''❌'');
        }
      };
      
