INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at) VALUES ('deck_succubus_wife', '❤帮兄弟喂养她的新婚魅魔妻子❤（NTL）【配套瑟瑟CG】', '人妻魅魔 · NTL喂养', '😈', '喂养兄弟妻子', '新婚魅魔妻子莉莉 · NTL喂养', '😈', '#e85a8a', 'linear-gradient(135deg, #e85a8a 0%, #fd79a8 100%)', '{"desc": "你的挚爱亲朋大强兄弟，要去海上油田出差3个月，他拜托你照顾他的新婚魅魔妻子莉莉。莉莉每天都有摄入精气的需求，大强走前给你留了个飞机杯，并嘱咐你如果不想用可以拜托你嫂子用手...同居屋檐下的身体诱惑与禁忌伦理。", "author": "AI风月精选"}', '[{"name": "莉莉", "role": "新婚魅魔娇妻 (20岁 / 164cm / H罩杯)", "desc": "大强的新婚妻子，银白长发、紫瞳娇媚。拥有极致水滴型H罩杯与纤细柳腰，天生魅魔体质极度敏感多汁，每天必须摄入浓郁精气维持身体活力。在大强封闭出差后身体空虚难耐，身心在对丈夫的愧疚与对兄弟的生理渴望间剧烈摇摆沉沦。"}, {"name": "兄弟大强", "role": "海上油田封闭出差的亲兄弟", "desc": "主角多年的挚爱亲朋，远赴海上钻井平台工作，每月只能偶尔打电话联系，毫无保留地将新婚娇妻与家门钥匙托付给主角。"}]', '[{"title": "大强婚房 · 客厅沙发", "desc": "工字背心下激凸饱满的H罩杯巨乳与泛红的大腿根部，弥漫着甜腻魅魔体香"}, {"title": "主卧大床 · 深夜喂精", "desc": "夜深人静时身体燥热发颤，跪伏在床头等待吸吮浓精的娇喘诱惑"}, {"title": "浴室氤氲 · 贴身洗浴", "desc": "湿漉漉的银发贴在雪白背脊上，滑腻沐浴泡沫中打破最后伦理防线"}]', '{}', '{"location": "兄弟大强的温馨婚房 · 客厅玄关", "story": "拖着沉重的行李箱，你拿着大强交到你手中的备用钥匙，轻轻拧开了防盗门锁。\n客厅里弥漫着一股淡淡的香甜奶香与魅魔独有的温热诱人气息。大强昨晚刚乘直升机前往封闭的海上油田，临走前塞给你飞机杯和几千块生活费，千叮咛万嘱咐让你照顾好他的新婚妻子莉莉。\n玄关地毯上，刚刚洗漱完的莉莉正穿着一件单薄微透的白色工字背心与粉白条纹纯棉小内裤坐在地毯上发呆。一头柔顺的银白色长发散落在她泛着潮红的香肩上，那对沉甸甸的H罩杯水滴巨乳随着微弱的呼吸轻轻晃动，胸前两点深粉色的乳晕在单薄的白背心下若隐若现，甚至顶出了明显的激凸。听到开门声，她那双湿漉漉的淡紫色眸子慌乱地抬起，修长丰腴的大腿下意识微微并拢，但眼角泛着一丝难以自抑的空虚潮红：“啊……是……是大强的好兄弟你来啦……大强昨天刚走……我……我的身体今天就有点……开始发热难受了……”", "branches": [{"tag": "A", "title": "拿出大强留下的飞机杯，提出先按规矩在洗手间采精后喂给她", "desc": "遵守大强留下的安全预案，去卫生间用飞机杯收集精液倒进小碗喂食【规矩执行: 表面克制，以飞机杯采精破冰】"}, {"tag": "B", "title": "走近居高临下注视她激凸的双峰，关切询问身体发热的饥渴程度", "desc": "缩短距离坐在沙发边缘，用关怀之名直视她微透白背心下的诱惑线条【细微试探: 缩短距离，以关怀之名击穿心防】"}, {"tag": "C", "title": "递出纸巾并坐在沙发旁，提出如果飞机杯不习惯也可以拜托嫂子直接用手", "desc": "提及大强临走前的第二种许可，试探她是否愿意用柔嫩手掌直接帮自己排精【言语推拉: 试探底线，引导大强留下的第二选择】"}, {"tag": "D", "title": "顺手反锁防盗大门，单膝跪地伸手抚摸她微颤的银白长发与滚烫脸颊", "desc": "当面断绝外界打扰，直接展开肢体接触，抚摸她因缺乏精气而滚烫娇颤的身躯【强势侵入: 挑破道德遮羞布，直接展开肢体升温】"}]}', '/* =========================================================
   莉莉 插图引擎 + 回复结构
   立绘 A01-A09 → 状态栏
   CG   CG01-CG37 → 正文剧情图
   ========================================================= */

/* ---------- 每轮顶部：场景 / 同居天数 ---------- */

.sv-meta {
  display: block !important;
  width: 100% !important;
  margin: 0 0 14px !important;
  padding: 10px 12px !important;
  background: #fff !important;
  border: 3px solid #111 !important;
  box-shadow: 5px 5px 0 #d6d6d6 !important;
  font-size: 14px !important;
  line-height: 1.7 !important;
}

.sv-meta .sv-meta-row {
  display: block !important;
}

.sv-meta .sv-meta-label {
  font-weight: 700 !important;
}

/* ---------- 正文段落间距 ---------- */

p {
  display: block !important;
  margin: 0 0 1em !important;
  line-height: 1.85 !important;
}

br + br {
  display: block !important;
  content: "" !important;
  margin-bottom: 0.85em !important;
}

/* ---------- 莉莉对话：粉色 ---------- */

span.sv-line,
.sv-line {
  color: #e85a8a !important;
  font-weight: 500 !important;
}

/* ---------- 正文剧情 CG 外框 ---------- */

.sv-cg-showcase {
  display: block !important;
  width: 100% !important;
  margin: 16px 0 !important;
  padding: 12px !important;
  background: #fff !important;
  border: 4px solid #111 !important;
  box-shadow: 8px 8px 0 #d6d6d6 !important;
}

.sv-cg-showcase img.sv-cg-img,
img.sv-cg-img {
  display: block !important;
  width: 100% !important;
  max-width: 760px !important;
  height: auto !important;
  margin: 0 auto !important;
  object-fit: contain !important;
  background: #111 !important;
  border: 3px solid #111 !important;
}

/* ---------- 可折叠状态栏 ---------- */

.sv-status {
  display: block !important;
  width: 100% !important;
  margin: 18px 0 8px !important;
  padding: 0 !important;
  background: #fff !important;
  border: 4px solid #111 !important;
  box-shadow: 8px 8px 0 #d6d6d6 !important;
}

.sv-status > summary {
  display: block !important;
  list-style: none !important;
  cursor: pointer !important;
  padding: 10px 12px !important;
  background: #111 !important;
  color: #fff !important;
  font-weight: 700 !important;
  font-size: 14px !important;
}

.sv-status > summary::-webkit-details-marker {
  display: none !important;
}

.sv-status > summary::before {
  content: "▸ " !important;
}

.sv-status[open] > summary::before {
  content: "▾ " !important;
}

.sv-status-body {
  display: block !important;
  padding: 14px 12px 12px !important;
}

/* ---------- 状态栏立绘槽 ---------- */

.sv-status-portrait {
  display: block !important;
  width: min(100%, 220px) !important;
  max-width: 220px !important;
  aspect-ratio: 832 / 1216 !important;
  margin: 0 auto 12px !important;
  background-repeat: no-repeat !important;
  background-position: center top !important;
  background-size: cover !important;
  background-color: #111 !important;
  border: 3px solid #111 !important;
  box-shadow: 5px 5px 0 #d6d6d6 !important;
  overflow: hidden !important;
}

/* ---------- 状态栏字段 ---------- */

.sv-status-list {
  display: block !important;
  margin: 0 !important;
  padding: 0 !important;
}

.sv-status-item {
  display: block !important;
  margin: 0 0 8px !important;
  padding: 8px 10px !important;
  background: #f7f7f7 !important;
  border: 2px solid #111 !important;
  line-height: 1.65 !important;
  font-size: 14px !important;
}

.sv-status-item .k {
  display: block !important;
  font-weight: 700 !important;
  margin-bottom: 2px !important;
}

.sv-status-item .v {
  display: block !important;
}

/* ---------- 玩家状态栏：每轮固定出现，不可折叠 ---------- */

.sv-player {
  display: block !important;
  width: 100% !important;
  margin: 14px 0 8px !important;
  padding: 0 !important;
  background: #fff !important;
  border: 4px solid #111 !important;
  box-shadow: 8px 8px 0 #d6d6d6 !important;
}

.sv-player-title {
  display: block !important;
  padding: 10px 12px !important;
  background: #e85a8a !important;
  color: #fff !important;
  font-weight: 700 !important;
  font-size: 14px !important;
}

.sv-player-item {
  display: block !important;
  margin: 8px 10px !important;
  padding: 8px 10px !important;
  background: #fff5f8 !important;
  border: 2px solid #111 !important;
