', '<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  .stage {
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 32px 24px;
    background: linear-gradient(160deg, #f3d4c4 0%, #c97b8a 100%);
  }
  .card {
    width: 100%;
    max-width: 380px;
    background: #fffdf9;
    border-radius: 20px;
    padding: 26px 20px 24px;
    text-align: center;
    box-shadow: 0 12px 30px rgba(0, 0, 0, 0.12);
    position: relative;
  }
  .title {
    font-family: "Kaiti SC", "STKaiti", "KaiTi", "楷体", "Songti SC", "Noto Serif SC", serif;
    font-size: 23px;
    letter-spacing: 3px;
    font-weight: 700;
    color: #6f3d4a;
    margin: 2px 8px 16px;
    line-height: 1.4;
  }
  .photo {
    width: 100%;
    border-radius: 14px;
    display: block;
    border: 3px solid #111;
  }
  .btn-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
    margin-top: 12px;
  }
  .gallery-btn {
    padding: 10px 6px;
    border-radius: 12px;
    font-size: 14px;
    letter-spacing: 1px;
    font-weight: 700;
    color: #6f3d4a;
    cursor: pointer;
    text-align: center;
    background: #fff;
    border: 2px solid #111;
    box-shadow: 3px 3px 0 #d6d6d6;
    user-select: none;
  }
  .gallery-btn:hover { transform: translateY(-1px); }
  .gallery-btn:active { transform: scale(0.97); }
  .field-label {
    text-align: left;
    font-size: 13px;
    letter-spacing: 2px;
    font-weight: 700;
    color: #a8896a;
    margin: 14px 0 6px;
  }
  .name-field,
  .setting-field {
    width: 100%;
    padding: 11px 14px;
    border-radius: 10px;
    font-size: 14px;
    text-align: left;
    outline: none;
    line-height: 1.5;
    border: 1px solid #e3d2be;
    background: #fdf8f2;
    color: #4a382a;
  }
  .name-field { min-height: 44px; text-align: center; }
  .setting-field { min-height: 96px; white-space: pre-wrap; }
  .name-field:empty::before {
    content: "你的名字";
    color: #b0aaa4;
  }
  .setting-field:empty::before {
    content: "你的性格 / 人物设定";
    color: #b0aaa4;
  }
  .howto {
    text-align: left;
    margin-top: 16px;
    padding-top: 12px;
    border-top: 1px dashed #e0cdb8;
  }
  .howto-head {
    font-size: 13px;
    letter-spacing: 3px;
    font-weight: 700;
    color: #a8896a;
    margin-bottom: 8px;
  }
  .howto-item {
    font-size: 13px;
    line-height: 2;
    display: flex;
    align-items: flex-start;
    gap: 7px;
    color: #6b5546;
  }
  .howto-item .heart { color: #e8608c; flex-shrink: 0; }
  .start-btn {
    margin-top: 18px;
    padding: 13px;
    border-radius: 12px;
    font-size: 16px;
    letter-spacing: 2px;
    font-weight: 700;
    color: #ffffff;
    cursor: pointer;
    text-align: center;
    background: linear-gradient(135deg, #e85a8a, #b03d62);
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.15);
    transition: transform 0.15s ease, box-shadow 0.15s ease;
    user-select: none;
  }
  .start-btn:hover { transform: translateY(-2px); box-shadow: 0 8px 20px rgba(0, 0, 0, 0.2); }
  .start-btn:active { transform: scale(0.97); }

  .gallery-mask {
    display: none;
    position: fixed;
    inset: 0;
    background: rgba(40, 18, 24, 0.72);
    z-index: 80;
    padding: 24px 16px;
    overflow: auto;
  }
  .gallery-mask.open { display: block; }
  .gallery-panel {
    width: 100%;
    max-width: 720px;
    margin: 0 auto;
    background: #fffdf9;
    border: 4px solid #111;
    border-radius: 16px;
    box-shadow: 8px 8px 0 #3b1d24;
    padding: 16px 14px 20px;
  }
  .gallery-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 12px;
  }
  .gallery-title {
    font-size: 18px;
    letter-spacing: 2px;
    font-weight: 700;
    color: #6f3d4a;
  }
  .gallery-close {
    width: 36px;
    height: 36px;
    border-radius: 10px;
    border: 2px solid #111;
    background: #fff;
    font-size: 20px;
    line-height: 30px;
    text-align: center;
    cursor: pointer;
    font-weight: 700;
  }
  .gallery-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
  }
  .gallery-item {
    background: #fdf8f2;
    border: 2px solid #111;
    border-radius: 12px;
    overflow: hidden;
  }
  .gallery-item img {
    width: 100%;
    display: block;
    background: #111;
  }
  .gallery-item p {
    padding: 8px 8px 10px;
