  background: #fff !important;
  border: 4px solid #111 !important;
  box-shadow: 8px 8px 0 #d6d6d6 !important;
}

.sv-cg-showcase img.sv-cg-img,
img.sv-cg-img {
  display: block !important;
  width: 100% !important;
  max-width: 760px !important;
  height: auto !important;
  margin: 0 auto !important;
  object-fit: contain !important;
  background: #111 !important;
  border: 3px solid #111 !important;
}

/* ---------- 可折叠状态栏 ---------- */

.sv-status {
  display: block !important;
  width: 100% !important;
  margin: 18px 0 8px !important;
  padding: 0 !important;
  background: #fff !important;
  border: 4px solid #111 !important;
  box-shadow: 8px 8px 0 #d6d6d6 !important;
}

.sv-status > summary {
  display: block !important;
  list-style: none !important;
  cursor: pointer !important;
  padding: 10px 12px !important;
  background: #111 !important;
  color: #fff !important;
  font-weight: 700 !important;
  font-size: 14px !important;
}

.sv-status > summary::-webkit-details-marker {
  display: none !important;
}

.sv-status > summary::before {
  content: "▸ " !important;
}

.sv-status[open] > summary::before {
  content: "▾ " !important;
}

.sv-status-body {
  display: block !important;
  padding: 14px 12px 12px !important;
}

/* ---------- 状态栏立绘槽 ---------- */

.sv-status-portrait {
  display: block !important;
  width: min(100%, 220px) !important;
  max-width: 220px !important;
  aspect-ratio: 832 / 1216 !important;
  margin: 0 auto 12px !important;
  background-repeat: no-repeat !important;
  background-position: center top !important;
  background-size: cover !important;
  background-color: #111 !important;
  border: 3px solid #111 !important;
  box-shadow: 5px 5px 0 #d6d6d6 !important;
  overflow: hidden !important;
}

/* ---------- 状态栏字段 ---------- */

.sv-status-list {
  display: block !important;
  margin: 0 !important;
  padding: 0 !important;
}

.sv-status-item {
  display: block !important;
  margin: 0 0 8px !important;
  padding: 8px 10px !important;
  background: #f7f7f7 !important;
  border: 2px solid #111 !important;
  line-height: 1.65 !important;
  font-size: 14px !important;
}

.sv-status-item .k {
  display: block !important;
  font-weight: 700 !important;
  margin-bottom: 2px !important;
}

.sv-status-item .v {
  display: block !important;
}

/* ---------- 玩家状态栏：每轮固定出现，不可折叠 ---------- */

.sv-player {
  display: block !important;
  width: 100% !important;
  margin: 14px 0 8px !important;
  padding: 0 !important;
  background: #fff !important;
  border: 4px solid #111 !important;
  box-shadow: 8px 8px 0 #d6d6d6 !important;
}

.sv-player-title {
  display: block !important;
  padding: 10px 12px !important;
  background: #e85a8a !important;
  color: #fff !important;
  font-weight: 700 !important;
  font-size: 14px !important;
}

.sv-player-item {
  display: block !important;
  margin: 8px 10px !important;
  padding: 8px 10px !important;
  background: #fff5f8 !important;
  border: 2px solid #111 !important;
  line-height: 1.65 !important;
  font-size: 14px !important;
}

.sv-player-item .k {
  font-weight: 700 !important;
}

.sv-player-item .v {
  display: inline !important;
  white-space: pre-wrap !important;
}

