.gen-btn{
  width:100%;margin-top:8px;
  font-family:inherit;font-size:16px;font-weight:700;letter-spacing:3px;
  color:#fff;
  background:linear-gradient(135deg,#e6a4b4,#d16081);
  border:none;border-radius:var(--radius-sm);
  padding:16px;
  cursor:pointer;
  box-shadow:0 8px 22px rgba(209,96,129,0.35);
  transition:all 0.25s ease;
  position:relative;
  overflow:hidden;
}
.gen-btn:active{transform:scale(0.98);}
.gen-btn::after{
  content:"";position:absolute;top:0;left:-60%;width:40%;height:100%;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,0.45),transparent);
  transform:skewX(-20deg);
  animation:shine 3s infinite;
}
@keyframes shine{
  0%{left:-60%;}
  55%{left:130%;}
  100%{left:130%;}
}
.summary{
  background:linear-gradient(160deg,rgba(255,255,255,0.96),rgba(255,244,249,0.92));
