    border-radius: 4px;
    border-left: 2px solid rgba(255, 126, 179, 0.3);
}

/* ===== 其他辅助 ===== */
.w .t {
    display: block;
    font-weight: bold;
    font-size: 14px;
    color: #d81b60;
    margin: 12px 10px 4px 10px;
    padding-left: 8px;
