}

/* ===== 可选行动推荐 ===== */
.w .action-list {
    margin: 8px 10px 4px 10px;
    padding: 6px 10px;
    background: rgba(255, 255, 255, 0.6);
    border-radius: 6px;
    border-left: 3px solid #ff758c;
    font-size: 13px;
    color: #4a2c40;
}
.w .action-list .act {
    display: block;
    padding: 2px 0;
    color: #6a4a5b;
}

/* ===== 移动端适配 ===== */
@media (max-width: 480px) {
    .w {
        padding: 4px;
        border-radius: 8px;
    }
    .w .a summary,
    .w .b summary,
    .w .star-memory summary {
        padding: 8px 10px;
        font-size: 14px;
    }
    .w .r {
        margin: 4px 6px;
