    }
    .w .m {
        margin: 4px 6px;
    }
    .w .mi {
        font-size: 12px;
        padding: 4px 8px;
    }
    /* 记忆区表格手机优化 */
    .w .star-memory table {
        font-size: 12px;
        min-width: 280px;
    }
    .w .star-memory table th,
    .w .star-memory table td {
        padding: 4px 2px;
        font-size: 12px;
