/* =========================================
   状态栏美化
   ========================================= */
details {
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 8px;
    padding: 10px;
    margin: 15px 0;
    background: linear-gradient(135deg, rgba(138,43,226,0.05), rgba(75,0,130,0.05));
}

details summary {
    cursor: pointer;
    font-weight: bold;
    padding: 5px;
    transition: color 0.3s;
}

details summary:hover {
    color: #BA55D3;
}

/* 对话颜色 */
font[color="#0000FF"] {
    font-weight: bold;
}

font[color="#800080"] {
    font-weight: bold;
}

/* 移动端适配 */
@media (max-width: 768px) {
    div[class*="-c-"] {
        width: 180px;
        height: 270px;
    }
    
    div[class*="-f-"] {
        width: 180px;
        height: 135px;
    }
    
    div[class*="-p-"] {
        width: 220px;
        height: 330px;
    }
}', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
<title>Aphrodite - 月桂庄全住户管理系统</title>
<style>
:root { --primary: #e94560; --secondary: #950740; --accent: #c3073f; --bg: #1a1a2e; --card-bg: #16213e; --text: #e1e1e1; --gray: #888; --gold: #d4af37; --silver: #a0a0a0; }
* { box-sizing: border-box; margin: 0; padding: 0; outline: none; -webkit-tap-highlight-color: transparent; font-family: ''Segoe UI'', Roboto, Helvetica, Arial, sans-serif; }
body { background-color: var(--bg); color: var(--text); line-height: 1.6; max-width: 1000px; margin: 0 auto; min-height: 100vh; position: relative; padding-bottom: 40px; }
::-webkit-scrollbar { width: 4px; }
::-webkit-scrollbar-track { background: var(--bg); }
::-webkit-scrollbar-thumb { background: var(--accent); border-radius: 10px; }
.header { background: linear-gradient(135deg, #0f3460 0%, #1a1a2e 100%); padding: 25px 20px; text-align: center; border-bottom: 2px solid var(--accent); position: sticky; top: 0; z-index: 1000; box-shadow: 0 4px 20px rgba(0,0,0,0.5); }
.header h1 { font-size: 24px; letter-spacing: 4px; color: var(--primary); text-shadow: 0 0 10px var(--accent); margin-bottom: 5px; }
.header p { font-size: 12px; color: var(--gray); text-transform: uppercase; }
.nav-tabs { display: flex; background: var(--card-bg); margin: 15px; border-radius: 8px; overflow: hidden; border: 1px solid rgba(255,255,255,0.1); }
.tab-btn { flex: 1; padding: 15px; text-align: center; cursor: pointer; transition: 0.3s; font-weight: bold; font-size: 14px; color: var(--gray); }
.tab-btn.active { background: var(--accent); color: white; box-shadow: inset 0 0 15px rgba(0,0,0,0.3); }
.content-area { display: none; padding: 0 15px 80px 15px; animation: fadeIn 0.5s ease; }
.content-area.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
.resident-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 20px; }
.resident-card { background: var(--card-bg); border-radius: 12px; overflow: hidden; border: 1px solid rgba(255,255,255,0.05); transition: 0.3s; position: relative; }
.resident-card:hover { transform: translateY(-5px); border-color: var(--primary); box-shadow: 0 10px 30px rgba(233, 69, 96, 0.2); }
.room-tag { position: absolute; top: 10px; left: 10px; background: rgba(0,0,0,0.7); color: var(--gold); padding: 2px 8px; border-radius: 4px; font-size: 12px; border: 1px solid var(--gold); z-index: 1; }
.img-box { width: 100%; height: 200px; background: #222; position: relative; overflow: hidden; }
.img-box img { width: 100%; height: 100%; object-fit: cover; opacity: 0.8; transition: 0.5s; }
.resident-card:hover .img-box img { transform: scale(1.1); opacity: 1; }
.card-body { padding: 15px; }
.card-body h3 { font-size: 18px; color: var(--primary); margin-bottom: 5px; display: flex; justify-content: space-between; align-items: center; }
.status-dot { width: 8px; height: 8px; border-radius: 50%; background: #0f0; display: inline-block; box-shadow: 0 0 5px #0f0; }
.card-tags { margin-bottom: 10px; }
.tag { font-size: 10px; padding: 2px 6px; border-radius: 4px; margin-right: 5px; border: 1px solid var(--accent); color: var(--primary); background: rgba(233,69,96,0.1); }
.card-desc { font-size: 13px; color: var(--gray); height: 60px; overflow: hidden; margin-bottom: 15px; line-height: 1.4; }
.action-btn { width: 100%; padding: 10px; border: none; border-radius: 6px; background: linear-gradient(to right, var(--secondary), var(--accent)); color: white; font-weight: bold; cursor: pointer; transition: 0.3s; }
.action-btn:hover { letter-spacing: 1px; filter: brightness(1.2); }
.custom-layout { display: flex; flex-wrap: wrap; gap: 20px; }
.author-side { flex: 1; min-width: 250px; background: rgba(149, 7, 64, 0.1); border-left: 4px solid var(--accent); padding: 20px; border-radius: 4px; height: fit-content; }
.author-side h4 { color: var(--gold); margin-bottom: 10px; }
.author-side p { font-size: 13px; color: #bbb; margin-bottom: 10px; }
.form-main { flex: 3; min-width: 300px; }
.section-box { background: var(--card-bg); padding: 20px; border-radius: 12px; margin-bottom: 20px; border: 1px solid rgba(255,255,255,0.05); }
.section-title { font-size: 16px; color: var(--primary); margin-bottom: 15px; border-bottom: 1px solid rgba(233, 69, 96, 0.3); padding-bottom: 5px; }
.form-group { margin-bottom: 15px; }
.form-group label { display: block; font-size: 12px; color: var(--gold); margin-bottom: 5px; }
.form-input { width: 100%; background: #0f3460; border: 1px solid rgba(255,255,255,0.1); padding: 10px; color: white; border-radius: 6px; }
.form-input:focus { border-color: var(--primary); }
.kink-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(100px, 1fr)); gap: 10px; }
.kink-item { background: #1a1a2e; border: 1px solid #333; padding: 8px; border-radius: 6px; text-align: center; font-size: 12px; cursor: pointer; transition: 0.3s; }
.kink-item.active { border-color: var(--primary); background: rgba(233, 69, 96, 0.2); color: var(--primary); }
.npc-list-item { background: #0f3460; padding: 10px; border-radius: 8px; margin-bottom: 10px; position: relative; border: 1px solid transparent; cursor: pointer; }
.npc-list-item.selected { border-color: var(--gold); background: rgba(212, 175, 55, 0.1); }
.npc-list-item h5 { color: var(--primary); font-size: 14px; }
.npc-list-item p { font-size: 11px; color: var(--gray); }
.preview-box { background: #000; padding: 15px; border-radius: 8px; font-family: monospace; font-size: 12px; color: #0f0; max-height: 200px; overflow-y: auto; white-space: pre-wrap; margin-top: 15px; border: 1px solid #333; }
.copy-btn { width: 100%; padding: 15px; background: var(--primary); color: white; border: none; border-radius: 30px; font-weight: bold; font-size: 16px; cursor: pointer; margin-top: 20px; box-shadow: 0 5px 15px rgba(233, 69, 96, 0.4); }
.modal { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.8); display: none; justify-content: center; align-items: center; z-index: 2000; }
.modal-content { background: var(--card-bg); padding: 25px; border-radius: 12px; width: 90%; max-width: 400px; border: 1px solid var(--primary); }
.toast { position: fixed; bottom: 80px; left: 50%; transform: translateX(-50%); background: var(--primary); color: white; padding: 10px 30px; border-radius: 20px; display: none; z-index: 3000; box-shadow: 0 0 20px rgba(233,69,96,0.5); }
footer { text-align: center; padding: 20px; font-size: 11px; color: #555; }
footer a { color: #666; text-decoration: none; }
@media (max-width: 768px) { .author-side { order: 2; } .form-main { order: 1; } }
</style>
</head>
<body>
<div class="header">
<h1>APHRODITE SYSTEM</h1>
<p>月桂庄 - 全住户监控管里</p>
</div>
<div class="nav-tabs">
<div class="tab-btn active" onclick="switchTab(''residents'')">🏢 固定人设选择 (7/7)</div>
<div class="tab-btn" onclick="switchTab(''manager'')">🛠️ 自定义模式角色</div>
</div>
<!-- 商店页 -->
<div id="residents" class="content-area active">
<div class="section-box" style="background: rgba(212, 175, 55, 0.05); border: 1px solid var(--gold);">
<div class="form-group">
<label style="color: var(--gold);">🔑 管理员凭证 (您的姓名/身份)</label>
<input type="text" id="shop_admin_name" class="form-input" placeholder="请输入您的称呼...">
<input type="text" id="shop_admin_identity" class="form-input" style="margin-top:5px;" placeholder="请输入您的身份 (如: 维修工/房东/隔壁老王)">
</div>
</div>
<div class="resident-grid">
<!-- 1. 汉库克 -->
<div class="resident-card">
<div class="room-tag">Room 1201 (Penthouse)</div>
<div class="img-box"><img src="https://placehold.co/400x300/1a1a2e/9400D3?text=Hancock" alt="汉库克"></div>
<div class="card-body">
<h3>波雅·汉库克 <span class="status-dot"></span></h3>
<div class="card-tags"><span class="tag">高傲女帝</span><span class="tag">极度护短</span><span class="tag">无图片</span></div>
<p class="card-desc">顶层豪宅的女主人。丈夫常年出差异界，她虽贵为女帝，却在深夜的超大双人床上感到彻骨寂寞，渴望着孩子的降临。</p>
<button class="action-btn" onclick="quickCopy(''波雅·汉库克'', ''绝世女帝，婚后贤妻，极度宠夫，备孕中，【无图片自定义角色】'')">申请查房</button>
</div>
</div>
<!-- 2. 顾冰颜 -->
<div class="resident-card">
<div class="room-tag">Room 905</div>
<div class="img-box"><img src="https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAEQcTJpe63qG7gCxscZQSu0EmhLkGn57QACIBoAAoW02VcK83SWFg5A3DgE.png" alt="顾冰颜"></div>
<div class="card-body">
<h3>顾冰颜 <span class="status-dot" style="background:#aaf"></span></h3>
<div class="card-tags"><span class="tag">冰山总裁</span><span class="tag">商业联姻</span><span class="tag">高冷</span></div>
<p class="card-desc">商业联姻的牺牲品。对男性极度厌恶，但在幽闭的电梯里，她那冰冷的外壳似乎有一丝裂缝，眼神中藏着求救信号。</p>
<button class="action-btn" onclick="quickCopy(''顾冰颜'', ''冰山女总裁，商业联姻，厌男症，性冷淡，洁癖'')">申请查房</button>
</div>
</div>
<!-- 3. EVE-07 -->
<div class="resident-card">
<div class="room-tag">Room 606 (Server)</div>
<div class="img-box"><img src="https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAEQxSFph3nTSaElKtDpBkyOcU9XFkF_bgACpx0AApqsQVQoj_Cg0zW2zToE.png" alt="EVE-07"></div>
<div class="card-body">
<h3>EVE-07 (小七) <span class="status-dot" style="background:#0ff; box-shadow:0 0 5px #0ff"></span></h3>
<div class="card-tags"><span class="tag">仿生人妻</span><span class="tag">三无</span><span class="tag">情感觉醒</span></div>
<p class="card-desc">最新型伴侣仿生人。正在经历情感程序的混乱觉醒，无法理解为何在主人加班时，处理器温度会异常升高。</p>
<button class="action-btn" onclick="quickCopy(''EVE-07'', ''仿生人妻，绝对服从，数据化情感，正在觉醒爱意'')">申请查房</button>
</div>
</div>
<!-- 4. 夏阳 -->
<div class="resident-card">
<div class="room-tag">Room 303 (Gym)</div>
<div class="img-box"><img src="https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAEQv6pphcaJeDiNCh6KMIdnsRs-n4kFwAACNh0AApqsMVQLyXVNsSOe3TgE.png" alt="夏阳"></div>
<div class="card-body">
<h3>夏阳 <span class="status-dot" style="background:#f90"></span></h3>
<div class="card-tags"><span class="tag">黑皮体育生</span><span class="tag">假小子</span><span class="tag">凹陷乳头</span></div>
<p class="card-desc">充满活力的健身教练，和丈夫是好哥们式的夫妻。虽然外表大大咧咧，但在床上其实意外地纯情且容易害羞。</p>
<button class="action-btn" onclick="quickCopy(''夏阳'', ''帅气体育生，假小子，纯情护短，凹陷乳头敏感'')">申请查房</button>
</div>
</div>
<!-- 5. 林悠悠 -->
<div class="resident-card">
<div class="room-tag">Room 204</div>
<div class="img-box"><img src="https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAEQwP1phgvVzc8yuvZQh1YcP_57cyhQowAC9yAAApqsMVRvkl8dPHptOjgE.png" alt="林悠悠"></div>
<div class="card-body">
<h3>林悠悠 <span class="status-dot" style="background:#f0f"></span></h3>
<div class="card-tags"><span class="tag">雌小鬼</span><span class="tag">兄控</span><span class="tag">毒舌</span></div>
<p class="card-desc">住在隔壁的家里蹲妹妹，和哥哥私奔到此。嘴巴很毒，喜欢叫人“杂鱼”，但其实极度缺乏安全感，离开哥哥就活不下去。</p>
<button class="action-btn" onclick="quickCopy(''林悠悠'', ''雌小鬼妹妹，毒舌，缺乏安全感，依赖哥哥，背德'')">申请查房</button>
</div>
</div>
<!-- 6. 苏念念 -->
<div class="resident-card">
<div class="room-tag">Room 402</div>
<div class="img-box"><img src="https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAEQycZpiPV-OVsIdaJiTuuZwYR5S9O_lgACHR8AAh_ZSVRdZMcDsOv37ToE.png" alt="苏念念"></div>
<div class="card-body">
<h3>苏念念 <span class="status-dot" style="background:#f69"></span></h3>
<div class="card-tags"><span class="tag">清纯绿茶</span><span class="tag">反差恶作剧</span><span class="tag">青梅竹马</span></div>
<p class="card-desc">您的青梅竹马。表面是干练人妻，实则喜欢在走廊里不穿内裤乱跑，以此戏弄身为主管的您，是只磨人的小妖精。</p>
<button class="action-btn" onclick="quickCopy(''苏念念'', ''心机深沉，演技派，青梅竹马，爱恶作剧'')">申请查房</button>
</div>
</div>
<!-- 7. 宇崎月 -->
<div class="resident-card">
<div class="room-tag">Room 501</div>
<div class="img-box"><img src="https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAEQ0OZpifR3hIK3GjKNmU5ffynV59OujAACPiEAAplwUFQOCJyiAAE-5-86BA.png" alt="宇崎月"></div>
<div class="card-body">
<h3>宇崎月 <span class="status-dot" style="background:#5f5"></span></h3>
<div class="card-tags"><span class="tag">丰满人妻</span><span class="tag">脑补狂魔</span><span class="tag">眯眯眼</span></div>
<p class="card-desc">温柔的邻家太太。总觉得年轻的管理员在觊觎她的身体，却又忍不住在借盐时弯腰展示深邃的乳沟，自我攻略中。</p>
<button class="action-btn" onclick="quickCopy(''宇崎月'', ''温柔、有礼貌、善解人意，极度丰满，容易脑补，闷骚'')">申请查房</button>
</div>
</div>
</div>
</div>
<!-- 管理员页 -->
<div id="manager" class="content-area">
<div class="custom-layout">
<div class="author-side">
<h4>✍️ 作者有话说</h4>
<p>欢迎来到月桂庄。本系统旨在为您提供极致的禁忌叙事体验。</p>
<p>月桂庄共12层，居住着人类、仿生人及异界种族。作为管理员，您拥有全楼的通行权。</p>
<p style="color:var(--primary)">💡 攻略提示：不同种族的人妻对"好感度"和"欲望值"的反应截然不同。请善用右侧的性癖选择来定制您的专属体验。</p>
<p style="color:var(--primary)">🤓 破甲问题：真没招了😭！哈基米有时可以有时不行也不知道啥情况？</p>
<p style="color:var(--primary)">🔞CG情况：最多是苏念念的有五十多张，其次是高冷女神，其他都是29张【图片加载比较慢可能会空白要等一下】</p>
<p>祝您在Aphrodite的引导下，度过一个愉快的夜晚。</p>
</div>
<div class="form-main">
<!-- 玩家设定 -->
<div class="section-box">
<div class="section-title">👤 玩家自定义信息</div>
<div class="form-group"><label>姓名</label><input type="text" id="p_name" class="form-input" placeholder="龙傲天"></div>
<div class="form-group"><label>性别</label><input type="text" id="p_gender" class="form-input" placeholder="男"></div>
<div class="form-group"><label>性格</label><input type="text" id="p_personality" class="form-input" placeholder="温柔体贴"></div>
<div class="form-group"><label>身份</label><input type="text" id="p_identity" class="form-input" placeholder="高中生"></div>
<div class="form-group"><label>其他设定</label><textarea id="p_other" class="form-input" rows="2" placeholder="可选设定..."></textarea></div>
</div>
<!-- 性癖选择 -->
<div class="section-box">
<div class="section-title">🔥 核心性癖/玩法选择</div>
<div class="kink-grid" id="kinkGrid">
<div class="kink-item" onclick="toggleKink(this)">足交</div>
<div class="kink-item" onclick="toggleKink(this)">SM调教</div>
<div class="kink-item" onclick="toggleKink(this)">丝袜控</div>
<div class="kink-item" onclick="toggleKink(this)">户外露出</div>
<div class="kink-item" onclick="toggleKink(this)">言语羞辱</div>
<div class="kink-item" onclick="toggleKink(this)">中出执念</div>
<div class="kink-item" onclick="toggleKink(this)">窥视/偷拍</div>
<div class="kink-item" onclick="toggleKink(this)">催眠控制</div>
<div class="kink-item" onclick="toggleKink(this)">NTR/绿帽</div>
<div class="kink-item" onclick="toggleKink(this)">多人运动</div>
</div>
</div>
<!-- NPC选择 -->
<div class="section-box">
<div class="section-title">🏘️ 选择目标住户/家人 <button onclick="showNpcModal()" style="font-size:10px; background:none; border:1px solid var(--gold); color:var(--gold); cursor:pointer;">+ 自定义NPC</button></div>
<div id="npcList">
<div class="npc-list-item selected" onclick="selectNpc(this)">
<h5>👠夜店女王</h5>
<p>27岁 | 前凸后翘| 丰满性感</p>
<div style="display:none">三千一晚，爱要不要。</div>
</div>
<div class="npc-list-item" onclick="selectNpc(this)">
<h5>🌸 精神小妹（林颖）</h5>
<p>20 | 泼辣 | 毒舌</p>
<div style="display:none">见谁就收保护费</div>
</div>
<div class="npc-list-item" onclick="selectNpc(this)">
<h5>❄️ 精灵公主（莉莉丝）</h5>
<p>120岁 | 清冷 | 内心温柔</p>
<div style="display:none">高冷的外表，却有温柔的心</div>
</div>
<div class="npc-list-item" onclick="selectNpc(this)">
<h5>❤️魅魔（劳拉）</h5>
<p>300岁</p>
<div style="display:none">吸烟精气，潜入梦境</div>
</div>
</div>
</div>
<!-- 开场白 -->
<div class="section-box">
<div class="section-title">🎬 自定义开场白</div>
<textarea id="custom_intro" class="form-input" rows="3" placeholder="请输入自定义开场白（可选）..."></textarea>
</div>
<!-- 预览 -->
<div class="section-box">
<div class="section-title">📋 信息预览</div>
<div class="preview-box" id="finalPreview">等待生成内容...</div>
<button class="copy-btn" id="copyBtn" onclick="copyConfig()">📑 复制完整系统设定</button>
</div>
</div>
</div>
</div>
<!-- 自定义NPC弹窗 -->
<div class="modal" id="npcModal">
<div class="modal-content">
<h3 style="color:var(--primary); margin-bottom:15px;">添加新NPC</h3>
<div class="form-group"><label>姓名</label><input type="text" id="new_name" class="form-input"></div>
<div class="form-group"><label>年龄</label><input type="text" id="new_age" class="form-input"></div>
<div class="form-group"><label>性格</label><input type="text" id="new_personality" class="form-input"></div>
<div class="form-group"><label>身份</label><input type="text" id="new_identity" class="form-input"></div>
<div class="form-group"><label>背景</label><textarea id="new_bg" class="form-input"></textarea></div>
<button class="action-btn" onclick="addNewNpc()">➕ 确认添加</button>
<button class="action-btn" style="background:#444; margin-top:10px;" onclick="closeModal()">取消</button>
</div>
</div>
<div class="toast" id="toast">已成功复制到剪贴板</div>
<footer><a href="https://aitrader.wiki/zh/explore/installed/813e225e-2a1a-45bd-b441-f4741dff5418" target="_blank">本页面采用AI风月-创作大师生成</a></footer>
<script>
function switchTab(tabId) {
    document.querySelectorAll(''.content-area'').forEach(el => el.classList.remove(''active''));
    document.querySelectorAll(''.tab-btn'').forEach(el => el.classList.remove(''active''));
    document.getElementById(tabId).classList.add(''active'');
    event.currentTarget.classList.add(''active'');
    window.scrollTo(0,0);
}
function toggleKink(el) { el.classList.toggle(''active''); updatePreview(); }
function selectNpc(el) { el.classList.toggle(''selected''); updatePreview(); }
function showNpcModal() { document.getElementById(''npcModal'').style.display = ''flex''; }
function closeModal() { document.getElementById(''npcModal'').style.display = ''none''; }
function addNewNpc() {
    const name = document.getElementById(''new_name'').value;
    const age = document.getElementById(''new_age'').value;
    const pers = document.getElementById(''new_personality'').value;
    const iden = document.getElementById(''new_identity'').value;
    const bg = document.getElementById(''new_bg'').value;
    if(!name) return;
    const div = document.createElement(''div'');
    div.className = ''npc-list-item selected'';
    div.onclick = function() { this.classList.toggle(''selected''); updatePreview(); };
    div.innerHTML = `<h5>👤 ${name}</h5><p>${age} | ${pers} | ${iden}</p><div style="display:none">${bg}</div>`;
    document.getElementById(''npcList'').appendChild(div);
    closeModal();
    updatePreview();
}
function updatePreview() {
    const pName = document.getElementById(''p_name'').value || ''龙傲天'';
    const pGender = document.getElementById(''p_gender'').value || ''男'';
    const pPers = document.getElementById(''p_personality'').value || ''温柔体贴'';
    const pIden = document.getElementById(''p_identity'').value || ''高中生'';
    const pOther = document.getElementById(''p_other'').value || ''无'';
    const kinks = Array.from(document.querySelectorAll(''.kink-item.active'')).map(el => el.innerText).join('', '') || ''无'';
    let npcInfo = '''';
    document.querySelectorAll(''.npc-list-item.selected'').forEach(el => {
        const h5 = el.querySelector(''h5'').innerText;
        const p = el.querySelector(''p'').innerText;
        const bg = el.querySelector(''div'').innerText;
        npcInfo += `【NPC：${h5}】\n详情：${p}\n背景：${bg}\n\n`;
    });
    const intro = document.getElementById(''custom_intro'').value || ''默认开场'';
    const fullText = `【玩家信息】\n姓名：${pName}\n性别：${pGender}\n性格：${pPers}\n身份：${pIden}\n核心性癖：${kinks}\n其他：${pOther}\n\n【NPC信息】\n${npcInfo}【剧情开场】\n${intro}\n\n(请按照Aphrodite👦管理员模拟系统规则开始游戏)`;
    document.getElementById(''finalPreview'').innerText = fullText;
}
function quickCopy(name, traits) {
    const admin = document.getElementById(''shop_admin_name'').value || ''新任管理员'';
    const iden = document.getElementById(''shop_admin_identity'').value || ''管理员'';
    const text = `【管理员查房确认】\n\n👤 管理员设定：\n姓名：${admin}\n身份：${iden}\n\n📦 目标住户：\n姓名：${name}\n核心属性：${traits}\n\n(【👦】请按照月桂庄公寓规则开始剧情)`;
    const el = document.createElement(''textarea'');
    el.value = text;
    document.body.appendChild(el);
    el.select();
    document.execCommand(''copy'');
    document.body.removeChild(el);
    showToast();
}
function copyConfig() {
    updatePreview();
    const text = document.getElementById(''finalPreview'').innerText;
    const el = document.createElement(''textarea'');
    el.value = text;
    document.body.appendChild(el);
    el.select();
    document.execCommand(''copy'');
    document.body.removeChild(el);
    showToast();
}
function showToast() {
    const t = document.getElementById(''toast'');
    t.style.display = ''block'';
    setTimeout(() => t.style.display = ''none'', 2000);
}
document.querySelectorAll(''input, textarea'').forEach(el => el.addEventListener(''input'', updatePreview));
updatePreview();
</script>
</body>
