            color: white;
            padding: 15px 30px;
            border-radius: 30px;
            font-weight: bold;
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
            display: none;
            z-index: 1000;
        }

        /* ===== 自定义下拉组件 ===== */
        .custom-select {
            position: relative;
            width: 100%;
            user-select: none;
            -webkit-tap-highlight-color: transparent;
        }
        .custom-select-trigger {
            display: flex;
            align-items: center;
            justify-content: space-between;
            width: 100%;
            padding: 12px 14px;
            border: 1px solid var(--primary);
            border-radius: 8px;
            background: rgba(255, 255, 255, 0.8);
            color: var(--text);
            font-size: 1rem;
            cursor: pointer;
            transition: all 0.3s;
            min-height: 48px;
            touch-action: manipulation;
        }
        .custom-select-trigger:active {
            background: rgba(232, 180, 184, 0.2);
        }
        .custom-select-trigger .value {
            flex: 1;
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
        }
        .custom-select-trigger .arrow {
            margin-left: 10px;
            font-size: 12px;
            color: var(--accent);
            transition: transform 0.3s;
            flex-shrink: 0;
        }
        .custom-select-trigger .arrow.open {
            transform: rotate(180deg);
        }
        .custom-select-trigger.placeholder {
            color: #999;
        }
        .custom-select-trigger:focus {
            outline: none;
            border-color: var(--accent);
            box-shadow: 0 0 8px rgba(164, 92, 64, 0.2);
        }

        .custom-select-dropdown {
            position: absolute;
            top: calc(100% + 4px);
            left: 0;
            right: 0;
            z-index: 999;
            background: #fff;
            border: 1px solid var(--primary);
            border-radius: 8px;
            box-shadow: 0 8px 25px rgba(0, 0, 0, 0.15);
            max-height: 220px;
            overflow-y: auto;
            display: none;
            -webkit-overflow-scrolling: touch;
        }
        .custom-select-dropdown.open {
            display: block;
            animation: dropdownIn 0.2s ease;
        }
        @keyframes dropdownIn {
            from {
                opacity: 0;
                transform: translateY(-6px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }
        .custom-select-dropdown .option {
            padding: 12px 14px;
            font-size: 0.95rem;
            color: var(--text);
            cursor: pointer;
            transition: background 0.15s;
            border-bottom: 1px solid #f5f0ee;
            min-height: 44px;
            display: flex;
            align-items: center;
            touch-action: manipulation;
            -webkit-tap-highlight-color: transparent;
        }
        .custom-select-dropdown .option:last-child {
            border-bottom: none;
        }
        .custom-select-dropdown .option:active {
            background: var(--secondary);
        }
        .custom-select-dropdown .option:hover {
            background: var(--secondary);
        }
        .custom-select-dropdown .option.selected {
            background: var(--primary);
            color: var(--accent);
            font-weight: bold;
        }
        .custom-select-dropdown .option.custom-option {
            border-top: 1px dashed var(--primary);
            color: var(--accent);
            font-style: italic;
        }

        /* 自定义输入框在select下方 */
        .custom-input-wrapper {
            margin-top: 10px;
            display: none;
        }
        .custom-input-wrapper.show {
            display: block;
        }

        /* 移动端适配 */
        @media (max-width: 600px) {
            .tabs {
                flex-direction: column;
            }
            .tab-btn {
                width: 100%;
                padding: 14px;
                font-size: 0.95rem;
            }
            .btn-group {
                flex-direction: column;
            }
            .action-btn {
                padding: 16px;
                font-size: 1rem;
            }
            .content-area {
                padding: 16px;
            }
            .card {
                padding: 16px;
            }
            .header h1 {
                font-size: 1.6rem;
            }
            .custom-select-trigger {
                min-height: 48px;
                padding: 12px 14px;
                font-size: 0.95rem;
            }
            .custom-select-dropdown .option {
                padding: 14px 14px;
                font-size: 0.95rem;
                min-height: 48px;
            }
            .custom-select-dropdown {
                max-height: 200px;
                top: calc(100% + 2px);
            }
            .preview-box {
                height: 220px;
                font-size: 13px;
            }
        }

        @media (max-width: 400px) {
            .header h1 {
                font-size: 1.3rem;
            }
            .header p {
                font-size: 0.85rem;
            }
            .tab-btn {
