<script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/gsap.min.js"></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/ScrollTrigger.min.js"></script>
<script>
/* ============ 雪 ============ */
(function(){
  var canvas=document.getElementById(''snow''),ctx=canvas.getContext(''2d'');
  var W,H,flakes=[],N=140;
  function resize(){W=canvas.width=window.innerWidth;H=canvas.height=window.innerHeight;}
  resize();window.addEventListener(''resize'',resize);
  for(var i=0;i<N;i++){
    flakes.push({
      x:Math.random()*window.innerWidth,
      y:Math.random()*window.innerHeight,
      r:Math.random()*2.3+0.6,
      s:Math.random()*0.55+0.22,
      d:Math.random()*Math.PI*2,
      o:Math.random()*0.55+0.2
    });
  }
  function tick(){
    var doc=document.documentElement;
    var max=doc.scrollHeight-window.innerHeight;
    var p=max>0?(window.scrollY/max):0;
    var density=1-p*0.8;
    ctx.clearRect(0,0,W,H);
    ctx.fillStyle=''#ffffff'';
    for(var i=0;i<flakes.length;i++){
      var f=flakes[i];
      f.y+=f.s*1.7;f.d+=0.008;f.x+=Math.sin(f.d)*0.45;
      if(f.y>H+6){f.y=-6;f.x=Math.random()*W;}
      if(f.x>W+6){f.x=-6;}if(f.x<-6){f.x=W+6;}
      ctx.globalAlpha=f.o*density;
      ctx.beginPath();ctx.arc(f.x,f.y,f.r,0,Math.PI*2);ctx.fill();
    }
    ctx.globalAlpha=1;
    requestAnimationFrame(tick);
  }
  tick();
})();

/* ============ 鼠标星尘轨迹 ============ */
(function(){
  var last=0;
  document.addEventListener(''mousemove'',function(e){
    var now=Date.now();
    if(now-last<75)return;
    last=now;
    var s=document.createElement(''span'');
    s.className=''trail'';
    s.textContent=Math.random()<0.5?''✦'':''❄'';
    s.style.left=e.clientX+''px'';
    s.style.top=e.clientY+''px'';
    s.style.fontSize=(Math.random()*8+7)+''px'';
    (document.getElementById(''xj-page'')||document.body).appendChild(s);
    setTimeout(function(){s.remove();},1150);
  });
})();

/* ============ 2.5D 立体卡 ============ */
(function(){
  document.querySelectorAll(''[data-stereo]'').forEach(function(card){
    var inner=card.querySelector(''.stereo-inner'');
    var holo=card.querySelector(''.stereo-holo'');
    card.addEventListener(''mousemove'',function(e){
      var r=card.getBoundingClientRect();
      var px=(e.clientX-r.left)/r.width-0.5;
      var py=(e.clientY-r.top)/r.height-0.5;
      inner.style.transform=''rotateY(''+(px*15)+''deg) rotateX(''+(-py*13)+''deg)'';
      if(holo){
        holo.style.setProperty(''--hx'',(50+px*85)+''%'');
        holo.style.setProperty(''--hy'',(50+py*85)+''%'');
      }
    });
    card.addEventListener(''mouseleave'',function(){
      inner.style.transform=''rotateY(0deg) rotateX(0deg)'';
    });
  });
})();

/* ============ 灯箱 ============ */
(function(){
  var lb=document.getElementById(''lightbox'');
  var lbImg=lb.querySelector(''img'');
  var lbCap=lb.querySelector(''.lb-cap'');
  document.querySelectorAll(''img[data-zoom]'').forEach(function(im){
    im.addEventListener(''click'',function(){
      lbImg.src=im.src;
      lbCap.textContent=im.getAttribute(''data-cap'')||'''';
      lb.classList.add(''on'');
      document.body.style.overflow=''hidden'';
    });
  });
  function close(){lb.classList.remove(''on'');document.body.style.overflow='''';}
  lb.addEventListener(''click'',close);
  document.addEventListener(''keydown'',function(e){if(e.key===''Escape'')close();});
})();

/* ============ BGM 播放器（替代原「回到顶部」）============ */
(function(){
  var btn=document.getElementById(''bgm'');
  if(!btn) return;
  var au=new Audio();
  au.src=''https://raw.githubusercontent.com/mikyo-miao/goodjob/main/assets/xuejian/audio/xuejian_chuxue.mp3'';
  au.loop=true;
  au.volume=0.3;
  au.preload=''auto'';
  var on=false, armed=true;
  function paint(){
    btn.classList.toggle(''on'',on);
    btn.textContent=on?''❄'':''♪'';
    btn.title=on?''暂停 · 初雪落在你肩上'':''播放 · 初雪落在你肩上'';
  }
  function start(){
    var r=au.play();
    if(r&&r.then){ r.then(function(){on=true;paint();}).catch(function(){on=false;paint();}); }
    else { on=true; paint(); }
  }
  function stop(){ try{au.pause();}catch(e){} on=false; paint(); }
  btn.addEventListener(''click'',function(e){
    e.preventDefault(); e.stopPropagation(); armed=false;
    if(on){stop();}else{start();}
  });
  function arm(){ if(!armed) return; armed=false; if(!on) start(); }
  [''pointerdown'',''touchstart'',''touchend'',''keydown'',''scroll''].forEach(function(ev){
    window.addEventListener(ev,arm,{passive:true});
  });
  paint();
  start();
})();

/* ============ 开局设定 ============ */
(function(){
  var modes=["纯爱模式","堕落模式"];
  var diffs=[
    {name:"简单",desc:"本金 120 万 · 大概还一年半"},
    {name:"标准",desc:"本金 180 万 · 大概还两年"},
    {name:"困难",desc:"本金 240 万 · 两年多"}
  ];
  var openings=[
    {name:"地库之夜",text:"晚上十一点，保姆车缓缓开进酒店地库。你陪她录了一整天的打歌节目，她刚在车上睡了半小时，被停车的声音惊醒，迷迷糊糊揉着眼睛，习惯性地往你肩膀上拱。\n「哥……」\n她声音带着浓浓的鼻音，像只没睡醒的小猫。她伸手摸你的口袋，摸到那根你下午趁虹姐不注意偷偷塞进去的烤淀粉肠，眼睛瞬间亮了——随即她像想起什么，飞快把肠塞回你兜里，警惕地看了一眼电梯口方向。\n「虹姐还没走。」\n她小声嘀咕着，把口罩往上拉了拉。电梯门打开的前一秒，她凑过来，飞快在你的衣领上蹭了蹭，用只有你能听见的声音说：\n「今晚，你帮我洗头好不好，发胶好臭……」"},
    {name:"出租屋周末",text:"周六下午三点，老城区的出租屋。她难得没有通告，穿着你那件洗得发白的旧 T 恤，盘腿窝在沙发里，怀里抱着一包薯片，电视里放着重播的无聊综艺。\n看见你拿起外套，她头也不抬地伸出一根手指晃了晃：\n「哥，今天不许出门，也不许玩手机。你的周末，被我征用了。」\n她拍了拍身边的沙发垫，薯片渣掉了一身也不自知。"},
    {name:"突击查房",text:"早上七点，酒店房门被敲响了——门外是虹姐的声音。\n她顶着一头睡乱的长毛从被窝里弹起来，睡意全无，手忙脚乱地把你往卫生间推，压低声音又急又凶：\n「快躲进去！就说……就说我生理期肚子疼，你是被我叫来送药的！」\n门外的敲门声又响了两下。她胡乱扒了两下头发，深吸一口气，换上了那副标准的营业笑容。"},
    {name:"初雪生日",text:"12 月 24 日，初雪。她收工回来时已经很晚了，帽子和肩膀上落满了雪，鼻尖冻得通红。\n她把双手背在身后，站在门口不肯进来，眼睛亮晶晶地看着你，欲言又止——\n「那个……哥。」\n她的声音比平时小了半度，脚尖在雪水里轻轻蹭了蹭。\n「你还记得，今天是什么日子吗？」"}
  ];
  function $(id){return document.getElementById(id);}
  function picked(name){
    var v=0;
    document.querySelectorAll("input[name="+name+"]").forEach(function(r){if(r.checked)v=+r.value;});
    return v;
  }
  $("btnGen").addEventListener("click",function(){
    var name=$("stName").value.trim()||"（未填写）";
    var gender=$("stGender").value;
    var look=$("stLook").value.trim()||"（未填写）";
    var extra=$("stExtra").value.trim()||"（无）";
    var mode=modes[picked("mode")];
    var diff=diffs[picked("diff")];
    var op=openings[picked("opening")];
    $("stOut").value=
"【主角档案】\n姓名："+name+"\n性别："+gender+"\n外貌："+look+"\n额外设定："+extra+
"\n\n【世界设定】\n开局日期：11/23（周一）\n模式："+mode+"\n难度："+diff.name+"（"+diff.desc+"）"+
"\n\n【开场 · "+op.name+"】\n"+op.text;
    $("stOut").focus();
  });
  $("btnCopy").addEventListener("click",function(){
    var txt=$("stOut").value;
    var btn=$("btnCopy");
    function reset(msg,t){btn.textContent=msg;setTimeout(function(){btn.textContent="复制开局设定";},t);}
    if(!txt.trim()){reset("还没有内容哦",1500);return;}
    function done(){reset("已复制 ✓",1600);}
    function legacy(){
      $("stOut").select();
      try{document.execCommand("copy");done();}
      catch(e){reset("复制失败，请手动复制",1800);}
    }
    if(navigator.clipboard&&navigator.clipboard.writeText){
      navigator.clipboard.writeText(txt).then(done).catch(legacy);
    }else{legacy();}
  });
})();

/* ============ 首屏立绘视差 ============ */
(function(){
  var hero=document.getElementById(''hero'');
  var box=document.querySelector(''.hero-floaters'');
  if(!hero||!box||!window.matchMedia||!window.matchMedia(''(pointer:fine)'').matches)return;
  var items=[].slice.call(box.querySelectorAll(''.fc''));
  if(!items.length)return;
  var tx=0,ty=0,cx=0,cy=0,raf=null;
  function loop(){
    cx+=(tx-cx)*0.06;cy+=(ty-cy)*0.06;
    for(var i=0;i<items.length;i++){
      var d=parseFloat(items[i].getAttribute(''data-depth''))||0.5;
      var rot=(cx*d*1.6).toFixed(3);
      items[i].style.transform=''translate3d(''+(cx*d*26).toFixed(2)+''px,''+(cy*d*13).toFixed(2)+''px,0) rotate(''+rot+''deg)'';
    }
    if(Math.abs(tx-cx)>0.0012||Math.abs(ty-cy)>0.0012){raf=requestAnimationFrame(loop);}
    else{raf=null;}
  }
  function kick(){if(!raf)raf=requestAnimationFrame(loop);}
  hero.addEventListener(''mousemove'',function(e){
    var r=hero.getBoundingClientRect();
    tx=(e.clientX-r.left)/r.width-0.5;
    ty=(e.clientY-r.top)/r.height-0.5;
    kick();
  });
  hero.addEventListener(''mouseleave'',function(){tx=0;ty=0;kick();});
})();

/* ============ 滚动动效 ============ */
window.addEventListener(''load'',function(){
  if(!window.gsap){fallback();return;}
  gsap.registerPlugin(ScrollTrigger);

  gsap.fromTo(''.reveal-hero'',
    {y:36,opacity:0},
    {y:0,opacity:1,duration:1.3,stagger:0.22,ease:''power3.out'',delay:0.2});

  document.querySelectorAll(''.reveal'').forEach(function(el){
    gsap.fromTo(el,{y:46,opacity:0},{
      y:0,opacity:1,duration:1.1,ease:''power2.out'',
      scrollTrigger:{trigger:el,start:''top 86%''}
    });
  });

  var tl=document.getElementById(''tlLine'');
  if(tl){
    gsap.fromTo(tl,{scaleY:0},{
      scaleY:1,ease:''none'',
      scrollTrigger:{trigger:''.timeline'',start:''top 75%'',end:''bottom 60%'',scrub:0.6}
    });
  }

  document.querySelectorAll(''.watermark'').forEach(function(el){
    gsap.to(el,{yPercent:-18,ease:''none'',
      scrollTrigger:{trigger:el.parentElement,start:''top bottom'',end:''bottom top'',scrub:1}});
  });

  /* 红章盖印 */
  document.querySelectorAll(''.bill-stamp'').forEach(function(el){
    gsap.fromTo(el,{scale:2.2,opacity:0,rotate:32},{
      scale:1,opacity:0.88,rotate:11,duration:0.55,ease:''power4.in'',
      scrollTrigger:{trigger:el,start:''top 82%''}
    });
  });

  /* 粉丝数 count-up */
  document.querySelectorAll(''.countup'').forEach(function(el){
    var target=parseFloat(el.getAttribute(''data-to''));
    var dec=el.getAttribute(''data-dec'')===''1'';
    ScrollTrigger.create({
      trigger:el,start:''top 88%'',once:true,
      onEnter:function(){
        var obj={v:0};
        gsap.to(obj,{v:target,duration:1.8,ease:''power2.out'',onUpdate:function(){
          el.textContent=dec?obj.v.toFixed(1):Math.round(obj.v);
        }});
      }
    });
  });

  /* 目标进度条 */
  document.querySelectorAll(''.goal-fill'').forEach(function(el){
    ScrollTrigger.create({
      trigger:el,start:''top 90%'',once:true,
      onEnter:function(){el.style.width=el.getAttribute(''data-goal'')+''%'';}
    });
  });

  var note=document.getElementById(''sideNote'');
  [''#faces'',''#emotions'',''#body-sec'',''#secret'',''#wardrobe'',''#album'',''#play'',''#finale'',''#setup''].forEach(function(sel){
    var sec=document.querySelector(sel);
    if(!sec)return;
    ScrollTrigger.create({
      trigger:sec,start:''top 55%'',end:''bottom 55%'',
      onEnter:function(){note.classList.add(''on-light'');},
      onEnterBack:function(){note.classList.add(''on-light'');},
      onLeave:function(){note.classList.remove(''on-light'');},
      onLeaveBack:function(){note.classList.remove(''on-light'');}
    });
  });
});
/* 无 GSAP 时的保底 */
function fallback(){
  document.querySelectorAll(''.reveal,.reveal-hero'').forEach(function(el){el.style.opacity=1;});
  document.querySelectorAll(''.countup'').forEach(function(el){el.textContent=el.getAttribute(''data-to'');});
  document.querySelectorAll(''.goal-fill'').forEach(function(el){el.style.width=el.getAttribute(''data-goal'')+''%'';});
}
setTimeout(function(){if(!window.gsap)fallback();},2500);
</script>
</body>
</html>', '二次元', '2026-09-16 11:22:22', '2026-09-16 11:22:22') ON CONFLICT (id) DO NOTHING;
