<div id="toast" style="position:fixed; bottom:30px; left:50%; transform:translateX(-50%); background:var(--color-primary); color:#white; padding:10px 20px; border-radius:20px; display:none; z-index:10000; box-shadow:0 4px 15px rgba(0,0,0,0.5);" role="alert" aria-live="polite"></div>
<script>
const tabs = document.querySelectorAll(''.tab-btn'');
const panels = document.querySelectorAll(''.panel'');
tabs.forEach(tab => {
tab.addEventListener(''click'', () => {
tabs.forEach(t => { t.classList.remove(''active''); t.setAttribute(''aria-selected'', ''false''); });
panels.forEach(p => p.classList.remove(''active''));
tab.classList.add(''active'');
tab.setAttribute(''aria-selected'', ''true'');
document.getElementById(tab.getAttribute(''aria-controls'')).classList.add(''active'');
});
});
function selectTag(el) {
const traitArea = document.getElementById(''p-trait'');
if(!traitArea.value.includes(el.innerText)) {
traitArea.value += (traitArea.value ? ''，'' : '''') + el.innerText;
}
}
function rerollTags() {
const pool = document.getElementById(''random-pool'');
const tags = [
{n:''视奸成瘾'', q:''''}, {n:''言语凌辱'', q:''tag-rare''}, {n:''钞能力'', q:''tag-epic''},
{n:''体能怪物'', q:''tag-rare''}, {n:''触手操控'', q:''tag-legend''}, {n:''纯爱战神(伪)'', q:''tag-epic''},
{n:''道具专家'', q:''''}, {n:''录像怪癖'', q:''tag-rare''}
];
pool.innerHTML = '''';
for(let i=0; i<4; i++) {
const r = tags[Math.floor(Math.random()*tags.length)];
pool.innerHTML += `<span class="random-tag ${r.q}" onclick="selectTag(this)">${r.n}</span>`;
}
}
function copyData() {
const name = document.getElementById(''p-name'').value;
if(!name) {
showToast(''请输入玩家代号！'');
document.getElementById(''p-name'').focus();
document.getElementById(''p-name'').setAttribute(''aria-invalid'', ''true'');
return;
}
const data = `【用户信息】\n姓名：${name}\n年龄：${document.getElementById(''p-age'').value}\n身份：${document.getElementById(''p-job'').value}\n特质：${document.getElementById(''p-trait'').value}\n系统：${document.getElementById(''sys-type'').value}\n难度：${document.getElementById(''sys-hard'').value}\n【开场设定】\n${document.getElementById(''w-start'').value}`;
const tempInput = document.createElement(''textarea'');
tempInput.value = data;
document.body.appendChild(tempInput);
tempInput.select();
try {
document.execCommand(''copy'');
showToast(''✅ 档案已加密复制，准备进入深渊...'');
} catch (err) {
showToast(''❌ 复制失败，请手动选择'');
}
document.body.removeChild(tempInput);
}
function showToast(msg) {
const t = document.getElementById(''toast'');
t.innerText = msg;
t.style.display = ''block'';
setTimeout(() => { t.style.display = ''none''; }, 2000);
}
function resetForm() {
if(confirm(''确定要清除所有档案数据吗？'')) {
location.reload();
}
}
document.getElementById(''intro-overlay'').addEventListener(''click'', function() {
