    transition: all 0.3s ease !important;
}

/* 展开时的交互微调 */
details[open] {
    border-color: #6495ED !important; /* 展开后边框变深一点 */
    background: #F0F8FF !important;
}

/* 状态栏标题 (Summary) */
summary {
