/* =========================================
   自定义UI包裹层 (完整保留，重构为复古小说主题)
   ========================================= */
.c {
  max-width: 800px; margin: 0 auto;
  background: linear-gradient(135deg, #fdf6e3 0%, #f4ebd0 100%); 
  color: #2c2216;
  font-family: "STKaiti", "KaiTi", "SimSun", serif;
  font-size: 16px; line-height: 1.8;
  border-radius: 4px; padding: 16px;
  box-shadow: 
    0 10px 30px -5px rgba(0,0,0,0.1),
    0 0 0 1px rgba(139, 38, 38, 0.1) inset;
  border: 1px solid #d4c4a1;
}

details { 
  margin-bottom: 14px; 
  border-radius: 4px; 
  overflow: visible; 
  box-shadow: 0 4px 6px rgba(0,0,0,0.05);
  transition: all 0.3s ease;
}

summary {
  padding: 12px 16px; font-weight: 800; cursor: pointer;
  list-style: none; 
  color: #2c2216 !important; 
  text-shadow: none;
  display: flex; justify-content: space-between; align-items: center;
  font-size: 15px; letter-spacing: 2px;
  background-image: linear-gradient(#f4ebd0, #e9dac1);
  border-radius: 4px; 
  border: 1px solid #d4c4a1;
}
details[open] > summary {
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
  border-bottom: 1px solid #c3b391;
}
summary::-webkit-details-marker { display: none; }
summary::after { content: "▼"; font-size: 10px; transition: transform 0.3s; opacity: 0.7; color: #8b2626; }
details[open] > summary::after { transform: rotate(180deg); color: #a53232; }

.c > details:nth-of-type(1) { background: linear-gradient(to bottom, #fdf6e3, #f4ebd0); border: 1px solid #d4c4a1; }
.c > details:nth-of-type(1) > summary { background-color: #f4ebd0; background-image: linear-gradient(135deg, #f4ebd0, #e9dac1); box-shadow: 0 2px 10px rgba(139, 38, 38, 0.05); }
.c > details:nth-of-type(1) .i, .c > details:nth-of-type(1) .l div, .c > details:nth-of-type(1) .txt div { color: #8b2626; }
.c > details:nth-of-type(1) .i { background: #e9dac1; border: 1px solid #d4c4a1; }
