.c > details:nth-of-type(2) { background: linear-gradient(to bottom, #fdf6e3, #f4ebd0); border: 1px solid #c2d4c6; }
.c > details:nth-of-type(2) > summary { background-color: #eaf0eb; background-image: linear-gradient(135deg, #eaf0eb, #d5e0d7); box-shadow: 0 2px 10px rgba(46, 139, 87, 0.05); }
.c > details:nth-of-type(2) .i, .c > details:nth-of-type(2) .txt div, .c > details:nth-of-type(2) .bd { color: #3b5e47; }
.c > details:nth-of-type(2) .i { background: #d5e0d7; border: 1px solid #b3c7b8; }
.c > details:nth-of-type(2) .i span { color: #2c4234; }

.c > details:nth-of-type(3) { background: #fdf6e3; border: 1px solid #d4c4a1; color: #4a3b2c; }
.c > details:nth-of-type(3) > summary { background-color: #f4ebd0; background-image: linear-gradient(135deg, #f4ebd0, #e9dac1); border-bottom: 1px solid #d4c4a1; }
.term { padding: 15px; background: radial-gradient(circle at top right, rgba(139, 38, 38, 0.03), transparent); }
.term > div { font-weight: 700; color: #2c2216; text-shadow: none; border-bottom: 1px dashed rgba(139,38,38,0.2); padding: 6px 0; }
.mon { background: rgba(244, 235, 208, 0.8); border: 1px solid #d4c4a1; color: #8b2626 !important; border-radius: 2px; margin: 8px 0; box-shadow: 0 0 15px rgba(139, 38, 38, 0.05) inset; font-family: "STKaiti", serif; }

.c > details:nth-of-type(4) { background: linear-gradient(to bottom, #fdf6e3, #f4ebd0); border: 1px solid #d4c4a1; }
.c > details:nth-of-type(4) > summary { background-color: #f4ebd0; background-image: linear-gradient(135deg, #f4ebd0, #e9dac1); border-bottom: 1px solid #c3b391; color: #2c2216 !important;}

.tip {
  position: static; 
  cursor: help;
  border-bottom: 1px dotted rgba(139,38,38,0.6);
  font-weight: bold;
  transition: all 0.2s;
  color: #4a3b2c;
}
.tip:hover { color: #8b2626; text-shadow: none; }

.pop {
  visibility: hidden;
  background: linear-gradient(135deg, rgba(253, 246, 227, 0.98), rgba(244, 235, 208, 0.98));
  backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px);
