.purple-text { color: #5e1a78; font-weight: bold; }
.pink-text   { color: #8b2626; font-weight: bold; }
.blue-text   { color: #1a4a66; font-weight: bold; }
.gold-text   { color: #8c7b65; font-weight: bold; }
.red-text    { color: #a53232; font-weight: bold; }
.char-text   { color: #4a3b2c; }
.tal-text    { color: #8b2626; }
.link-color  { color: #3b5e47; font-weight: bold; }

.tt-container {
  position: relative; display: inline-block; cursor: help;
}
.tt-wave {
  text-decoration: underline wavy; text-decoration-color: #8b2626;
  text-decoration-thickness: 1.5px; text-underline-offset: 3px; transition: all 0.2s;
}
.tt-container:hover .tt-wave { color: #a53232; text-shadow: none; }

.tt-pop {
  visibility: hidden; opacity: 0; position: fixed; top: 50%; left: 50%;
  transform: translate(-50%, -50%) scale(0.9); width: 300px; max-width: 90vw; 
  background: rgba(253, 246, 227, 0.98); backdrop-filter: blur(12px);
  border-radius: 2px; padding: 15px;
  box-shadow: 0 20px 60px rgba(0,0,0,0.15), 0 0 0 1000px rgba(0,0,0,0.2); 
  border: 1px solid rgba(139,38,38,0.3); z-index: 9999; 
  transition: all 0.2s cubic-bezier(0.18, 0.89, 0.32, 1.28);
  pointer-events: none; text-align: left;
}
.tt-container:hover .tt-pop { visibility: visible; opacity: 1; transform: translate(-50%, -50%) scale(1); }

.tp-title {
  display: block; font-size: 16px; text-transform: uppercase; letter-spacing: 2px;
  margin-bottom: 8px; padding-bottom: 6px; border-bottom: 1px dashed rgba(139,38,38,0.3);
  color: #8b2626; font-weight: bold;
}
.tp-body { display: block; font-size: 14px; color: #4a3b2c; line-height: 1.6; font-weight: normal; }

.pop-orange { border-top: 2px solid #a67c52; } .pop-orange .tp-title { color: #8b5a2b; }
.pop-purple { border-top: 2px solid #6b426b; } .pop-purple .tp-title { color: #550055; }
.pop-blue   { border-top: 2px solid #4a6b8c; } .pop-blue .tp-title   { color: #003366; }
.pop-green  { border-top: 2px solid #5a7a5a; } .pop-green .tp-title  { color: #3b5e47; }
.pop-red    { border-top: 2px solid #a53232; } .pop-red .tp-title    { color: #8b2626; }
.pop-gold   { border-top: 2px solid #a6957a; } .pop-gold .tp-title   { color: #8c7b65; }
.pop-dark   { border-top: 2px solid #d4c4a1; background: #fdf6e3; color: #4a3b2c; }
.pop-dark .tp-title { color: #8b2626; border-bottom-color: #d4c4a1; } .pop-dark .tp-body { color: #5c4d3c; }

.npc-layout-grid { display: flex; gap: 15px; align-items: flex-start; margin-bottom: 10px; }
.npc-avatar-col { flex-shrink: 0; }
.npc-info-col { flex: 1; min-width: 0; }

.npc-avatar-face {
  width: 110px; height: 110px; border-radius: 2px;
  border: 1px solid #d4c4a1; box-shadow: 0 4px 15px rgba(0,0,0,0.1);
  background-color: #f4ebd0; filter: sepia(50%) contrast(110%);
}

.header-barrier-scene { position: relative; height: 180px; background: #fdf6e3; overflow: hidden; margin-bottom: 20px; border-bottom: 2px solid #d4c4a1; }
.sky-gradient { position: absolute; width: 100%; height: 100%; background: radial-gradient(circle at 50% 120%, #f4ebd0 0%, #fdf6e3 70%); }
.barrier-dome {
  position: absolute; bottom: -20px; left: 50%; transform: translateX(-50%);
  width: 120%; height: 200px;
  background: radial-gradient(circle at 50% 0%, rgba(253,246,227,0.8), rgba(139,38,38,0.05) 60%, rgba(139,38,38,0.1) 100%);
  border-radius: 50% 50% 0 0; border: 1px solid rgba(139,38,38,0.1);
  box-shadow: 0 0 60px rgba(139,38,38,0.05) inset; z-index: 10; overflow: hidden;
}
.barrier-grid-anim {
  position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background-image: linear-gradient(rgba(139,38,38,0.05) 1px, transparent 1px),
  linear-gradient(90deg, rgba(139,38,38,0.05) 1px, transparent 1px);
  background-size: 30px 30px; opacity: 0.6; animation: gridMove 20s linear infinite;
}
@keyframes gridMove { from { transform: translateY(0); } to { transform: translateY(30px); } }

.hud-status-row { position: absolute; top: 30px; width: 100%; display: flex; justify-content: center; gap: 12px; z-index: 20; }
.hud-pill {
  background: rgba(253,246,227,0.9); backdrop-filter: blur(10px); padding: 6px 14px; border-radius: 2px;
  display: flex; align-items: center; gap: 8px; box-shadow: 0 4px 15px rgba(0,0,0,0.05); border: 1px solid #d4c4a1; min-width: 100px;
}
.h-icon { font-size: 20px; text-shadow: none; }
.time-pill .h-icon { color: #5c4d3c; } .loc-pill .h-icon { color: #8b2626; } .weather-pill .h-icon { color: #3b5e47; }
.h-data { display: flex; flex-direction: column; line-height: 1.1; }
.h-lbl { font-size: 11px; color: #8c7b65; font-weight: bold; letter-spacing: 2px; }
.h-val { font-size: 14px; font-weight: bold; color: #2c2216; }

.city-silhouette {
  position: absolute; bottom: 20px; width: 100%; height: 60px;
  display: flex; justify-content: center; align-items: flex-end; gap: 6px; opacity: 0.3; z-index: 15;
}
.bld { background: #d4c4a1; border-top: 1px solid rgba(139,38,38,0.1); }
.b1 { width: 30px; height: 40px; } .b2 { width: 40px; height: 70px; } .b3 { width: 60px; height: 50px; } .b4 { width: 35px; height: 60px; } .b5 { width: 25px; height: 30px; }

.status-panel { background: #f4ebd0; border: 1px solid #d4c4a1; padding: 10px; border-radius: 2px; margin-bottom: 12px; box-shadow: inset 0 0 10px rgba(0,0,0,0.02); }
.status-text-row { font-size: 14px; margin-bottom: 8px; border-bottom: 1px dashed #d4c4a1; padding-bottom: 5px; }
.st-label { font-weight: bold; color: #5c4d3c; margin-right: 5px; }
.st-val { color: #8b2626; font-weight: bold; }

.bar-group { display: flex; flex-direction: column; gap: 6px; }
.bar-row { display: flex; align-items: center; gap: 8px; }
.bar-tag { font-size: 11px; font-weight: bold; width: 20px; text-align: center; color: #fdf6e3; border-radius: 2px; padding: 1px 0; }
.hp { background: #8b2626; } .mp { background: #3b5e47; } .sp { background: #8c7b65; }

.progress-track { flex: 1; height: 8px; background: #e9dac1; border-radius: 0; overflow: hidden; border: 1px solid #d4c4a1; box-shadow: inset 0 1px 5px rgba(0,0,0,0.05); }
.progress-fill { height: 100%; border-radius: 0; position: relative; }
.progress-fill::after {
  content: ""; position: absolute; top: 0; left: 0; bottom: 0; right: 0;
  background-image: linear-gradient(45deg,rgba(255,255,255,.2) 25%,transparent 25%,transparent 50%,rgba(255,255,255,.2) 50%,rgba(255,255,255,.2) 75%,transparent 75%,transparent);
  background-size: 1rem 1rem; animation: progress-bar-stripes 2s linear infinite;
}
.fill-hp { background: linear-gradient(90deg, #a53232 0%, #8b2626 100%); }
.fill-mp { background: linear-gradient(90deg, #5a7a5a 0%, #3b5e47 100%); }
.fill-sp { background: linear-gradient(90deg, #a6957a 0%, #8c7b65 100%); }
.bar-pct { font-size: 11px; width: 30px; text-align: right; color: #5c4d3c; font-family: monospace; }
.npc-panel { background: #fdf6e3; border-color: #d4c4a1; margin-top: 5px; }
.small-bars .progress-track { height: 6px; }

.main-content { padding: 0 20px 20px 20px; }
.theme-details { background: #f4ebd0; border-radius: 2px; margin-bottom: 20px; box-shadow: 0 5px 20px rgba(0,0,0,0.05); border: 1px solid #d4c4a1; overflow: hidden; }
.fold-header { padding: 12px 16px; cursor: pointer; list-style: none; font-weight: bold; color: #2c2216; font-size: 16px; display: flex; align-items: center; text-shadow: none; }
.fold-header::-webkit-details-marker { display: none; }
.fh-icon { margin-right: 10px; font-size: 1.2em; color: #8b2626; } .fh-title { flex: 1; } .fh-arrow { font-size: 10px; transition: transform 0.3s; opacity: 0.5; }
.theme-details[open] .fh-arrow { transform: rotate(180deg); color: #a53232;}
.fold-content { padding: 16px; background: rgba(253,246,227,0.95); }

.purple-theme .fold-header { background: linear-gradient(135deg, #e6dbe6, #f4ebd0); } .purple-theme { border-left: 3px solid #6b426b; }
.orange-theme .fold-header { background: linear-gradient(135deg, #ebdcd0, #f4ebd0); } .orange-theme { border-left: 3px solid #a67c52; }
.pink-details .fold-header { background: linear-gradient(135deg, #ebd0d0, #f4ebd0); } .pink-details { border-left: 3px solid #8b2626; }
.blue-details .fold-header { background: linear-gradient(135deg, #d0e0eb, #f4ebd0); } .blue-details { border-left: 3px solid #4a6b8c; }
.choice-details .fold-header { background: linear-gradient(135deg, #e9dac1, #f4ebd0); } .choice-details { border-left: 3px solid #a6957a; }

.attr-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 12px; }
.attr-item { background: #fdf6e3; padding: 6px; border-radius: 2px; text-align: center; border: 1px solid #d4c4a1; box-shadow: inset 0 0 5px rgba(0,0,0,0.02); }
.ak { display: block; font-size: 12px; color: #5c4d3c; } .av { font-size: 14px; font-weight: 500; color: #2c2216; }
.main-name { color: #8b2626; font-weight: bold; font-size: 16px; text-shadow: none; }
.tags-row { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 15px; }
.tag-box { background: #f4ebd0; border: 1px solid #d4c4a1; padding: 4px 10px; border-radius: 2px; font-size: 13px; color: #2c2216; }
.tk { color: #5c4d3c; margin-right: 4px; } .tv { font-weight: bold; color: #8b2626; }

.sub-details { background: #f4ebd0; border: 1px solid #d4c4a1; border-radius: 2px; margin-bottom: 10px; }
.sub-details summary { padding: 8px 12px; color: #2c2216; font-size: 14px; font-weight: bold; cursor: pointer; border-bottom: 1px solid #d4c4a1; }
.sub-body { padding: 10px 12px; font-size: 14px; color: #4a3b2c; }
.ability-list ul, .simple-list, .item-list, .mini-ul { margin: 5px 0 0 0; padding-left: 20px; color: #4a3b2c; }
.skill-tag, .item-badge { padding: 1px 5px; border-radius: 2px; font-size: 13px; margin-right: 5px; background: #e9dac1; color: #8b2626; border: 1px solid #d4c4a1; }

.text-block { margin-top: 10px; } .tb-row { margin-bottom: 6px; font-size: 14px; color: #2c2216; }
.lore-block { margin-top: 10px; border-left: 3px solid #8b2626; padding-left: 10px; background: rgba(139,38,38,0.02); padding: 8px; border-radius: 0 2px 2px 0; }
.lb-title { font-weight: bold; color: #8b2626; font-size: 14px; margin-bottom: 4px; letter-spacing: 1px; }
.lb-text { font-size: 14px; color: #4a3b2c; line-height: 1.6; }

.mission-box { border: 1px solid; border-radius: 2px; padding: 10px; margin-bottom: 8px; }
.main-m { background: #fdf6e3; border-color: #8b2626; } .sub-m { background: #f4ebd0; border-color: #d4c4a1; border-style: dashed; }
.m-head { font-weight: bold; font-size: 14px; letter-spacing: 2px; margin-bottom: 5px; }
.main-m .m-head { color: #8b2626; } .sub-m .m-head { color: #5c4d3c; }
.m-rew { font-size: 13px; background: rgba(244,235,208,0.8); display: inline-block; padding: 3px 8px; border-radius: 2px; color: #3b5e47; font-weight: bold; border: 1px solid #c2d4c6; margin-top: 4px; }

.bond-list { margin: 0; padding: 0; }
.bond-item { list-style: none; margin-bottom: 15px; border-bottom: 1px dashed #d4c4a1; padding-bottom: 10px; }
.bond-top { display: flex; justify-content: space-between; margin-bottom: 4px; }
.bond-names { font-weight: bold; color: #8b2626; font-size: 14px; }
.bond-lv { font-weight: bold; color: #a53232; font-size: 13px; background: #f4ebd0; padding: 0 6px; border-radius: 2px; border: 1px solid #d4c4a1; }
.bond-bar-wrap { display: flex; align-items: center; gap: 8px; margin-bottom: 4px; }
.bond-bar-track { flex: 1; height: 8px; background: #e9dac1; border-radius: 0; overflow: hidden; border: 1px solid #d4c4a1; }
.bond-bar-fill { height: 100%; background: linear-gradient(90deg, #a53232, #8b2626); border-radius: 0; }
.bond-nums { font-size: 11px; color: #5c4d3c; font-family: monospace; }
.bond-meta { font-size: 12px; color: #8c7b65; }
.bond-tht { font-style: italic; color: #4a3b2c; font-size: 13px; margin-top: 3px; display: block; }

.npc-card { border: 1px solid #d4c4a1; background: #fdf6e3; border-radius: 2px; padding: 12px; margin-bottom: 15px; box-shadow: inset 0 0 10px rgba(0,0,0,0.02); }
.npc-header-row { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; border-bottom: 1px solid #e9dac1; padding-bottom: 5px; }
.npc-name { font-size: 18px; font-weight: bold; color: #8b2626; text-shadow: none; }
.npc-tags span { font-size: 11px; background: #f4ebd0; border: 1px solid #d4c4a1; color: #8b2626; padding: 2px 6px; border-radius: 2px; margin-left: 4px; }
.compact { grid-template-columns: 1fr 1fr; margin-bottom: 8px; }
.mind-block { background: #fdf6e3; border-radius: 2px; padding: 8px; margin: 8px 0; border: 1px solid #d4c4a1; }
.mb-row { font-size: 13px; color: #4a3b2c; margin-bottom: 2px; }

.r18-zone { border-color: #d4c4a1; background: #fdf6e3; } .r18-zone summary { color: #8b2626; font-weight: bold; }
.r18-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.r-cell { background: #f4ebd0; padding: 5px; border-radius: 2px; font-size: 13px; border: 1px solid #d4c4a1; color: #2c2216; }
.r-k { color: #8b2626; font-weight: bold; margin-right: 4px; }

.term-style { background: #fdf6e3; color: #3b5e47; font-family: "Consolas", monospace; border-radius: 0 0 4px 4px; border: 1px solid #d4c4a1; border-top: none; }
.term-line { margin-bottom: 6px; border-bottom: 1px dashed #d4c4a1; padding-bottom: 2px; color: #5c4d3c; }
.monitor-box { border: 1px solid #d4c4a1; background: #f4ebd0; padding: 8px; margin-bottom: 10px; box-shadow: inset 0 0 15px rgba(139,38,38,0.05); }
.alert-text { color: #8b2626; font-weight: bold; text-shadow: none; }
.blink { animation: blinker 1.5s linear infinite; }
@keyframes blinker { 50% { opacity: 0.3; } }
.comm-box { border-left: 3px solid #8b2626; background: rgba(139,38,38,0.05); padding: 8px; margin-bottom: 10px; }
.info-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.info-table th { border: 1px solid #d4c4a1; padding: 4px; color: #8b2626; text-align: left; background: #e9dac1; }
.info-table td { border: 1px solid #e9dac1; padding: 4px; color: #4a3b2c; }
.mem-details { background: #fdf6e3; border: 1px solid #d4c4a1; margin-bottom: 5px; }

.choice-list { display: flex; flex-direction: column; gap: 10px; }
.opt-btn { background: #f4ebd0; border: 1px solid #d4c4a1; padding: 12px; border-radius: 2px; font-weight: bold; color: #2c2216; cursor: pointer; transition: all 0.2s; text-align: left; box-shadow: 0 4px 0 #e9dac1; font-family: "STKaiti", serif; font-size: 15px;}
.opt-btn:hover { transform: translateY(-2px); box-shadow: 0 6px 0 #d4c4a1; background: #e9dac1; color: #8b2626; border-color: #8b2626; }

@media (max-width: 600px) {
  .attr-grid { grid-template-columns: 1fr 1fr; }
  .r18-grid { grid-template-columns: 1fr; }
  .hud-status-row { flex-direction: column; align-items: center; top: 20px; gap: 8px; }
  .hud-pill { width: 80%; justify-content: center; }
  .barrier-dome { height: 240px; }
  .header-barrier-scene { height: 220px; }
}

.spirit-flat-belt { display: flex; width: 100%; height: 8px; margin: 0; padding: 0; background: #f4ebd0; border-bottom: 1px solid #d4c4a1; }
.s-flat { flex: 1; height: 100%; opacity: 0.6; }
.f-tohka { background: #6b426b; } .f-yoshino { background: #3b5e47; } .f-kurumi { background: #8b2626; }
.f-kotori { background: #a53232; } .f-yamai { background: #8c7b65; } .f-miku { background: #4a6b8c; }
.f-natsumi { background: #5a7a5a; } .f-origami { background: #a6957a; } .f-nia { background: #5c4d3c; }
.f-mukuro { background: #a67c52; }

.date-cot-wrapper {
    position: relative; width: 100%; height: 40px; margin-bottom: 10px;
    background: rgba(244, 235, 208, 0.8); border: 1px solid #d4c4a1; border-radius: 2px; overflow: hidden; box-shadow: inset 0 0 15px rgba(139, 38, 38, 0.05);
}
.cot-status-processing {
    width: 100%; height: 100%; display: flex; align-items: center; justify-content: center;
    color: #8b2626; font-weight: bold; font-family: ''STKaiti'', sans-serif; font-size: 15px; letter-spacing: 4px;
}
.d-dot { opacity: 0; animation: dot-blink 1.5s infinite; color: #8b2626; }
.d1 { animation-delay: 0.0s; } .d2 { animation-delay: 0.5s; } .d3 { animation-delay: 1.0s; }
@keyframes dot-blink { 0% { opacity: 0; } 50% { opacity: 1; } 100% { opacity: 0; } }
.cot-hidden-logic { display: none; }
.cot-status-finished {
    position: absolute; top: 0; left: 0; width: 100%; height: 100%; background: #fdf6e3; display: flex; align-items: center; justify-content: center;
    color: #8b2626; font-weight: bold; font-size: 15px; letter-spacing: 4px; animation: slide-up-fade 0.5s ease-out; z-index: 10; border: 1px solid #d4c4a1;
}
@keyframes slide-up-fade { 0% { transform: translateY(100%); opacity: 0; } 100% { transform: translateY(0); opacity: 1; } }

/* =========================================
   核心聊天框与平台覆盖 (小说/泛黄纸张风格)
   ========================================= */

/* 统一聊天框 */
.bg-gray-100\/90.relative.inline-block {
    background: linear-gradient(135deg, #fdf6e3 0%, #f0e4c3 100%) !important;
    border: 1px solid #d4c4a1 !important; 
    outline: 1px solid #e9dac1 !important; 
    outline-offset: -2px !important; 
    border-radius: 4px !important;
    box-shadow: inset 0 0 40px rgba(166, 123, 70, 0.1), 0 4px 12px rgba(0,0,0,0.05) !important;
    color: #2c2216 !important; 
    padding: 24px 30px !important;
    isolation: isolate !important;
}

/* 纸张纹理叠加 */
.bg-gray-100\/90.relative.inline-block::before {
    content: "" !important;
    position: absolute !important;
    top: 0 !important; left: 0 !important; right: 0 !important; bottom: 0 !important;
    background-image: url("data:image/svg+xml,%3Csvg viewBox=''0 0 200 200'' xmlns=''http://www.w3.org/2000/svg''%3E%3Cfilter id=''noiseFilter''%3E%3CfeTurbulence type=''fractalNoise'' baseFrequency=''0.85'' numOctaves=''3'' stitchTiles=''stitch''/%3E%3C/filter%3E%3Crect width=''100%25'' height=''100%25'' filter=''url(%23noiseFilter)'' opacity=''0.05''/%3E%3C/svg%3E") !important;
    pointer-events: none !important;
    z-index: -1 !important;
    border-radius: inherit !important;
}

/* 聊天框右下角印章装饰 */
.bg-gray-100\/90.relative.inline-block::after {
    content: "阅" !important; 
    position: absolute !important;
    bottom: 10px !important;
    right: 15px !important;
    font-family: ''STKaiti'', ''KaiTi'', serif !important;
    color: rgba(139, 38, 38, 0.15) !important; 
    font-size: 36px !important;
    font-weight: bold !important;
    pointer-events: none !important;
    border: 2px solid rgba(139, 38, 38, 0.15) !important;
    padding: 2px !important;
    border-radius: 4px !important;
}

/* 核心文本排版 */
.markdown-body {
    font-family: ''STKaiti'', ''KaiTi'', ''SimSun'', serif !important;
    color: #2c2216 !important; 
    text-shadow: none !important;
    font-size: 18px !important; /* 放大字体 */
    letter-spacing: 1.5px !important;
    line-height: 1.85 !important;
    background: transparent !important;
    z-index: 1 !important;
}

.markdown-body strong {
    color: #8b2626 !important;
    font-weight: 900 !important;
}

.markdown-body code {
    background: #f4ebd0 !important;
    border: 1px dashed #d4c4a1 !important;
    color: #8b2626 !important;
    font-family: ''Consolas'', monospace !important;
}

/* 底部附加元素高对比度适配 */
.MuiTypography-root.MuiTypography-body2.css-6c0gf2,
.text-orange-500,
.MuiButton-textPrimary {
    color: #5c4d3c !important; 
    font-family: ''STKaiti'', serif !important; 
    opacity: 0.9 !important;
}

/* 输入框与外部背景 */
.w-full.bg-white, 
.sticky.top-0,
body {
    background: #e9dac1 !important; 
    border-bottom: 2px solid #d4c4a1 !important; 
}

.MuiInputBase-root,
div[class*="bg-white"], textarea, input[type="text"] {
    background-color: #fdf6e3 !important;
    border: 1px solid #d4c4a1 !important; 
    color: #2c2216 !important; 
    border-radius: 4px !important;
    font-family: "STKaiti", serif !important;
    font-size: 16px !important;
}

textarea:focus, input[type="text"]:focus {
    background-color: #fff !important;
    border-color: #8b2626 !important; 
    box-shadow: inset 0 0 10px rgba(139, 38, 38, 0.1) !important;
}

/* 发送按钮重构为印章风格 */
button[aria-label="send"], button[class*="send"] {
    position: relative !important;
    width: 48px !important; height: 48px !important;
    border-radius: 4px !important;
    border: 2px solid #8b2626 !important;
    background: #fdf6e3 !important;
    color: transparent !important;
    box-shadow: 0 2px 5px rgba(0,0,0,0.1) !important;
    overflow: hidden !important;
    transition: all 0.3s ease !important;
}
button[aria-label="send"]::before, button[class*="send"]::before {
    content: "批" !important; position: absolute !important; top: 50% !important; left: 50% !important;
    transform: translate(-50%, -50%) !important; color: #8b2626 !important; font-size: 20px !important; font-family: ''STKaiti'', serif !important; font-weight: bold !important;
}
button[aria-label="send"]:hover, button[class*="send"]:hover {
    background: #8b2626 !important;
}
button[aria-label="send"]:hover::before, button[class*="send"]:hover::before {
    color: #fdf6e3 !important;
}
button[aria-label="send"]::after, button[class*="send"]::after, button[aria-label="send"] svg { display: none !important; }

/* 滚动条美化 */
::-webkit-scrollbar { width: 8px !important; }
::-webkit-scrollbar-track { background: #e9dac1 !important; border-left: 1px solid #d4c4a1 !important; }
::-webkit-scrollbar-thumb { background: #c3b391 !important; border: 1px solid #d4c4a1 !important; border-radius: 4px !important; }
::-webkit-scrollbar-thumb:hover { background: #a6957a !important; }

/* 文本选择颜色 */
::selection { background: #8b2626 !important; color: #fdf6e3 !important; }

/* 角色专属对话前缀重构 (适配浅色主题) */
d { display: inline !important; font-weight: 900 !important; border-bottom: 1px dashed currentColor !important; padding-bottom: 1px !important; margin: 0 3px !important; font-size: 1.05em !important; }
m { display: block !important; color: #5c4d3c !important; font-style: italic !important; font-size: 0.9em !important; margin: 5px 0 !important; border-left: 3px solid #d4c4a1 !important; padding-left: 10px !important; background: rgba(212,196,161,0.2) !important; }

d.tohka { color: #6b426b !important; }
d.origami { color: #4a3b2c !important; background-color: #e9dac1 !important; padding: 2px 8px !important; border: 1px solid #d4c4a1 !important; border-bottom: 2px solid #a6957a !important; }
d.yoshino { color: #3b5e47 !important; }
d.kurumi { color: #8b2626 !important; border-bottom-style: double !important; }
d.kotori { color: #a53232 !important; }
d.mukuro { color: #a67c52 !important; }
d.natsumi { color: #5a7a5a !important; }
d.yamai { color: #8c7b65 !important; }
d.miku { color: #4a6b8c !important; }
d.nia { color: #5c4d3c !important; }
d.mio { color: #fdf6e3 !important; background-color: #8b2626 !important; padding: 2px 8px !important; border: 1px solid #a53232 !important; border-bottom: 2px solid #550000 !important; }
d.shido { color: #2c4234 !important; }

