  font-size:28px;
  letter-spacing:2px;
  background:linear-gradient(135deg, #ffffff 0%, #ffe4e6 50%, #f43f5e 100%);
  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;
  text-shadow:0 4px 20px rgba(244,63,94,0.4);
  margin-bottom:8px;
}
.hero .sub{
  position:relative;
  font-size:12px;
  letter-spacing:4px;
  color:#fda4af;
  margin-bottom:16px;
  text-shadow:0 2px 10px rgba(0,0,0,0.5);
}
.hero .tagline{
  position:relative;
  display:inline-block;
  padding:6px 20px;
  border-radius:999px;
  font-size:12.5px;
  letter-spacing:1.5px;
  background:rgba(244,63,94,0.16);
  border:1px solid rgba(244,63,94,0.38);
  color:#fecdd3;
  backdrop-filter:blur(6px);
  box-shadow:0 4px 16px rgba(0,0,0,0.4);
}

/* ====== 通用卡片 ====== */
.card{
  background:var(--card);
  border:1px solid rgba(255,255,255,0.08);
  border-top:1px solid rgba(244,63,94,0.3);
  border-radius:20px;
  padding:22px 20px;
  margin-top:20px;
  backdrop-filter:blur(14px);
  box-shadow:var(--shadow);
  animation:rise .5s ease both;
}
@keyframes rise{
  from{opacity:0;transform:translateY(14px);}
  to{opacity:1;transform:translateY(0);}
}

.sec-title{
  display:flex;
  align-items:center;
  gap:10px;
  font-size:17px;
  font-weight:700;
  color:#f8fafc;
  margin-bottom:16px;
  letter-spacing:0.5px;
}
.sec-title .icon{
  display:inline-flex;
  align-items:center;justify-content:center;
  width:32px;height:32px;
  border-radius:10px;
  font-size:15px;
  background:linear-gradient(135deg,#f43f5e,#a855f7);
  color:#fff;
  box-shadow:0 4px 14px rgba(244,63,94,0.45);
  flex:none;
}
.sec-title::after{
  content:"";
  flex:1;
  height:1px;
  background:linear-gradient(90deg,var(--line),transparent);
}

/* ====== 背景故事 ====== */
.story p{
  font-size:14.5px;
  color:#cbd5e1;
  text-indent:2em;
  margin-bottom:12px;
  text-align:justify;
  line-height:1.9;
}
.story p:last-child{margin-bottom:0;}
.story .hl{
  color:#fb7185;
  font-weight:600;
  background:rgba(244,63,94,0.18);
  padding:2px 6px;
  border-radius:6px;
  border:1px solid rgba(244,63,94,0.25);
}

/* ====== 人物介绍 ====== */
.char-head{
  display:flex;
  gap:16px;
  align-items:center;
  margin-bottom:18px;
}
.avatar{
  width:64px;height:64px;
  border-radius:18px;
  flex:none;
  display:flex;align-items:center;justify-content:center;
  font-family:''Noto Serif SC'',serif;
  font-size:26px;
  font-weight:700;
  color:#fff;
  background:linear-gradient(140deg,#f43f5e,#7c3aed);
  box-shadow:0 6px 22px rgba(244,63,94,0.45);
  position:relative;
  border:1px solid rgba(255,255,255,0.2);
}
.avatar::after{
  content:"✦";
  position:absolute;bottom:-6px;right:-6px;
  width:22px;height:22px;
  border-radius:50%;
  background:#1a1324;
  color:#f43f5e;
  border:1px solid rgba(244,63,94,0.5);
  font-size:11px;
  display:flex;align-items:center;justify-content:center;
  box-shadow:0 3px 10px rgba(0,0,0,0.6);
}
.char-name{font-size:20px;font-weight:700;color:#f8fafc;}
.char-name small{
  font-size:11.5px;
  font-weight:400;
  color:#94a3b8;
  margin-left:10px;
  letter-spacing:1px;
}
.char-tags{
  display:flex;flex-wrap:wrap;gap:8px;
  margin-top:8px;
}
.tag{
  font-size:11.5px;
  padding:3px 12px;
  border-radius:999px;
  color:#c084fc;
  background:rgba(168,85,247,0.15);
  border:1px solid rgba(168,85,247,0.3);
}
.tag.pink{
  color:#fb7185;
  background:rgba(244,63,94,0.15);
  border-color:rgba(244,63,94,0.35);
}

.profile-grid{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:10px;
  margin-top:8px;
}
.profile-item{
  background:rgba(255,255,255,0.03);
  border:1px solid rgba(255,255,255,0.07);
  border-radius:14px;
  padding:12px 14px;
}
.profile-item .k{
  font-size:11px;
  color:#94a3b8;
  letter-spacing:1px;
  margin-bottom:3px;
  display:block;
}
.profile-item .v{
  font-size:13.5px;
  color:#f1f5f9;
  font-weight:600;
  line-height:1.6;
}
.profile-item.wide{grid-column:1 / -1;}

.desc-block{
  margin-top:16px;
  padding:14px 16px;
  border-radius:14px;
  background:linear-gradient(135deg,rgba(244,63,94,0.12),rgba(168,85,247,0.1));
  border:1px solid rgba(244,63,94,0.25);
  font-size:13.5px;
  color:#e2e8f0;
  text-align:justify;
  line-height:1.9;
}
.desc-block b{color:#fb7185;}

/* ====== 玩法 ====== */
.rules{display:flex;flex-direction:column;gap:11px;}
.rule{
  display:flex;gap:12px;
  padding:13px 15px;
  border-radius:14px;
  background:rgba(255,255,255,0.03);
  border:1px solid rgba(255,255,255,0.07);
}
.rule .num{
  flex:none;
  width:26px;height:26px;
  border-radius:9px;
  font-size:12.5px;
  font-weight:700;
  color:#fff;
  display:flex;align-items:center;justify-content:center;
  background:linear-gradient(135deg,#f43f5e,#a855f7);
  box-shadow:0 3px 10px rgba(244,63,94,0.35);
}
.rule .txt{font-size:13.5px;color:#cbd5e1;line-height:1.8;}
.rule .txt b{color:#c084fc;}

/* ====== 开场白 ====== */
.opening-list{
  display:flex;flex-direction:column;gap:12px;
}
.opening{
  position:relative;
  padding:15px 16px 15px 48px;
  border-radius:16px;
  cursor:pointer;
  font-size:13.5px;
  line-height:1.85;
  color:#cbd5e1;
  background:rgba(255,255,255,0.03);
  border:1.5px solid rgba(255,255,255,0.08);
  transition:.25s ease;
  user-select:none;
  text-align:justify;
}
.opening:hover{
  background:rgba(244,63,94,0.08);
  border-color:rgba(244,63,94,0.35);
  transform:translateY(-2px);
  color:#f8fafc;
}
.opening.sel{
  background:linear-gradient(135deg,rgba(244,63,94,0.2),rgba(168,85,247,0.15));
  border-color:#f43f5e;
  box-shadow:0 0 24px rgba(244,63,94,0.35);
  color:#fff;
}
.opening .idx{
  position:absolute;
  left:14px;top:15px;
  width:24px;height:24px;
  border-radius:8px;
  font-size:12px;
  font-weight:700;
  color:#fb7185;
  display:flex;align-items:center;justify-content:center;
  background:rgba(255,255,255,0.06);
  border:1px solid rgba(244,63,94,0.3);
  transition:.25s ease;
}
.opening.sel .idx{
  background:#f43f5e;
  color:#fff;
  border-color:#f43f5e;
  box-shadow:0 0 10px rgba(244,63,94,0.6);
}

/* ====== 表单控件 ====== */
.form-grid{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:12px;
}
.form-item{
  display:flex;flex-direction:column;gap:6px;
}
.form-item.wide{grid-column:1 / -1;}
.form-item label{
  font-size:12px;
  font-weight:600;
  color:#94a3b8;
  letter-spacing:0.5px;
}
.form-item input,
.form-item textarea{
  background:rgba(255,255,255,0.04) !important;
  border:1px solid rgba(255,255,255,0.12) !important;
  border-radius:12px !important;
  padding:10px 14px !important;
  color:#f8fafc !important;
  font-size:13.5px !important;
  font-family:inherit !important;
  outline:none !important;
  transition:border-color .2s, box-shadow .2s;
}
.form-item input:focus,
.form-item textarea:focus{
  border-color:#f43f5e !important;
  box-shadow:0 0 14px rgba(244,63,94,0.35) !important;
  background:rgba(244,63,94,0.05) !important;
}
.custom-opening textarea{
  width:100%;
  min-height:90px;
  margin-top:12px;
}

/* ====== 总结与行动按钮 ====== */
.gen-wrap{
  margin-top:18px;
  text-align:center;
}
.gen-btn, .copy-btn{
  width:100%;
  padding:14px 20px;
  border-radius:14px;
  border:none;
  font-size:15px;
  font-weight:700;
  color:#fff;
  background:linear-gradient(135deg,#f43f5e,#a855f7);
  box-shadow:0 10px 30px rgba(244,63,94,0.45);
  cursor:pointer;
  transition:transform .2s, box-shadow .2s;
  letter-spacing:1px;
}
.gen-btn:hover, .copy-btn:hover{
  transform:translateY(-2px);
  box-shadow:0 14px 38px rgba(244,63,94,0.65);
}
.gen-btn:active, .copy-btn:active{
  transform:translateY(0);
}

.summary-card{
  margin-top:20px;
}
.summary-box{
  background:#09090e;
  border:1px solid rgba(244,63,94,0.3);
  border-radius:14px;
  padding:16px;
  font-size:13px;
  line-height:1.8;
  color:#e2e8f0;
  font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;
  white-space:pre-wrap;
  word-break:break-word;
  max-height:280px;
  overflow-y:auto;
}
.copy-wrap{
  margin-top:14px;
  display:flex;
  flex-direction:column;
  gap:10px;
}
.sum-empty{
  color:#94a3b8;
  font-style:italic;
  text-align:center;
  padding:20px;
}
</style>
</head>
<body>

<div class="app" id="app">

  <!-- ===== 封面 ===== -->
  <div class="hero">
    <div class="moon"></div>
    <h1>巨乳白虎妹妹每晚夜袭肥鲍迷奸</h1>
    <div class="sub">M I D N I G H T · A C C O M P L I C E</div>
    <div class="tagline">白天清冷的校花 · 深夜缠绵的妹妹</div>
  </div>

  <!-- ===== 背景故事 ===== -->
  <div class="card story">
    <div class="sec-title"><span class="icon">❖</span>背景故事</div>
    <p>你们住在老城区一栋旧居民楼里，父母常年在海外工作，家里只剩下你和她。白天，她是学校里公认的<span class="hl">高冷校花</span>，走廊上擦肩而过时不会多看你一眼，说话永远只有两三个字。</p>
    <p>但大约两年前的那个夏天，一切悄悄变了。某个闷热的深夜，她第一次推开你的房门，钻进你的被窝，只是安静地抱着你。那之后，这样的夜访越来越频繁，也越来越大胆——从依偎，到试探，到一套完整的、心照不宣的<span class="hl">深夜仪式</span>。</p>
    <p>白天她依然冷淡，仿佛什么都没发生过。可当你早晨在枕边闻到那股熟悉的甜香，看到她端着牛奶面无表情地路过你房门口时，你们都知道——昨夜的秘密，只有你们两个懂。</p>
    <p>这是一场从未说破的<span class="hl">共犯关系</span>。你究竟是真的睡着了，还是……一直在默许？</p>
  </div>

  <!-- ===== 人物介绍 ===== -->
  <div class="card">
    <div class="sec-title"><span class="icon">✦</span>人物档案</div>

    <div class="char-head">
      <div class="avatar">月</div>
      <div>
        <div class="char-name">林溪月 <small>LIN XIYUE · 18 · 高三</small></div>
        <div class="char-tags">
          <span class="tag pink">亲妹妹</span>
          <span class="tag">同校校花</span>
          <span class="tag">黑长直</span>
          <span class="tag pink">反差</span>
          <span class="tag">夜袭主导者</span>
        </div>
      </div>
    </div>

    <div class="profile-grid">
      <div class="profile-item">
        <span class="k">外 貌</span>
        <span class="v">黑长直 · 瓜子脸 · 凤眼薄唇</span>
      </div>
      <div class="profile-item">
        <span class="k">气 质</span>
        <span class="v">清冷疏离 · 生人勿近</span>
      </div>
      <div class="profile-item">
        <span class="k">身 材</span>
        <span class="v">巨乳 · 蜜桃臀 · 白丝长腿</span>
      </div>
      <div class="profile-item">
        <span class="k">夜间着装</span>
        <span class="v">宽大T恤 · 半透明蕾丝</span>
      </div>
      <div class="profile-item wide">
        <span class="k">性 格</span>
        <span class="v">表层冷淡理性，里层极度兄控、占有欲爆棚</span>
      </div>
      <div class="profile-item wide">
        <span class="k">语 言 风 格</span>
        <span class="v">白天极简冷淡（"嗯。""让开。"），夜间缠绵低语（"哥哥……是我……别醒。"）</span>
      </div>
    </div>

    <div class="desc-block">
      <b>【秘密】</b>她藏在衣柜夹层里有一个小本子，记录着每一次夜袭的日期、你的反应，以及那些绝不外传的细节。她从不让关系越过某条线，却又痴迷于在每个深夜把它推进到极致边缘。<br>
      <b>【执念】</b>她认为哥哥的一切只能属于自己。若白天看到你和别的女生说话，当晚的夜袭会变得格外沉默、也格外漫长。
    </div>
  </div>

  <!-- ===== 玩法 ===== -->
  <div class="card">
    <div class="sec-title"><span class="icon">◈</span>玩法机制</div>
    <div class="rules">
      <div class="rule">
        <div class="num">1</div>
        <div class="txt"><b>夜袭阶段：</b>潜入 → 侍奉 → 骑脸 → 口足 → 半插入 → 善后。每个夜晚会推进至其中若干阶段，节奏由她的心情与你的反应共同决定。</div>
      </div>
      <div class="rule">
        <div class="num">2</div>
        <div class="txt"><b>情动阈值：</b>她越投入，动作越缠绵、气声越失控。但无论多动情，她始终守住最后的底线。</div>
      </div>
      <div class="rule">
        <div class="num">3</div>
        <div class="txt"><b>清醒度：</b>你可以一直装睡，也可以在关键时刻突然睁眼或出声，观察她慌乱失态的真实反应。</div>
      </div>
      <div class="rule">
        <div class="num">4</div>
        <div class="txt"><b>底线博弈：</b>你越想突破边界，她越会夹紧大腿、停下动作，甚至用一两天的日间冷战来回应。</div>
      </div>
      <div class="rule">
        <div class="num">5</div>
        <div class="txt"><b>日间痕迹：</b>床单、枕边、晨间的气息，都是线索。白天她若无其事，可细微的破绽瞒不过你。</div>
      </div>
    </div>
  </div>
  <!-- ===== 玩家设定 ===== -->
  <div class="card">
    <div class="sec-title"><span class="icon">❂</span>玩家设定</div>
    <div class="form-grid">
      <div class="field">
        <label>姓名</label>
        <input type="text" id="pName" placeholder="例如：林默">
      </div>
      <div class="field">
        <label>年龄</label>
        <input type="text" id="pAge" placeholder="例如：18">
      </div>
      <div class="field">
        <label>性别</label>
        <input type="text" id="pGender" placeholder="男 / 女 / 其他">
      </div>
      <div class="field">
        <label>外貌</label>
        <input type="text" id="pLook" placeholder="例如：清瘦高个 · 碎发 · 单眼皮">
      </div>
      <div class="field wide">
        <label>肉棒设定</label>
        <textarea id="pSize" placeholder="尺寸、形状、敏感度、特殊反应……（自由格式，越具体越好）"></textarea>
      </div>
      <div class="field wide">
        <label>其他设定</label>
        <textarea id="pOther" placeholder="身份、性格、习惯、与妹妹的关系细节、隐藏设定、底线态度……"></textarea>
      </div>
    </div>


  <!-- ===== 开场白 ===== -->
  <div class="card">
    <div class="sec-title"><span class="icon">❀</span>开场白 · 选择一个开局</div>
    <div class="opening-list" id="openingList">
      <div class="opening" data-idx="1">
        <span class="idx">1</span>半夜一阵细碎窸窣和床垫下陷把你弄醒。黑暗中清甜洗发水香气逼近，一只微凉的手从背后环住你的腰，耳垂被含进温热唇间，她贴在你耳边气声呢喃：“哥……我来了。”
      </div>
      <div class="opening" data-idx="2">
        <span class="idx">2</span>凌晨的月光从窗帘缝漏进来。你感觉到脸上一片柔软、湿漉漉的温热缓缓摩擦着嘴唇，舌尖尝到一点甜腻。身上的重量很轻，是她的气息，她正居高临下地看着你，长发垂落满脸。
      </div>
      <div class="opening" data-idx="3">
        <span class="idx">3</span>你的睡裤被一只丝滑微凉的脚掌从腰间挑开。黑暗中，纯白丝袜在月光下泛着微光，它的主人背对着你跨坐在你胸口，一手撑着床、一手捂着嘴。不远处传来压抑而黏腻的水声，一下一下。
      </div>
      <div class="opening" data-idx="4">
        <span class="idx">4</span>你梦见自己在吃一颗不断融化、极软的糖，舌尖被另一条柔软的舌头轻轻勾着，交换着温热。半梦醒地睁开眼睛，看到的是她那张近在咫尺、双颊绯红的瓜子脸——她正闭着眼睛，专注地把自己的唾液一点一点渡进你嘴里。
      </div>
      <div class="opening" data-idx="5">
        <span class="idx">5</span>你的呼吸被打乱。黑暗中，能感觉到那对饱满的柔软正隔着T恤一下一下压过你的小腹。她骑在你腰上，一只手撑在你胸口，另一只手传来布料被轻轻掀开的细微声响——你知道，这个夜晚才刚刚开始。
      </div>
    </div>

    <div class="custom-box">
      <div class="lbl">自定义开场白</div>
      <textarea id="customOpening" placeholder="写下你想让她在今晚以哪种方式登场……（填写后将优先使用自定义内容）"></textarea>
    </div>
  </div>

    <div class="gen-wrap">
      <button class="gen-btn" id="genBtn">✦ 生 成 ✦</button>
    </div>
  </div>


  <!-- ===== 总结区 ===== -->
  <div class="summary" id="summary">
    <div class="summary-head">
      <span class="dot"></span>总结区 · SUMMARY
    </div>
    <div class="summary-body" id="summaryBody">
      <div class="sum-empty">还没有生成任何内容……<br>填写上方设定、选择开场白后，点击「生成」。</div>
    </div>

    <div class="copy-wrap">
      <button class="copy-btn" id="copyBtn"><span class="ic">⧉</span>一键复制</button>
    </div>
  </div>

  <div class="footer">
    M I D N I G H T &nbsp;·&nbsp; A C C O M P L I C E<br>
    <span style="letter-spacing:1px;">— 只有你们两个懂的夜晚 —</span>
  </div>

</div>

<script>
(function(){
  var openings = document.querySelectorAll(''.opening'');
  var selectedIdx = -1;
  var customTa = document.getElementById(''customOpening'');
  var genBtn = document.getElementById(''genBtn'');
  var summaryBody = document.getElementById(''summaryBody'');
  var copyBtn = document.getElementById(''copyBtn'');
  var copiedText = '''';

  // 选择开场白
  openings.forEach(function(el){
    el.addEventListener(''click'', function(){
      var idx = parseInt(el.getAttribute(''data-idx''), 10);
      if(selectedIdx === idx){
        selectedIdx = -1;
        el.classList.remove(''sel'');
      } else {
        openings.forEach(function(o){ o.classList.remove(''sel''); });
        selectedIdx = idx;
        el.classList.add(''sel'');
        // 清空自定义，避免冲突
        customTa.value = '''';
      }
    });
  });

  // 输入自定义时清空选择
  customTa.addEventListener(''input'', function(){
    if(customTa.value.trim() !== ''''){
      selectedIdx = -1;
      openings.forEach(function(o){ o.classList.remove(''sel''); });
    }
  });

  // 获取开场白文本
  function getOpeningText(){
    var custom = customTa.value.trim();
    if(custom) return custom;
    if(selectedIdx > 0){
      var el = document.querySelector(''.opening[data-idx="'' + selectedIdx + ''"]'');
      if(el){
        var clone = el.cloneNode(true);
        var idxEl = clone.querySelector(''.idx'');
        if(idxEl) idxEl.parentNode.removeChild(idxEl);
        return clone.innerText.replace(/\s+/g, '' '').trim();
      }
    }
    return '''';
  }

  // 转义
  function esc(s){
    return String(s).replace(/[&<>"'']/g, function(m){
      return {''&'':''&amp;'',''<'':''&lt;'',''>'':''&gt;'',''"'':''&quot;'',"''":''&#39;''}[m];
    });
  }

  // 生成
  genBtn.addEventListener(''click'', function(){
    var name   = document.getElementById(''pName'').value.trim();
    var age    = document.getElementById(''pAge'').value.trim();
    var gender = document.getElementById(''pGender'').value.trim();
    var look   = document.getElementById(''pLook'').value.trim();
    var size   = document.getElementById(''pSize'').value.trim();
    var other  = document.getElementById(''pOther'').value.trim();
    var opening = getOpeningText();

    if(!opening){
      summaryBody.innerHTML = ''<div class="sum-empty">请先选择一个开场白，或在下方填写自定义开场白。</div>'';
      return;
    }

    var vName   = name   || ''（未填写）'';
    var vAge    = age    || ''（未填写）'';
    var vGender = gender || ''（未填写）'';
    var vLook   = look   || ''（未填写）'';
    var vSize   = size   || ''（未填写）'';
    var vOther  = other  || ''（未填写）'';

    var html = '''';
    html += ''<div class="sum-block">'';
    html += ''<div class="st">◈ 玩 家 设 定</div>'';
    html += ''<div class="sv">'';
    html += ''<span class="kv">姓名：</span>'' + esc(vName) + ''\n'';
    html += ''<span class="kv">年龄：</span>'' + esc(vAge) + ''\n'';
    html += ''<span class="kv">性别：</span>'' + esc(vGender) + ''\n'';
    html += ''<span class="kv">外貌：</span>'' + esc(vLook) + ''\n'';
    html += ''<span class="kv">肉棒：</span>'' + esc(vSize) + ''\n'';
    html += ''<span class="kv">其他：</span>'' + esc(vOther);
    html += ''</div></div>'';

    html += ''<div class="sum-block">'';
    html += ''<div class="st">❀ 开 场 白</div>'';
    html += ''<div class="sv">'' + esc(opening) + ''</div>'';
    html += ''</div>'';

    summaryBody.innerHTML = html;

    copiedText = ''【玩家设定】\n''
      + ''姓名：'' + vName + ''\n''
      + ''年龄：'' + vAge + ''\n''
      + ''性别：'' + vGender + ''\n''
      + ''外貌：'' + vLook + ''\n''
      + ''肉棒：'' + vSize + ''\n''
      + ''其他：'' + vOther + ''\n\n''
      + ''【开场白】\n'' + opening;

    // 生成后滚动到总结区
    try{
      document.getElementById(''summary'').scrollIntoView({behavior:''smooth'', block:''center''});
    }catch(e){
      document.getElementById(''summary'').scrollIntoView();
    }
  });

  // 复制
  copyBtn.addEventListener(''click'', function(){
    if(!copiedText){
      copiedText = summaryBody.innerText.replace(/\n{3,}/g, ''\n\n'').trim();
    }
    if(!copiedText) return;

    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(copiedText).then(showCopied).catch(function(){
        fallbackCopy(copiedText);
      });
    } else {
      fallbackCopy(copiedText);
    }
  });

  function fallbackCopy(text){
    var ta = document.createElement(''textarea'');
    ta.value = text;
    ta.style.position = ''fixed'';
    ta.style.top = ''0'';
    ta.style.left = ''0'';
    ta.style.opacity = ''0'';
    document.body.appendChild(ta);
    ta.focus();
    ta.select();
    try{ document.execCommand(''copy''); showCopied(); }catch(e){}
    document.body.removeChild(ta);
  }

  function showCopied(){
    copyBtn.classList.add(''copied'');
    var old = copyBtn.innerHTML;
    copyBtn.innerHTML = ''<span class="ic">✓</span>已复制到剪贴板'';
    setTimeout(function(){
      copyBtn.classList.remove(''copied'');
      copyBtn.innerHTML = old;
    }, 1800);
  }
})();
</script>

</body>
</html>', '都市', '2026-09-16 11:22:22', '2026-09-16 11:22:22') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at) VALUES ('4339eb70-6f5b-40f8-9f19-0da2d6acd6b7', '【roll天赋/大世界，可bg,bl,gb,gl】从零开始的修仙日常', '高自由度修仙 · 苍澜界', '⚔️', '从零开始的修仙日常', 'roll天赋·大世界·开放探索', 'https://catai.wiki/db5174e8-79b6-4fcc-a931-776ee4351000/cover', 'bg-slate-900/90 text-sky-200 border-sky-600/50', 'from-cyan-600 to-blue-700', '{"title": "【roll天赋/大世界，可bg,bl,gb,gl】从零开始的修仙日常", "desc": "欢迎来到最真实的修仙世界！这里你可以体验抽灵根，roll天赋，还可以从凡人开始修仙（也可以开局直接当大佬），众多门派任你挑选，正派反派随你选择，当人还是当妖还是当魔修可以，超高自由度！内置二十几个NPC任你挑选，可bg可bl可gb可gl\n\n", "bg_image": "https://free.picui.cn/free/2025/12/01/692c8049eabb9.jpg", "opening_options": ["今天是百年难得一遇的中州宗门统一开放招收弟子的日子……", "这是你们宗门招收弟子的日子，你作为长老理应前往……", "（自定义开场白）", "（输入“开启灵网”打开论坛，输入“关闭灵网”关闭论坛）"]}', '[{"name": "君亦尘", "role": "昆仑宗掌门", "desc": "外貌三十许岁，面如冠玉，紫金道袍。性格沉稳内敛，心怀天下苍生，行事公正严明，实则是位操心的“老父亲”。"}, {"name": "萧寒衣", "role": "天剑门剑首", "desc": "胜雪白衣，衣角带陈旧血梅，背负麻布缠裹古剑。极度沉默寡言，纯粹的剑痴，战力惊世。"}, {"name": "叶倾城", "role": "昆仑宗首席", "desc": "肌肤胜雪，万年玄冰雕琢般的玉人，素白长裙。极度高冷孤傲，一心向道的修炼狂魔。"}, {"name": "魅姬", "role": "合欢宗宗主", "desc": "清纯与妖艳交织，紫裙赤足，脚踝系红绳金铃。随心所欲玩弄人心，视天下男子为玩物却从未动情。"}, {"name": "温如玉", "role": "青囊药谷谷主", "desc": "面若冠玉，双目覆素白绫缎，浅青宽袖长衫。温和宽厚彬彬有礼，心眼通透能洞察人心。"}, {"name": "君无邪", "role": "天魔教教主", "desc": "魔道第一美男，左金右黑摄人异瞳，暗金魔纹黑皇袍。狂傲霸道智多近妖，立志颠覆修仙界的枭雄。"}]', '[{"title": "中州太白峰下 · 问仙大会 · 宗门招徒大典", "desc": "巍峨磅礴的昆仑仙山直插云霄，太白峰下云海翻涌，瑞气千条。百年难得一遇的中州宗门统一大典今日正式开启，各大正派魁首、中立世家、散修翘楚云集于此。测灵石柱在广场中央耸立，散发出变幻莫测的灵光。各派长老与亲传弟子高踞玉台，审视着台下前赴后继的求道者。天地灵气浩荡激荡，风云变幻，属于你的修仙纪元正在揭开帷幕……"}]', '{"dialogue_style": "修仙沉浸小说笔调，兼顾仙侠意境、人物心机推拉、道法摩擦与感官张力", "format": "AI风月标准双栏规范及.xiuxian-ui样式"}', '[{"index": 1, "isUser": false, "scene": "中州太白峰下 · 问仙大会 · 宗门招徒大典", "story": "<tl>📅时间：大典吉时 | 🌏世界：苍澜界 | 🏘️场所：中州太白峰下·问仙灵台</tl>\n\n<article>\n<p>巍峨直插入天穹的太白峰下，翻滚的七彩霞云如同怒浪翻腾。数以万计的求道者自九州四海跋涉而来，将整座白玉广场围得水泄不通。天际不时有划破虚空的凌厉剑光与华贵云舟飞掠而过，引来阵阵惊叹与抽气声。</p>\n\n<p>“肃静——！”</p>\n\n<p>天剑门长老洛崇珩声若奔雷，浑厚的灵压自高空垂落，瞬息压制全场喧哗。广场正中央，九根雕刻着上古真龙与玄武的测灵石柱陡然轰鸣，幽蓝、赤金与青翠的玄光在石柱纹路中疯狂游走。玉台之上，正道首座昆仑宗掌门君亦尘神色威严温和，天剑门剑首萧寒衣抱剑闭目不语，合欢宗妖娆妩媚的魅姬则掩唇轻笑，一双桃花眼饶有兴致地打量着台下神态各异的年轻人。</p>\n\n<p><w>“若有身怀绝顶灵根或天生剑骨者，本门绝不吝赐下亲传令羽。”</w></p>\n\n<p>台下人群之中，你深吸了一口气，掌心微微沁出薄汗。周围人的目光或期盼、或嫉妒、或警惕，所有人都在等待着你登上测灵台的那一刻。</p>\n<p><thk>台上的各大宗门长老与暗中隐匿的魔修密探都在不动声色地注视着走上前台的每一个苗子，暗自盘算着此人的根骨与未来的道途价值……</thk></p>\n</article>\n\n<opt>\n<suggested_questions>\n<d>A. 【稳步登台测灵】：神色自若迈上测灵白玉台，将手掌贴向九龙测灵柱，毫无保留地展现自身灵根底蕴【策略评估：引动全场异象，直接成为各大顶级宗门争夺的热门天骄】</d>\n<d>B. 【收敛隐匿锋芒】：暗中运转独门匿气法门压制灵压，只展露出平平无奇的双灵根资质【策略评估：藏木于林，避免成为众矢之的，为暗中行事提供掩护】</d>\n<d>C. 【直面魔宗使者】：将目光投向广场角落戴着兜帽的血煞宗或万毒窟使者，传递桀骜不驯的魔道意志【策略评估：脱离正道桎梏，开启凶险莫测、快意恩仇的魔道修仙路】</d>\n<d>D. 【开启灵网玉简】：从怀中取出万宝楼特制的水晶玉简，轻唤“开启灵网”查看全大陆最新八卦与实时宗门招收内幕【策略评估：解锁修仙界互联网论坛模式，搜集情报与修仙道友灌水】</d>\n</suggested_questions>\n</opt>", "branches": [{"tag": "A", "title": "稳步登台展现灵根底蕴", "desc": "迈上测灵白玉台，将手掌贴向九龙测灵柱，引动全场异象"}, {"tag": "B", "title": "收敛隐匿锋芒暗藏底牌", "desc": "暗中运转匿气法门压制灵压，只展现中庸资质，藏木于林"}, {"tag": "C", "title": "直面暗处魔宗试探底线", "desc": "将视线投向边缘魔道使者，探寻非正统道途的别样可能"}, {"tag": "D", "title": "开启灵网玉简搜集情报", "desc": "取出通讯玉简输入“开启灵网”，阅览修仙界论坛热帖与道友议论"}]}]', '/* === 修仙 UI 基础框架 (已完美适配您的模板，去除灵网并格式化) === */

.xiuxian-ui {
    font-family: "KaiTi", "STKaiti", serif;
    background: #f5f7fa url("data:image/svg+xml,%3Csvg width=''64'' height=''64'' viewBox=''0 0 64 64'' xmlns=''http://www.w3.org/2000/svg''%3E%3Cpath d=''M8 16c4.418 0 8-3.582 8-8s-3.582-8-8-8-8 3.582-8 8 3.582 8 8 8zm0-2c3.314 0 6-2.686 6-6s-2.686-6-6-6-6 2.686-6 6 2.686 6 6 6zm33.414-6l5.95-5.95L45.95.636 40 6.586 34.05.636 32.636 2.05 38.586 8l-5.95 5.95 1.414 1.414L40 9.414l5.95 5.95 1.414-1.414L41.414 8zM40 48c4.418 0 8-3.582 8-8s-3.582-8-8-8-8 3.582-8 8 3.582 8 8 8zm0-2c3.314 0 6-2.686 6-6s-2.686-6-6-6-6 2.686-6 6 2.686 6 6 6zM9.414 40l5.95-5.95-1.414-1.414L8 38.586l-5.95-5.95L.636 34.05 6.586 40l-5.95 5.95 1.414 1.414L8 41.414l5.95 5.95 1.414-1.414L9.414 40z'' fill=''%23b0bec5'' fill-opacity=''0.15'' fill-rule=''evenodd''/%3E%3C/svg%3E");
    color: #455a64 !important;
    padding: 15px;
    border: 1px solid #90a4ae;
    border-radius: 5px;
    box-shadow: 0 0 20px rgba(120,144,156,0.15);
    line-height: 1.6;
    max-width: 800px;
    margin: 0 auto;
}

/* 1: 场景信息 */
.xx-header { border-bottom: 1px solid #cfd8dc; padding-bottom: 8px; margin-bottom: 15px; display: flex; flex-wrap: wrap; gap: 8px; }
.xx-tag { background: rgba(236,240,241,0.6); color: #546e7a !important; padding: 2px 6px; border-radius: 3px; font-size: 0.9em; border: 1px solid #cfd8dc; }
.xx-cause { width: 100%; margin-top: 5px; font-style: italic; color: #78909c !important; border-left: 3px solid #78909c; padding-left: 6px; }

/* 2: 故事正文 */
.xx-content { text-indent: 2em; margin-bottom: 20px; font-size: 1.05em; text-align: justify; color: #37474f !important; }

/* 3: 心声模块 */
.xx-voice-box { background: rgba(236,240,241,0.4); border: 1px dashed #b0bec5; padding: 10px; border-radius: 6px; margin-bottom: 15px; position: relative; }
.xx-voice-title { text-align: center; color: #5c6bc0 !important; font-weight: bold; font-size: 0.9em; margin-bottom: 5px; letter-spacing: 1px; }
.xx-voice-list { display: flex; flex-direction: column; gap: 4px; font-size: 0.9em; }
.xx-v-user { color: #00838f !important; }
.xx-v-npc { color: #5c6bc0 !important; }
.xx-v-sys { color: #78909c !important; font-style: italic; }

/* 4 & 5: 面板通用 (道友信息 & 肉身状态) */
.xx-panel { margin-bottom: 10px; border: 1px solid #cfd8dc; background: rgba(255,255,255,0.7); border-radius: 4px; overflow: hidden; }
.xx-sum { background: #eceff1; padding: 8px; cursor: pointer; font-weight: bold; color: #546e7a !important; list-style: none; outline: none; border-bottom: 1px solid #cfd8dc; }
.xx-sum::-webkit-details-marker { display: none; }
.xx-sum::after { content: "▼"; float: right; color: #90a4ae; font-size: 0.8em; }
details[open] > .xx-sum::after { content: "▲"; }
.xx-info-box { padding: 12px; font-size: 0.9em; color: #546e7a !important; }
.xx-row { border-bottom: 1px dashed #cfd8dc; padding: 4px 0; }
.xx-sep { color: #b0bec5; margin: 0 5px; }

/* 修为进度条 */
.xx-bar-bg { display: inline-block; width: 100px; height: 8px; background: #eceff1; border-radius: 4px; overflow: hidden; vertical-align: middle; margin-right: 5px; }
.xx-bar-fg { display: block; height: 100%; background: #81d4fa; background-image: linear-gradient(45deg,rgba(255,255,255,0.2) 25%,transparent 25%,transparent 50%,rgba(255,255,255,0.2) 50%,rgba(255,255,255,0.2) 75%,transparent 75%,transparent); background-size: 10px 10px; }

/* 详情块 (功法、招式、法宝等) */
.xx-block { margin-top: 8px; }
.xx-block strong { color: #5c6bc0 !important; }
.xx-block p { margin: 4px 0 4px 12px !important; color: #607d8b !important; font-size: 0.95em; }

/* 角色属性区域 */
.xx-char-section { margin-bottom: 10px; }
.xx-char-name { font-weight: bold; color: #455a64 !important; font-size: 1.1em; border-left: 4px solid #78909c; padding-left: 8px; margin-bottom: 6px; background: linear-gradient(90deg,rgba(120,144,156,0.1),transparent); }
.xx-char-section p { margin: 4px 0; line-height: 1.4; }
.xx-char-section p:first-of-type strong { color: #e91e63 !important; }
.xx-divider { border: 0; height: 1px; background-image: linear-gradient(to right,rgba(0,0,0,0),rgba(120,144,156,0.3),rgba(0,0,0,0)); margin: 15px 0; }

/* 🔞 肉身私密板块 */
.xx-sex-part { background: #eceff1; border: 1px solid #cfd8dc; border-radius: 4px; padding: 8px; margin-top: 6px; }
.xx-sex-title { color: #5c6bc0 !important; font-weight: bold; margin-bottom: 4px; font-size: 0.9em; }

/* 7: 记忆模块 */
.memory-section { margin-bottom: 10px; border: 1px solid #cfd8dc; background: rgba(255,255,255,0.7); border-radius: 4px; overflow: hidden; }
.section-summary { background: #eceff1; padding: 8px; cursor: pointer; font-weight: bold; color: #546e7a !important; list-style: none; outline: none; border-bottom: 1px solid #cfd8dc; display: flex; align-items: center; }
.section-summary::-webkit-details-marker { display: none; }
.section-summary::after { content: "▼"; margin-left: auto; color: #90a4ae; font-size: 0.8em; }
details[open] > .section-summary::after { content: "▲"; }
.sum-icon { margin-right: 8px; }
.mem-count { font-size: 0.85em; font-weight: normal; opacity: 0.8; margin-left: 8px; }
.memory-content { padding: 10px; display: flex; flex-direction: column; gap: 15px; }
.mem-title { font-size: 0.9em; font-weight: bold; color: #5c6bc0 !important; text-align: center; margin-bottom: 8px; padding: 4px; background: rgba(92,107,192,0.05); border-radius: 4px; }
.table-wrap { width: 100%; overflow-x: auto; }
.mem-table { width: 100%; border-collapse: collapse; font-size: 0.85em; min-width: 400px; }
.mem-table th { background: #f0f2f5; color: #455a64; padding: 6px; border: 1px solid #cfd8dc; text-align: left; }
.mem-table td { padding: 6px; border: 1px solid #cfd8dc; color: #546e7a !important; line-height: 1.4; }
.mem-table tr:nth-child(even) { background: rgba(236,240,241,0.3); }

/* 8: 玩家选项 */
.xx-choice-box { margin-top: 20px; background: rgba(236,240,241,0.5); padding: 15px; border-radius: 6px; border: 1px solid #b0bec5; }
.xx-c-title { font-weight: bold; margin-bottom: 8px; color: #78909c !important; }
.xx-btn { background: rgba(255,255,255,0.8); border: 1px solid #b0bec5; padding: 6px 10px; margin: 4px 0; border-radius: 3px; cursor: pointer; transition: 0.2s; color: #546e7a !important; }
.xx-btn:hover { background: #78909c; color: #fff !important; border-color: #78909c; transform: translateX(3px); }
.xx-diy { border-style: dashed; color: #90a4ae !important; }


/* ========================================== */
/* === 附加美化：雾霾蓝修仙气泡与全局样式 === */
/* ========================================== */

/* 基础气泡样式 (日间模式) */
.group.relative.ml-2 .relative.inline-block,
.group.relative.ml-4 .relative.inline-block,
.chat-answer-container .relative.inline-block,
.flex .relative.inline-block {
    background-color: rgba(240, 242, 245, 0.85) !important; 
    background-image: none !important;
    backdrop-filter: blur(12px) !important;
    -webkit-backdrop-filter: blur(12px) !important;
    color: #2b2b2b !important; 
    border: 1.5px solid #b0bec5 !important;
    border-radius: 20px 8px 20px 8px !important;
    padding: 18px 22px !important;
    margin: 14px 0 !important;
    position: relative !important;
    font-family: "KaiTi", "STKaiti", "Microsoft YaHei", serif !important;
    line-height: 1.6 !important;
    box-shadow: 
        0 8px 32px rgba(176, 190, 197, 0.15),
        0 4px 16px rgba(207, 216, 220, 0.2),
        0 0 20px rgba(255, 255, 255, 0.3),
        inset 0 0 0 1px rgba(255, 255, 255, 0.4) !important;
    transform: none !important;
    transition: all 0.3s ease !important;
    overflow: hidden !important;
}

/* 去除云纹渐变，保持纯净磨砂质感 */
.group.relative.ml-2 .relative.inline-block::before,
.group.relative.ml-4 .relative.inline-block::before,
.chat-answer-container .relative.inline-block::before,
.flex .relative.inline-block::before {
    display: none !important;
}

/* 右上角装饰 - ☁ 云纹符号 */
.group.relative.ml-2 .relative.inline-block::after,
.group.relative.ml-4 .relative.inline-block::after,
.chat-answer-container .relative.inline-block::after,
.flex .relative.inline-block::after {
    content: "☁" !important;
    position: absolute !important;
    top: -15px !important;
    right: -5px !important;
    font-size: 80px !important;
    color: rgba(144, 164, 174, 0.1) !important;
    z-index: 1 !important;
    pointer-events: none !important;
    text-shadow: 0 0 20px rgba(255, 255, 255, 0.5) !important;
    line-height: 1 !important;
    transform: rotate(-10deg) !important;
}

/* 确保内容在云纹之上 */
.group.relative.ml-2 .relative.inline-block .markdown-body,
.group.relative.ml-4 .relative.inline-block .markdown-body,
.chat-answer-container .relative.inline-block .markdown-body,
.flex .relative.inline-block .markdown-body {
    position: relative !important;
    z-index: 2 !important;
    color: inherit !important; 
}

/* 气泡边框虚线与流光 */
.group.relative.ml-2 .relative.inline-block,
.group.relative.ml-4 .relative.inline-block,
.chat-answer-container .relative.inline-block,
.flex .relative.inline-block {
    border-left: 2px dashed rgba(176, 190, 197, 0.6) !important;
    border-bottom: 2px dashed rgba(176, 190, 197, 0.6) !important;
    border-top: 1.5px solid #b0bec5 !important;
    border-right: 1.5px solid #b0bec5 !important;
}
.group.relative.ml-2 .relative.inline-block .absolute.top-0,
.group.relative.ml-4 .relative.inline-block .absolute.top-0,
.chat-answer-container .relative.inline-block .absolute.top-0,
.flex .relative.inline-block .absolute.top-0 {
    background: linear-gradient(90deg, transparent, #90a4ae, #eceff1, #90a4ae, transparent) !important;
    height: 2px !important;
    border-radius: 2px !important;
    box-shadow: 0 0 8px rgba(144, 164, 174, 0.5) !important;
}

/* 夜间模式适配 (Dark Mode) */
@media (prefers-color-scheme: dark) {
    .group.relative.ml-2 .relative.inline-block,
    .group.relative.ml-4 .relative.inline-block,
    .chat-answer-container .relative.inline-block,
    .flex .relative.inline-block {
        background-color: rgba(45, 51, 54, 0.85) !important; 
        backdrop-filter: blur(12px) !important;
        -webkit-backdrop-filter: blur(12px) !important;
        color: #2b2b2b !important; 
        border-color: #546e7a !important; 
        box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2), 0 4px 16px rgba(0, 0, 0, 0.1), 0 0 20px rgba(144, 164, 174, 0.05), inset 0 0 0 1px rgba(255, 255, 255, 0.05) !important;
    }
    .group.relative.ml-2 .relative.inline-block::after,
    .group.relative.ml-4 .relative.inline-block::after,
    .chat-answer-container .relative.inline-block::after,
    .flex .relative.inline-block::after { color: rgba(255, 255, 255, 0.02) !important; text-shadow: 0 0 20px rgba(255, 255, 255, 0.05) !important; }
    .group.relative.ml-2 .relative.inline-block,
    .group.relative.ml-4 .relative.inline-block,
    .chat-answer-container .relative.inline-block,
    .flex .relative.inline-block { border-left: 2px dashed rgba(84, 110, 122, 0.6) !important; border-bottom: 2px dashed rgba(84, 110, 122, 0.6) !important; }
    .group.relative.ml-2 .relative.inline-block .absolute.top-0,
    .group.relative.ml-4 .relative.inline-block .absolute.top-0,
    .chat-answer-container .relative.inline-block .absolute.top-0,
    .flex .relative.inline-block .absolute.top-0 { background: linear-gradient(90deg, transparent, #546e7a, #90a4ae, #546e7a, transparent) !important; box-shadow: 0 0 8px rgba(84, 110, 122, 0.5) !important; }
}

/* 雾霾蓝丹药风格按钮 */
.MuiButtonBase-root.MuiButton-root, button[class*="choice"], button[class*="button"], .btn, .button, .choice-btn, .MuiButton-root.MuiButton-outlined, .MuiButton-root.MuiButton-text {
    background: radial-gradient(circle at 30% 30%, rgba(236, 239, 241, 0.95) 0%, rgba(207, 216, 220, 0.9) 100%) !important;
    color: #546e7a !important;
    border: 1px solid #cfd8dc !important;
    border-radius: 40px !important;
    padding: 6px 14px !important;
    margin: 2px !important;
    font-family: "KaiTi", "Microsoft YaHei", sans-serif !important;
    font-weight: 600 !important;
    font-size: 12px !important;
    box-shadow: 0 4px 10px rgba(176, 190, 197, 0.3), inset 0 0 10px rgba(255, 255, 255, 0.8) !important;
    transform: none !important;
    transition: all 0.3s ease !important;
    position: relative !important;
    min-width: 70px !important;
    overflow: hidden !important;
}
.MuiButtonBase-root.MuiButton-root:hover, button[class*="choice"]:hover, button[class*="button"]:hover, .btn:hover, .button:hover, .choice-btn:hover {
    background: radial-gradient(circle at 30% 30%, rgba(255, 255, 255, 1) 0%, rgba(236, 239, 241, 0.95) 100%) !important;
    color: #37474f !important;
    border-color: #90a4ae !important;
    box-shadow: 0 6px 15px rgba(176, 190, 197, 0.5), 0 0 10px rgba(144, 164, 174, 0.2), inset 0 0 15px rgba(255, 255, 255, 0.9) !important;
    transform: translateY(-2px) scale(1.03) !important;
}

/* Markdown 内容文本样式 */
.markdown-body p { color: #2b2b2b !important; }
.markdown-body strong { color: #1a1a1a !important; font-weight: 600 !important; }
.markdown-body em { color: #2b2b2b !important; font-style: italic !important; }

/* 输入框设计 - 宣纸质感 */
input[type="text"], textarea, input[type="password"] {
    background: rgba(255, 255, 255, 0.8) !important;
    color: #455a64 !important;
    border: 1.5px solid #cfd8dc !important;
    border-radius: 8px !important;
    padding: 12px 16px !important;
    font-family: "KaiTi", "Microsoft YaHei", serif !important;
    box-shadow: inset 0 0 10px rgba(176, 190, 197, 0.1) !important;
    backdrop-filter: blur(5px) !important;
}
input[type="text"]:focus, textarea:focus { outline: none !important; border-color: #90a4ae !important; box-shadow: inset 0 0 10px rgba(176, 190, 197, 0.2), 0 0 15px rgba(144, 164, 174, 0.2) !important; background: rgba(255, 255, 255, 0.95) !important; }

/* ☁️ 修仙主题加载动画 - 天机推演 */
.flex.items-center.justify-center.w-6.h-5 { width: auto !important; height: auto !important; min-width: 180px !important; padding: 12px 20px !important; background: linear-gradient(135deg, #eceff1 0%, #cfd8dc 100%) !important; border: 1px solid #b0bec5 !important; border-radius: 12px !important; box-shadow: 0 6px 20px rgba(176, 190, 197, 0.3), inset 0 0 0 1px rgba(255, 255, 255, 0.5) !important; position: relative !important; font-family: "KaiTi", serif !important; display: flex !important; align-items: center !important; justify-content: center !important; overflow: hidden !important; }
.style_dot-flashing__8L91Q.style_text__zGhNq { display: none !important; }
.flex.items-center.justify-center.w-6.h-5::before { content: "正在推演天机" !important; font-size: 15px !important; color: #546e7a !important; animation: wave-text 6s ease-in-out infinite !important; }
.flex.items-center.justify-center.w-6.h-5::after { content: "……" !important; color: #78909c !important; font-weight: bold !important; animation: wave-dots 5s ease-in-out infinite !important; }

/* 状态栏 (兼容原版) - 雾霾蓝风格 */
.status-container { border: 1px solid #cfd8dc !important; border-radius: 6px !important; margin: 14px 0 !important; background: #f5f7fa !important; box-shadow: 0 4px 15px rgba(176, 190, 197, 0.2) !important; color: #546e7a !important; }
.status-summary { background: #eceff1 !important; color: #455a64 !important; border-bottom: 1px solid #cfd8dc !important; font-family: "KaiTi", serif !important; }
.status-summary::before { content: "✦" !important; color: #90a4ae !important; transform: rotate(0deg) !important; }
.status-container[open] .status-summary::before { transform: rotate(45deg) !important; }
.status-content { background: #fafafa !important; color: #607d8b !important; }
.status-content p { border-left: 2px solid #cfd8dc !important; background: rgba(236, 239, 241, 0.3) !important; color: #546e7a !important; }

/* 动画定义 */
@keyframes wave-text { 0%, 100% { transform: translateY(0); opacity: 0.8; } 50% { transform: translateY(-2px); opacity: 1; } }
@keyframes wave-dots { 0%, 100% { opacity: 0.5; } 50% { opacity: 1; } }

/* 📜 滚动条全域美化 (玉石质感) */
*::-webkit-scrollbar { width: 8px !important; height: 8px !important; background: transparent !important; }
*::-webkit-scrollbar-track { background: rgba(245, 247, 250, 0.5) !important; border-radius: 4px !important; }
*::-webkit-scrollbar-thumb { background-color: #cfd8dc !important; border: 2px solid transparent !important; background-clip: content-box !important; border-radius: 10px !important; box-shadow: inset 0 0 6px rgba(176, 190, 197, 0.3) !important; }
*::-webkit-scrollbar-thumb:hover { background-color: #90a4ae !important; border: 1px solid transparent !important; }
html { scrollbar-width: thin !important; scrollbar-color: #cfd8dc rgba(245, 247, 250, 0.5) !important; }', '<!DOCTYPE html>
