<script>
function showPage(pageNum) {
document.querySelectorAll(''.page'').forEach(p => p.classList.remove(''active''));
document.getElementById(''page'' + pageNum).classList.add(''active'');
if(pageNum === 5) {
updateSects();
}
}
const elements = [
{name: ''金'', class: ''root-gold''}, 
{name: ''木'', class: ''root-wood''}, 
{name: ''水'', class: ''root-water''}, 
{name: ''火'', class: ''root-fire''}, 
{name: ''土'', class: ''root-earth''}
];
const variantElements = [
{name: ''风'', class: ''root-wind''}, 
{name: ''冰'', class: ''root-ice''}, 
{name: ''雷'', class: ''root-thunder''}
];
let currentRoot = "";
let selectedTalents = [];
function rollRoot() {
const r = Math.random();
let rootType = "";
let roots = [];
let displayHTML = "";
if (r < 0.01) {
const el = variantElements[Math.floor(Math.random() * variantElements.length)];
displayHTML = `<span class="${el.class}">【变异天灵根 · ${el.name}】</span>`;
rootType = `变异天灵根（${el.name}）`;
} else {
let count = 5;
if (r < 0.05) count = 1;
else if (r < 0.20) count = 2;
else if (r < 0.50) count = 3;
else if (r < 0.80) count = 4;
const shuffled = [...elements].sort(() => 0.5 - Math.random());
const selected = shuffled.slice(0, count);
let nameStr = "";
if(count === 1) nameStr = "天灵根";
else if(count === 2) nameStr = "真灵根";
else if(count === 3) nameStr = "伪灵根";
else if(count === 4) nameStr = "杂灵根";
else nameStr = "废灵根";
displayHTML += `<span>${nameStr}：</span>`;
let typeArr = [];
selected.forEach(el => {
displayHTML += `<span class="${el.class}">${el.name} </span>`;
typeArr.push(el.name);
});
rootType = `${nameStr}（${typeArr.join('''')}）`;
}
document.getElementById(''rootResult'').innerHTML = displayHTML;
currentRoot = rootType;
}
const talentPool = {
''剑修'': [
{name: ''剑心通明'', desc: ''剑道悟性极高，修行一日千里''},
{name: ''天生剑骨'', desc: ''根骨如剑，天生适合修习剑法''},
{name: ''剑意纵横'', desc: ''出手自带剑意，威力倍增''},
{name: ''无上剑胎'', desc: ''以身为剑，可孕育本命神剑''},
{name: ''剑道独尊'', desc: ''唯剑唯我，万法皆可破''}
],
''丹修'': [
{name: ''神农百草'', desc: ''尝百草而不死，识药性如神''},
{name: ''丹火纯青'', desc: ''控火之术登峰造极，成丹率高''},
{name: ''药灵圣体'', desc: ''体质亲和草木，炼药事半功倍''},
{name: ''丹道宗师'', desc: ''天生知晓药理，可创绝世丹方''},
{name: ''妙手回春'', desc: ''医术通神，丹药效果翻倍''}
],
''阵修'': [
{name: ''阵法天成'', desc: ''举手投足皆成阵，无需阵盘''},
{name: ''玲珑棋心'', desc: ''推演能力极强，可破万阵''},
{name: ''天地为盘'', desc: ''可借天地大势布阵，威力无穷''},
{name: ''阵道本源'', desc: ''直指阵法本质，学习速度极快''},
{name: ''破妄之眼'', desc: ''看破虚妄，一切幻阵无效''}
],
''符修'': [
{name: ''通天符箓'', desc: ''无需符纸，凌空画符''},
{name: ''笔落惊风'', desc: ''符成引动天地异象，威力巨大''},
{name: ''符道通神'', desc: ''低阶符箓也能发挥高阶威能''},
{name: ''虚空凝符'', desc: ''心念一动，符箓自成''},
