.root-ice { color: #b3e5fc; }
.root-thunder { color: #9c27b0; }
.talent-grid {
display: grid;
grid-template-columns: repeat(2, 1fr);
gap: 15px;
margin-top: 20px;
}
.talent-card {
background: rgba(255, 255, 255, 0.1);
padding: 10px;
border-radius: 5px;
cursor: pointer;
