text-align: center;
}
.talent-card:hover {
background: rgba(255, 255, 255, 0.2);
}
.talent-card.selected {
background: rgba(162, 217, 255, 0.3);
border-color: #a2d9ff;
box-shadow: 0 0 10px rgba(162, 217, 255, 0.3);
}
.talent-name {
font-weight: bold;
font-size: 1.1em;
color: #fff;
margin-bottom: 5px;
}
.talent-desc {
