INSERT INTO plaza_cards (id, deck_id, title, badge, badge_color, author, "desc", rating, tags_json, heat, order_index, cover_image, image_tag, badge_type, is_featured, category, created_at) VALUES ('deck_twin_idols_fiancee', 'deck_twin_idols_fiancee', '国民级顶流双胞胎偶像转校生是我的未婚妻？', '国民双子 · 婚约转校', 'bg-purple-950/90 text-purple-300 border-purple-600/60', '吃花生的瓜子', '夏梦瑶与夏梦璃，舞台上风靡全国的顶流双子偶像，竟同时空降转校到了你的班级，并双双宣布是你的法定未婚妻！端庄清冷的姐姐与俏皮腹黑的小恶魔妹妹，两张绝美相同的容颜下，拉开了一场极限修罗场争宠战。', '9.9', '["双胞胎", "偶像", "未婚妻", "修罗场", "校园", "后宫", "二次元"]', '124.6k 玩过 · 39.2k 深度', 2, 'https://catai.wiki/4e84457e-3995-4aa8-7443-aa9e61ae8400/cover', NULL, 'fire', 1, '校园', '2026-09-16 11:22:22') ON CONFLICT (title) DO NOTHING;
INSERT INTO plaza_cards (id, deck_id, title, badge, badge_color, author, "desc", rating, tags_json, heat, order_index, cover_image, image_tag, badge_type, is_featured, category, created_at) VALUES ('deck_brother_loli_girlfriend', 'deck_brother_loli_girlfriend', '兄弟的巨乳萝莉女友？是我的了', '背德协奏 · 兄弟女友', 'bg-amber-950/90 text-amber-300 border-amber-600/60', '倒霉狐', '你受好兄弟之托前往空无一人的隔音音乐室送钥匙，却在门缝后撞破了兄弟平时清纯可人的娇小女友许晓娜，正瘫坐在琴凳上满脸潮红地自我慰藉。手握致命秘密与羞耻把柄的你，将步步击溃她的心理防线。', '9.8', '["NTR", "巨乳萝莉", "调教", "凌辱", "背德", "破甲", "开局即可色"]', '98.7k 玩过 · 31.5k 深度', 3, 'https://catai.wiki/87c12f5e-6807-4376-6c17-d4ec43aec500/cover', NULL, 'fire', 1, '都市', '2026-09-16 11:22:22') ON CONFLICT (title) DO NOTHING;
